        "everyday|2:1|4|text": "ਰਵੀ ਪੁਣੇ ਦੀ ਇੱਕ ਕੰਪਨੀ ਤੋਂ ਇੱਕ ਜ਼ਰੂਰੀ ਕਾਲ ਦੀ ਉਡੀਕ ਕਰ ਰਿਹਾ ਸੀ। ਉਸ ਦਾ ਫ਼ੋਨ ਵੱਜਿਆ, ਪਰ ਫ਼ੋਨ ਕਰਨ ਵਾਲੇ ਨੇ ਸੁਰੇਸ਼ ਨਾਂ ਦੇ ਕਿਸੇ ਬੰਦੇ ਬਾਰੇ ਪੁੱਛਿਆ। ਰਵੀ ਨੇ ਨਿਮਰਤਾ ਨਾਲ ਦੱਸਿਆ ਕਿ ਉਸ ਨੇ ਗ਼ਲਤ ਨੰਬਰ ਮਿਲਾਇਆ ਹੈ। ਕੁਝ ਮਿੰਟਾਂ ਬਾਅਦ, ਜਦੋਂ ਉਹ ਲਿਫ਼ਟ ਵਿੱਚ ਸੀ, ਉਸ ਨੂੰ ਕੰਪਨੀ ਤੋਂ ਇੱਕ ਮਿਸਡ ਕਾਲ ਆਈ। ਉਸ ਨੇ ਝੱਟ ਨੰਬਰ ਮਿਲਾਇਆ, ਪਰ ਲਾਈਨ ਬਿਜ਼ੀ ਸੀ। ਫਿਰ ਉਸ ਦੀ ਬੈਟਰੀ ਪੰਜ ਪ੍ਰਤੀਸ਼ਤ ਰਹਿ ਗਈ, ਅਤੇ ਚਾਰਜਰ ਉਹ ਘਰ ਹੀ ਭੁੱਲ ਆਇਆ ਸੀ। ਇੱਕ ਭਲੇ ਦੁਕਾਨਦਾਰ ਨੇ ਉਸ ਨੂੰ ਆਪਣਾ ਚਾਰਜਰ ਵਰਤਣ ਦਿੱਤਾ, ਅਤੇ ਆਖ਼ਰਕਾਰ ਉਸ ਦੀ ਗੱਲ ਹੋ ਗਈ। ਮੈਨੇਜਰ ਹੱਸ ਪਈ ਅਤੇ ਬੋਲੀ ਕਿ ਉਹ ਤਾਂ ਖ਼ੁਦ ਉਸ ਨੂੰ ਵਾਪਸ ਫ਼ੋਨ ਕਰਨ ਹੀ ਵਾਲੀ ਸੀ।",
        "everyday|2:1|4|q0": "ਪਹਿਲੇ ਫ਼ੋਨ ਕਰਨ ਵਾਲੇ ਨੇ ਕਿਸ ਬਾਰੇ ਪੁੱਛਿਆ?",
