        "everyday|2:1|5|l0": "ਨਮਸਕਾਰ, ਕੋਸਟਲ ਟਰੈਵਲਜ਼, ਮੈਂ ਪੂਜਾ ਬੋਲ ਰਹੀ ਹਾਂ। ਦੱਸੋ, ਮੈਂ ਤੁਹਾਡੀ ਕੀ ਮਦਦ ਕਰ ਸਕਦੀ ਹਾਂ?",
