        "everyday|2:1|5|l3": "ਹਾਂ ਜੀ। ਕੀ ਤੁਸੀਂ ਉਨ੍ਹਾਂ ਨੂੰ ਕਹਿ ਸਕਦੇ ਹੋ ਕਿ ਗੋਆ ਟ੍ਰਿਪ ਬਾਰੇ ਮੈਨੂੰ ਵਾਪਸ ਫ਼ੋਨ ਕਰਨ?",
        "everyday|2:1|5|l4": "ਮਾਫ਼ ਕਰਨਾ, ਲਾਈਨ ਬਹੁਤ ਖ਼ਰਾਬ ਹੈ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਦੱਸ ਸਕਦੇ ਹੋ?",
        "everyday|2:1|5|l5": "ਜ਼ਰੂਰ। ਕਿਰਪਾ ਕਰਕੇ ਮਿਸਟਰ ਕਾਮਥ ਨੂੰ ਕਹਿਣਾ ਕਿ ਉਹ ਗੋਆ ਟ੍ਰਿਪ ਬਾਰੇ ਮੈਨੂੰ ਵਾਪਸ ਫ਼ੋਨ ਕਰਨ।",
        "everyday|2:1|5|l6": "ਬਿਲਕੁਲ। ਤੁਹਾਡੇ ਨਾਲ ਕਿਸ ਨੰਬਰ ਉੱਤੇ ਸੰਪਰਕ ਕਰਨਾ ਸਭ ਤੋਂ ਵਧੀਆ ਰਹੇਗਾ?",
        "everyday|2:1|5|l7": "ਤੁਸੀਂ ਮੈਨੂੰ 98450 12376 ਉੱਤੇ ਫ਼ੋਨ ਕਰ ਸਕਦੇ ਹੋ।",
        "everyday|2:1|5|l8": "ਮੈਂ ਦੁਹਰਾ ਦਿੰਦੀ ਹਾਂ: 98450 12376। ਮੈਂ ਪੱਕਾ ਕਰਾਂਗੀ ਕਿ ਉਨ੍ਹਾਂ ਨੂੰ ਸੁਨੇਹਾ ਮਿਲ ਜਾਵੇ।",
