        "everyday|3:1|1|p0": "ਮੈਂ ਆਪਣੀ ਧੀ ਦੇ ਨਾਂ ਉੱਤੇ ਬੱਚਤ ਖਾਤਾ ਖੋਲ੍ਹਣਾ ਚਾਹੁੰਦਾ ਹਾਂ।",
