        "everyday|3:1|3|p0": "ਏਟੀਐੱਮ ਨੇ ਮੇਰਾ ਡੈਬਿਟ ਕਾਰਡ ਰੱਖ ਲਿਆ, ਇਸ ਲਈ ਮੈਨੂੰ ਇਹ ਫ਼ੌਰਨ ਬਲੌਕ ਕਰਵਾਉਣਾ ਪਵੇਗਾ।",
        "everyday|3:1|3|p1": "ਆਪਣਾ ਪਿੰਨ ਕਦੇ ਕਿਸੇ ਨੂੰ ਨਾ ਦੱਸੋ, ਭਾਵੇਂ ਉਹ ਕਹਿਣ ਕਿ ਉਹ ਬੈਂਕ ਤੋਂ ਹਨ।",
        "everyday|3:1|3|p2": "ਮੈਂ ਕਿਰਾਇਆ ਯੂਪੀਆਈ ਰਾਹੀਂ ਭਰਿਆ, ਪਰ ਹਾਲੇ ਤੱਕ ਮਾਲਕ ਕੋਲ ਨਹੀਂ ਪਹੁੰਚਿਆ।",
