        "everyday|3:1|3|p4": "ਕਿਰਪਾ ਕਰਕੇ ਆਪਣੇ ਆਧਾਰ ਅਤੇ ਪੈਨ ਨਾਲ ਕੇਵਾਈਸੀ ਪੂਰੀ ਕਰੋ, ਨਹੀਂ ਤਾਂ ਖਾਤਾ ਬੰਦ ਹੋ ਸਕਦਾ ਹੈ।",
        "everyday|3:1|4|title": "ਪਹਿਲਾ ਬੈਂਕ ਖਾਤਾ",
        "everyday|3:1|4|text": "ਸੰਜਨਾ ਨੂੰ ਮੰਗਲੁਰੂ ਵਿੱਚ ਪਹਿਲੀ ਨੌਕਰੀ ਮਿਲੀ, ਅਤੇ ਉਹ ਤਨਖ਼ਾਹ ਖਾਤਾ ਖੋਲ੍ਹਣ ਲਈ ਨੇੜਲੇ ਬੈਂਕ ਗਈ। ਕੇਵਾਈਸੀ ਲਈ ਅਫ਼ਸਰ ਨੇ ਉਸ ਦਾ ਆਧਾਰ ਕਾਰਡ, ਪੈਨ ਕਾਰਡ ਅਤੇ ਦੋ ਫ਼ੋਟੋਆਂ ਮੰਗੀਆਂ। ਸੰਜਨਾ ਨੇ ਫ਼ਾਰਮ ਭਰਿਆ ਅਤੇ ਦੋ ਹਜ਼ਾਰ ਰੁਪਏ ਜਮ੍ਹਾਂ ਕਰਾਏ। ਇੱਕ ਹਫ਼ਤੇ ਬਾਅਦ ਉਸ ਨੂੰ ਪਾਸਬੁੱਕ, ਚੈੱਕ ਬੁੱਕ ਅਤੇ ਡੈਬਿਟ ਕਾਰਡ ਮਿਲ ਗਏ। ਅਫ਼ਸਰ ਨੇ ਉਸ ਨੂੰ ਕਿਹਾ ਕਿ ਏਟੀਐੱਮ ਉੱਤੇ ਨਵਾਂ ਪਿੰਨ ਬਣਾਵੇ ਅਤੇ ਉਹ ਕਦੇ ਕਿਸੇ ਨੂੰ ਨਾ ਦੱਸੇ। ਉਸ ਨੇ ਆਪਣੇ ਫ਼ੋਨ ਉੱਤੇ ਖਾਤੇ ਨੂੰ ਯੂਪੀਆਈ ਨਾਲ ਵੀ ਜੋੜ ਲਿਆ। ਹੁਣ ਉਹ ਹਰ ਮਹੀਨੇ ਆਪਣਾ ਬੈਲੇਂਸ ਦੇਖਦੀ ਹੈ ਅਤੇ ਵਿਆਜ ਕਮਾਉਣ ਲਈ ਕੁਝ ਪੈਸੇ ਐੱਫ਼ਡੀ ਵਿੱਚ ਰੱਖਦੀ ਹੈ।",
