        "everyday|3:1|5|scenario": "ਫ਼ਰਹਾਨ ਪੁਣੇ ਵਿੱਚ ਆਪਣੇ ਬੈਂਕ ਜਾਂਦਾ ਹੈ ਕਿਉਂਕਿ ਇੱਕ ਯੂਪੀਆਈ ਪੇਮੈਂਟ ਫ਼ੇਲ੍ਹ ਹੋ ਗਈ, ਅਤੇ ਹੈਲਪ ਡੈਸਕ ਉੱਤੇ ਰਿਤੂ ਨਾਲ ਗੱਲ ਕਰਦਾ ਹੈ।",
        "everyday|3:1|5|l0": "ਨਮਸਕਾਰ ਸਰ। ਦੱਸੋ, ਅੱਜ ਮੈਂ ਤੁਹਾਡੀ ਕੀ ਮਦਦ ਕਰ ਸਕਦੀ ਹਾਂ?",
        "everyday|3:1|5|l1": "ਨਮਸਕਾਰ। ਕੱਲ੍ਹ ਮੈਂ ਯੂਪੀਆਈ ਰਾਹੀਂ ਤਿੰਨ ਹਜ਼ਾਰ ਰੁਪਏ ਭੇਜੇ, ਪਰ ਪੇਮੈਂਟ ਫ਼ੇਲ੍ਹ ਹੋ ਗਈ।",
        "everyday|3:1|5|l2": "ਅੱਛਾ। ਕੀ ਪੈਸੇ ਤੁਹਾਡੇ ਖਾਤੇ ਵਿੱਚੋਂ ਕੱਟੇ ਗਏ ਸਨ?",
        "everyday|3:1|5|l3": "ਹਾਂ। ਮੇਰਾ ਬੈਲੇਂਸ ਘਟ ਗਿਆ, ਪਰ ਦੁਕਾਨ ਨੂੰ ਪੈਸੇ ਮਿਲੇ ਹੀ ਨਹੀਂ।",
        "everyday|3:1|5|l4": "ਫ਼ਿਕਰ ਨਾ ਕਰੋ। ਫ਼ੇਲ੍ਹ ਹੋਈਆਂ ਪੇਮੈਂਟਾਂ ਦੇ ਪੈਸੇ ਆਮ ਤੌਰ 'ਤੇ ਤਿੰਨ ਕੰਮਕਾਜੀ ਦਿਨਾਂ ਵਿੱਚ ਵਾਪਸ ਆ ਜਾਂਦੇ ਹਨ।",
        "everyday|3:1|5|l5": "ਚਲੋ, ਤਸੱਲੀ ਹੋਈ। ਹੁਣ ਮੈਂ ਇੱਥੇ ਹਾਂ ਤਾਂ ਕੀ ਤੁਸੀਂ ਮੈਨੂੰ ਪੜ੍ਹਾਈ ਦੇ ਕਰਜ਼ਿਆਂ ਬਾਰੇ ਦੱਸ ਸਕਦੇ ਹੋ?",
        "everyday|3:1|5|l6": "ਜ਼ਰੂਰ। ਵਿਆਜ ਦੀ ਦਰ ਲਗਭਗ ਨੌਂ ਪ੍ਰਤੀਸ਼ਤ ਹੈ, ਅਤੇ ਤੁਹਾਡੀ ਕੇਵਾਈਸੀ ਪੂਰੀ ਹੋਣੀ ਚਾਹੀਦੀ ਹੈ।",
        "everyday|3:1|5|l7": "ਮੇਰੇ ਖ਼ਿਆਲ ਵਿੱਚ ਪੂਰੀ ਹੈ। ਮੈਂ ਪਿਛਲੇ ਸਾਲ ਆਪਣੇ ਆਧਾਰ ਦੀ ਜਾਣਕਾਰੀ ਅੱਪਡੇਟ ਕਰਾਈ ਸੀ।",
        "everyday|3:1|5|l8": "ਮੈਂ ਦੇਖਦੀ ਹਾਂ। ਹਾਂ, ਸਭ ਠੀਕ ਹੈ। ਇਹ ਰਿਹਾ ਕਰਜ਼ੇ ਦਾ ਫ਼ਾਰਮ ਅਤੇ ਦਸਤਾਵੇਜ਼ਾਂ ਦੀ ਸੂਚੀ।",
        "everyday|3:1|5|l9": "ਬਹੁਤ-ਬਹੁਤ ਸ਼ੁਕਰੀਆ। ਤੁਸੀਂ ਬਹੁਤ ਮਦਦ ਕੀਤੀ।",
        "everyday|3:1|5|q0": "ਫ਼ਰਹਾਨ ਦੀ ਪੇਮੈਂਟ ਵਿੱਚ ਕੀ ਗੜਬੜ ਹੋਈ?",
        "everyday|3:1|5|q0o0": "ਪੇਮੈਂਟ ਫ਼ੇਲ੍ਹ ਹੋ ਗਈ, ਪਰ ਪੈਸੇ ਉਸ ਦੇ ਖਾਤੇ ਵਿੱਚੋਂ ਕੱਟੇ ਗਏ",
        "everyday|3:1|5|q0o1": "ਉਸ ਨੇ ਦੁਕਾਨ ਨੂੰ ਦੋ ਵਾਰ ਪੈਸੇ ਦੇ ਦਿੱਤੇ",
        "everyday|3:1|5|q0o2": "ਉਹ ਆਪਣਾ ਪਿੰਨ ਭੁੱਲ ਗਿਆ",
        "everyday|3:1|5|q0o3": "ਦੁਕਾਨ ਨੇ ਪੈਸੇ ਵਾਪਸ ਭੇਜ ਦਿੱਤੇ",
        "everyday|3:1|5|q1": "ਪੈਸੇ ਆਮ ਤੌਰ 'ਤੇ ਕਦੋਂ ਵਾਪਸ ਆਉਣਗੇ?",
        "everyday|3:1|5|q1o0": "ਤਿੰਨ ਕੰਮਕਾਜੀ ਦਿਨਾਂ ਵਿੱਚ",
        "everyday|3:1|5|q1o1": "ਇੱਕ ਘੰਟੇ ਵਿੱਚ",
        "everyday|3:1|5|q1o2": "ਇੱਕ ਮਹੀਨੇ ਬਾਅਦ",
        "everyday|3:1|5|q1o3": "ਸਿਰਫ਼ ਸ਼ਿਕਾਇਤ ਕਰਨ ਤੋਂ ਬਾਅਦ",
        "everyday|3:1|5|q2": "ਫ਼ਰਹਾਨ ਹੋਰ ਕਿਸ ਚੀਜ਼ ਬਾਰੇ ਪੁੱਛਦਾ ਹੈ?",
        "everyday|3:1|5|q2o0": "ਪੜ੍ਹਾਈ ਦੇ ਕਰਜ਼ਿਆਂ ਬਾਰੇ",
