        "everyday|4:1|0|w0": "ਮੀਨੂ",
        "everyday|4:1|0|w1": "ਵੇਟਰ",
        "everyday|4:1|0|w2": "ਸਟਾਰਟਰ",
        "everyday|4:1|0|w3": "ਮੁੱਖ ਖਾਣਾ",
        "everyday|4:1|0|w4": "ਮਿੱਠਾ",
        "everyday|4:1|0|w5": "ਨੈਪਕਿਨ",
        "everyday|4:1|1|p0": "ਸੁਣੋ ਜੀ, ਕਿਰਪਾ ਕਰਕੇ ਸਾਨੂੰ ਮੀਨੂ ਅਤੇ ਥੋੜ੍ਹਾ ਪਾਣੀ ਦੇ ਦਿਓਗੇ?",
        "everyday|4:1|1|p1": "ਵੇਟਰ ਨੇ ਨੀਰ ਡੋਸਾ ਖਾਣ ਦੀ ਸਲਾਹ ਦਿੱਤੀ, ਇਸ ਲਈ ਅਸੀਂ ਦੋ ਪਲੇਟਾਂ ਮੰਗਵਾਈਆਂ।",
        "everyday|4:1|1|p2": "ਕੀ ਅਸੀਂ ਇੱਕ ਸਟਾਰਟਰ ਮਿਲ ਕੇ ਖਾਈਏ ਅਤੇ ਫਿਰ ਆਪੋ-ਆਪਣਾ ਮੁੱਖ ਖਾਣਾ ਮੰਗਵਾਈਏ?",
        "everyday|4:1|1|p3": "ਮੇਰਾ ਪੇਟ ਭਰ ਗਿਆ ਹੈ, ਮਿੱਠੇ ਦੀ ਥਾਂ ਨਹੀਂ, ਪਰ ਇੱਕ ਫ਼ਿਲਟਰ ਕੌਫ਼ੀ ਜ਼ਰੂਰ ਪੀਵਾਂਗਾ।",
        "everyday|4:1|1|p4": "ਕੀ ਤੁਸੀਂ ਕੁਝ ਵਾਧੂ ਨੈਪਕਿਨ ਅਤੇ ਮੇਰੇ ਪੁੱਤ ਲਈ ਇੱਕ ਛੋਟਾ ਚਮਚ ਲਿਆ ਸਕਦੇ ਹੋ?",
        "everyday|4:1|2|w0": "ਸਮੱਗਰੀ",
        "everyday|4:1|2|w1": "ਸ਼ਾਕਾਹਾਰੀ",
        "everyday|4:1|2|w2": "ਤਿੱਖਾ",
        "everyday|4:1|2|w3": "ਪਾਰਸਲ",
        "everyday|4:1|2|w4": "ਟਿੱਪ",
        "everyday|4:1|2|w5": "ਹਿੱਸਾ",
        "everyday|4:1|3|p0": "ਮੈਨੂੰ ਗਿਰੀਆਂ ਤੋਂ ਐਲਰਜੀ ਹੈ, ਇਸ ਲਈ ਕੀ ਤੁਸੀਂ ਇਸ ਕਰੀ ਦੀ ਸਮੱਗਰੀ ਦੇਖ ਸਕਦੇ ਹੋ?",
        "everyday|4:1|3|p1": "ਅਸੀਂ ਸਾਰੇ ਸ਼ਾਕਾਹਾਰੀ ਹਾਂ, ਇਸ ਲਈ ਕਿਰਪਾ ਕਰਕੇ ਧਿਆਨ ਰੱਖਣਾ ਕਿ ਕਿਸੇ ਵਿੱਚ ਵੀ ਆਂਡਾ ਨਾ ਹੋਵੇ।",
        "everyday|4:1|3|p2": "ਕੀ ਤੁਸੀਂ ਇਸ ਨੂੰ ਘੱਟ ਤਿੱਖਾ ਬਣਾ ਸਕਦੇ ਹੋ? ਮੇਰਾ ਪੁੱਤ ਬਹੁਤੀ ਮਿਰਚ ਨਹੀਂ ਖਾ ਸਕਦਾ।",
        "everyday|4:1|3|p3": "ਇੱਥੇ ਹਿੱਸੇ ਬਹੁਤ ਵੱਡੇ ਹਨ, ਇਸ ਲਈ ਕੀ ਤੁਸੀਂ ਬਚਿਆ ਹੋਇਆ ਖਾਣਾ ਪਾਰਸਲ ਕਰ ਦਿਓਗੇ?",
        "everyday|4:1|3|p4": "ਬਿੱਲ ਵਿੱਚ ਸਰਵਿਸ ਚਾਰਜ ਪਹਿਲਾਂ ਹੀ ਜੁੜਿਆ ਹੋਇਆ ਹੈ, ਇਸ ਲਈ ਸਾਨੂੰ ਟਿੱਪ ਦੇਣ ਦੀ ਲੋੜ ਨਹੀਂ।",
        "everyday|4:1|4|title": "ਉਡੁਪੀ ਵਿੱਚ ਜਨਮਦਿਨ ਦਾ ਖਾਣਾ",
        "everyday|4:1|4|text": "ਆਪਣੀ ਦਾਦੀ ਦੇ ਅੱਸੀਵੇਂ ਜਨਮਦਿਨ ਲਈ ਕਿਰਨ ਨੇ ਉਡੁਪੀ ਦੇ ਇੱਕ ਮਸ਼ਹੂਰ ਰੈਸਟੋਰੈਂਟ ਵਿੱਚ ਮੇਜ਼ ਬੁੱਕ ਕੀਤਾ। ਵੇਟਰ ਮੀਨੂ ਲੈ ਕੇ ਆਇਆ ਅਤੇ ਸਟਾਰਟਰ ਵਜੋਂ ਪਨੀਰ ਟਿੱਕਾ ਸੁਝਾਇਆ। ਕਿਰਨ ਦੀ ਚਚੇਰੀ ਭੈਣ ਨਿਸ਼ਾ ਨੂੰ ਮੂੰਗਫਲੀ ਤੋਂ ਐਲਰਜੀ ਹੈ, ਇਸ ਲਈ ਕਿਰਨ ਨੇ ਵੇਟਰ ਨੂੰ ਹਰ ਪਕਵਾਨ ਧਿਆਨ ਨਾਲ ਦੇਖਣ ਲਈ ਕਿਹਾ। ਦਾਦੀ ਆਪਣਾ ਮੁੱਖ ਖਾਣਾ ਘੱਟ ਤਿੱਖਾ ਚਾਹੁੰਦੀ ਸੀ, ਅਤੇ ਰਸੋਈਏ ਨੇ ਖ਼ੁਸ਼ੀ-ਖ਼ੁਸ਼ੀ ਹਾਮੀ ਭਰ ਦਿੱਤੀ। ਮਿੱਠੇ ਵਿੱਚ ਸਾਰੇ ਪਰਿਵਾਰ ਨੇ ਮਿਲ ਕੇ ਇੱਕ ਵੱਡੀ ਗਡਬਡ ਆਈਸਕ੍ਰੀਮ ਖਾਧੀ। ਜਦੋਂ ਬਿੱਲ ਆਇਆ, ਕਿਰਨ ਨੇ ਦੇਖਿਆ ਕਿ ਪੰਜ ਪ੍ਰਤੀਸ਼ਤ ਸਰਵਿਸ ਚਾਰਜ ਪਹਿਲਾਂ ਹੀ ਜੁੜਿਆ ਹੋਇਆ ਸੀ। ਫਿਰ ਵੀ ਉਸ ਨੇ ਥੋੜ੍ਹੀ ਜਿਹੀ ਟਿੱਪ ਛੱਡੀ, ਕਿਉਂਕਿ ਵੇਟਰ ਨੇ ਉਨ੍ਹਾਂ ਨਾਲ ਬਹੁਤ ਸਬਰ ਰੱਖਿਆ ਸੀ। ਬਚੀਆਂ ਹੋਈਆਂ ਰੋਟੀਆਂ ਉਹ ਪਾਰਸਲ ਕਰਵਾ ਕੇ ਘਰ ਲੈ ਗਏ।",
        "everyday|4:1|4|q0": "ਕਿਰਨ ਨੇ ਵੇਟਰ ਨੂੰ ਹਰ ਪਕਵਾਨ ਦੇਖਣ ਲਈ ਕਿਉਂ ਕਿਹਾ?",
        "everyday|4:1|4|q0o0": "ਉਸ ਦੀ ਚਚੇਰੀ ਭੈਣ ਨੂੰ ਮੂੰਗਫਲੀ ਤੋਂ ਐਲਰਜੀ ਹੈ",
