        "everyday|4:1|4|q1": "ਪਰਿਵਾਰ ਨੇ ਮਿੱਠੇ ਵਿੱਚ ਮਿਲ ਕੇ ਕੀ ਖਾਧਾ?",
        "everyday|4:1|4|q1o0": "ਗਡਬਡ ਆਈਸਕ੍ਰੀਮ",
