        "everyday|6:1|0|w0": "ਪਲੇਟਫ਼ਾਰਮ",
        "everyday|6:1|0|w1": "ਬਰਥ",
        "everyday|6:1|0|w2": "ਵੇਟਿੰਗ ਲਿਸਟ",
        "everyday|6:1|0|w3": "ਰਿਜ਼ਰਵੇਸ਼ਨ",
        "everyday|6:1|0|w4": "ਕਿਰਾਇਆ",
        "everyday|6:1|0|w5": "ਡੱਬਾ",
        "everyday|6:1|1|p0": "ਚਾਲੁਕਿਆ ਐਕਸਪ੍ਰੈੱਸ ਕਿਹੜੇ ਪਲੇਟਫ਼ਾਰਮ ਤੋਂ ਚੱਲਦੀ ਹੈ?",
        "everyday|6:1|1|p1": "ਮੈਨੂੰ ਹੇਠਲੀ ਬਰਥ ਚਾਹੀਦੀ ਹੈ, ਕਿਉਂਕਿ ਮੇਰੇ ਪਿਤਾ ਜੀ ਨੂੰ ਉੱਪਰ ਚੜ੍ਹਨਾ ਔਖਾ ਲੱਗਦਾ ਹੈ।",
        "everyday|6:1|1|p2": "ਸਾਡੀਆਂ ਟਿਕਟਾਂ ਹਾਲੇ ਵੇਟਿੰਗ ਲਿਸਟ ਵਿੱਚ ਹਨ, ਇਸ ਲਈ ਸ਼ਾਇਦ ਸਾਨੂੰ ਸੀਟਾਂ ਨਾ ਮਿਲਣ।",
        "everyday|6:1|1|p3": "ਤੁਹਾਨੂੰ ਦੀਵਾਲੀ ਤੋਂ ਘੱਟੋ-ਘੱਟ ਇੱਕ ਮਹੀਨਾ ਪਹਿਲਾਂ ਰਿਜ਼ਰਵੇਸ਼ਨ ਕਰਵਾ ਲੈਣੀ ਚਾਹੀਦੀ ਹੈ।",
        "everyday|6:1|1|p4": "ਪੁਣੇ ਤੱਕ ਸਲੀਪਰ ਡੱਬੇ ਦਾ ਕਿਰਾਇਆ ਲਗਭਗ ਛੇ ਸੌ ਰੁਪਏ ਹੈ।",
        "everyday|6:1|2|w0": "ਦੇਰੀ",
        "everyday|6:1|2|w1": "ਰੱਦ ਕਰਨਾ",
        "everyday|6:1|2|w2": "ਪੁੱਛਗਿੱਛ",
        "everyday|6:1|2|w3": "ਸਾਮਾਨ",
        "everyday|6:1|2|w4": "ਸਮਾਂ-ਸਾਰਣੀ",
        "everyday|6:1|2|w5": "ਕੁਲੀ",
        "everyday|6:1|3|p0": "ਦਿੱਲੀ ਨੇੜੇ ਸੰਘਣੀ ਧੁੰਦ ਕਾਰਨ ਚਾਰ ਘੰਟੇ ਦੀ ਦੇਰੀ ਹੈ।",
        "everyday|6:1|3|p1": "ਜੇ ਤੁਸੀਂ ਦੋ ਦਿਨਾਂ ਤੋਂ ਵੱਧ ਪਹਿਲਾਂ ਟਿਕਟ ਰੱਦ ਕਰੋ, ਤਾਂ ਰੱਦ ਕਰਨ ਦਾ ਖ਼ਰਚਾ ਥੋੜ੍ਹਾ ਹੁੰਦਾ ਹੈ।",
        "everyday|6:1|3|p2": "ਬੱਸ ਰੱਦ ਹੋ ਗਈ, ਇਸ ਲਈ ਮੈਂ ਪੈਸੇ ਵਾਪਸ ਮੰਗਣ ਲਈ ਪੁੱਛਗਿੱਛ ਕਾਊਂਟਰ ਉੱਤੇ ਗਿਆ।",
        "everyday|6:1|3|p3": "ਕੀ ਤੁਸੀਂ ਉਹ ਐਲਾਨ ਸੁਣਿਆ? ਸਾਨੂੰ ਆਪਣਾ ਸਾਮਾਨ ਪਲੇਟਫ਼ਾਰਮ ਪੰਜ ਉੱਤੇ ਲੈ ਕੇ ਜਾਣਾ ਪਵੇਗਾ।",
        "everyday|6:1|3|p4": "ਸਮਾਂ-ਸਾਰਣੀ ਮੁਤਾਬਕ ਮੈਸੂਰੂ ਲਈ ਆਖ਼ਰੀ ਬੱਸ ਦਸ ਵਜੇ ਚੱਲਦੀ ਹੈ।",
        "everyday|6:1|4|title": "ਐਨ ਮੌਕੇ ਉੱਤੇ",
        "everyday|6:1|4|text": "ਆਸ਼ਾ ਆਪਣੀ ਭੈਣ ਦੇ ਵਿਆਹ ਲਈ ਹੁਬਲੀ ਤੋਂ ਪੁਣੇ ਜਾ ਰਹੀ ਸੀ। ਉਸ ਨੇ ਦੋ ਮਹੀਨੇ ਪਹਿਲਾਂ ਰਿਜ਼ਰਵੇਸ਼ਨ ਕਰਵਾਈ ਸੀ ਅਤੇ ਡੱਬਾ ਐੱਸ4 ਵਿੱਚ ਉਸ ਦੀ ਹੇਠਲੀ ਬਰਥ ਸੀ। ਸਟੇਸ਼ਨ ਉੱਤੇ ਐਲਾਨ ਹੋਇਆ ਕਿ ਗੱਡੀ ਤਿੰਨ ਘੰਟੇ ਦੇਰੀ ਨਾਲ ਹੈ। ਆਸ਼ਾ ਨੇ ਫ਼ੋਨ ਉੱਤੇ ਬੱਸਾਂ ਦੀ ਸਮਾਂ-ਸਾਰਣੀ ਦੇਖੀ ਅਤੇ ਇੱਕ ਅਜਿਹੀ ਬੱਸ ਲੱਭੀ ਜੋ ਪੁਣੇ ਛੇਤੀ ਪਹੁੰਚਦੀ ਸੀ। ਉਸ ਨੇ ਆਨਲਾਈਨ ਆਪਣੀ ਰੇਲ ਟਿਕਟ ਰੱਦ ਕੀਤੀ, ਅਤੇ ਪੈਸੇ ਦੋ ਦਿਨਾਂ ਵਿੱਚ ਉਸ ਦੇ ਖਾਤੇ ਵਿੱਚ ਵਾਪਸ ਆ ਗਏ। ਇੱਕ ਕੁਲੀ ਥੋੜ੍ਹੇ ਜਿਹੇ ਪੈਸਿਆਂ ਬਦਲੇ ਉਸ ਦੇ ਭਾਰੇ ਬੈਗ ਬੱਸ ਅੱਡੇ ਤੱਕ ਲੈ ਗਿਆ। ਉਹ ਮਹਿੰਦੀ ਦੀ ਰਸਮ ਲਈ ਐਨ ਮੌਕੇ ਉੱਤੇ ਪੁਣੇ ਪਹੁੰਚ ਗਈ।",
        "everyday|6:1|4|q0": "ਆਸ਼ਾ ਪੁਣੇ ਕਿਉਂ ਜਾ ਰਹੀ ਸੀ?",
        "everyday|6:1|4|q0o0": "ਆਪਣੀ ਭੈਣ ਦੇ ਵਿਆਹ ਲਈ",
        "everyday|6:1|4|q0o1": "ਨੌਕਰੀ ਦੀ ਇੰਟਰਵਿਊ ਲਈ",
        "everyday|6:1|4|q0o2": "ਕਾਲਜ ਦੇ ਟੂਰ ਲਈ",
        "everyday|6:1|4|q0o3": "ਡਾਕਟਰ ਨੂੰ ਮਿਲਣ ਲਈ",
        "everyday|6:1|4|q1": "ਕਿੰਨੀ ਦੇਰੀ ਸੀ?",
        "everyday|6:1|4|q1o0": "ਤਿੰਨ ਘੰਟੇ",
        "everyday|6:1|4|q1o1": "ਤੀਹ ਮਿੰਟ",
