        "everyday|6:1|4|q1o3": "ਪੂਰਾ ਦਿਨ",
        "everyday|6:1|4|q2": "ਆਖ਼ਰ ਆਸ਼ਾ ਪੁਣੇ ਕਿਵੇਂ ਗਈ?",
        "everyday|6:1|4|q2o0": "ਬੱਸ ਰਾਹੀਂ",
        "everyday|6:1|4|q2o1": "ਬਾਅਦ ਵਾਲੀ ਰੇਲਗੱਡੀ ਰਾਹੀਂ",
        "everyday|6:1|4|q2o2": "ਹਵਾਈ ਜਹਾਜ਼ ਰਾਹੀਂ",
        "everyday|6:1|4|q2o3": "ਟੈਕਸੀ ਰਾਹੀਂ",
        "everyday|6:1|5|title": "ਰੱਦ ਹੋਈ ਰੇਲਗੱਡੀ",
        "everyday|6:1|5|scenario": "ਮੈਸੂਰੂ ਰੇਲਵੇ ਸਟੇਸ਼ਨ ਉੱਤੇ ਕਵਿਤਾ ਨੂੰ ਪਤਾ ਲੱਗਦਾ ਹੈ ਕਿ ਬੈਂਗਲੁਰੂ ਜਾਣ ਵਾਲੀ ਉਸ ਦੀ ਗੱਡੀ ਰੱਦ ਹੋ ਗਈ ਹੈ, ਅਤੇ ਉਹ ਪੁੱਛਗਿੱਛ ਕਾਊਂਟਰ ਉੱਤੇ ਸੁਰੇਸ਼ ਤੋਂ ਮਦਦ ਮੰਗਦੀ ਹੈ।",
        "everyday|6:1|5|l0": "ਸੁਣੋ ਜੀ, ਮੈਂ ਹੁਣੇ ਐਲਾਨ ਸੁਣਿਆ ਕਿ ਚਾਮੁੰਡੀ ਐਕਸਪ੍ਰੈੱਸ ਰੱਦ ਹੋ ਗਈ ਹੈ। ਕੀ ਇਹ ਸੱਚ ਹੈ?",
        "everyday|6:1|5|l1": "ਹਾਂ ਜੀ ਮੈਡਮ, ਅਫ਼ਸੋਸ ਹੈ। ਮਾਂਡਿਆ ਨੇੜੇ ਪਟੜੀ ਵਿੱਚ ਕੋਈ ਖ਼ਰਾਬੀ ਹੈ।",
        "everyday|6:1|5|l2": "ਹਾਏ ਰੱਬਾ। ਦੋ ਵਜੇ ਬੈਂਗਲੁਰੂ ਵਿੱਚ ਮੇਰੀ ਜ਼ਰੂਰੀ ਮੀਟਿੰਗ ਹੈ। ਮੇਰੇ ਕੋਲ ਹੋਰ ਕਿਹੜੇ ਰਾਹ ਹਨ?",
        "everyday|6:1|5|l3": "ਪਲੇਟਫ਼ਾਰਮ ਤਿੰਨ ਤੋਂ ਸਵਾ ਗਿਆਰਾਂ ਵਜੇ ਇੱਕ ਐਕਸਪ੍ਰੈੱਸ ਹੈ। ਉਹ ਆਮ ਤੌਰ 'ਤੇ ਡੇਢ ਵਜੇ ਤੱਕ ਪਹੁੰਚ ਜਾਂਦੀ ਹੈ।",
        "everyday|6:1|5|l4": "ਕੀ ਉਸ ਵਿੱਚ ਕੋਈ ਸੀਟ ਬਚੀ ਹੈ?",
        "everyday|6:1|5|l5": "ਸਿਰਫ਼ ਜਨਰਲ ਡੱਬੇ ਵਿੱਚ। ਰਿਜ਼ਰਵ ਸੀਟਾਂ ਸਾਰੀਆਂ ਵੇਟਿੰਗ ਲਿਸਟ ਵਿੱਚ ਹਨ।",
        "everyday|6:1|5|l6": "ਜਨਰਲ ਡੱਬਾ ਚੱਲੇਗਾ। ਅਤੇ ਮੇਰੀ ਰੱਦ ਹੋਈ ਟਿਕਟ ਦਾ ਕੀ ਹੋਵੇਗਾ?",
        "everyday|6:1|5|l7": "ਕਿਉਂਕਿ ਗੱਡੀ ਰੇਲਵੇ ਨੇ ਰੱਦ ਕੀਤੀ ਹੈ, ਤੁਹਾਨੂੰ ਇੱਕ ਹਫ਼ਤੇ ਵਿੱਚ ਪੂਰੇ ਪੈਸੇ ਵਾਪਸ ਮਿਲ ਜਾਣਗੇ।",
        "everyday|6:1|5|l8": "ਕੀ ਪੈਸੇ ਵਾਪਸ ਲੈਣ ਲਈ ਮੈਨੂੰ ਕੋਈ ਫ਼ਾਰਮ ਭਰਨਾ ਪਵੇਗਾ?",
        "everyday|6:1|5|l9": "ਨਹੀਂ ਮੈਡਮ। ਤੁਸੀਂ ਆਨਲਾਈਨ ਬੁੱਕ ਕੀਤੀ ਸੀ, ਇਸ ਲਈ ਇਹ ਆਪਣੇ ਆਪ ਹੋ ਜਾਵੇਗਾ। ਤੁਹਾਡਾ ਸਫ਼ਰ ਸੁਖਾਲਾ ਹੋਵੇ।",
        "everyday|6:1|5|q0": "ਚਾਮੁੰਡੀ ਐਕਸਪ੍ਰੈੱਸ ਕਿਉਂ ਰੱਦ ਹੋਈ?",
        "everyday|6:1|5|q0o0": "ਮਾਂਡਿਆ ਨੇੜੇ ਪਟੜੀ ਵਿੱਚ ਖ਼ਰਾਬੀ",
