        "everyday|6:1|5|q1": "ਸੁਰੇਸ਼ ਕਿਹੜੀ ਗੱਡੀ ਦਾ ਸੁਝਾਅ ਦਿੰਦਾ ਹੈ?",
        "everyday|6:1|5|q1o0": "ਸਵਾ ਗਿਆਰਾਂ ਵਜੇ ਵਾਲੀ ਐਕਸਪ੍ਰੈੱਸ",
        "everyday|6:1|5|q1o1": "ਰਾਤ ਦੀ ਗੱਡੀ",
        "everyday|6:1|5|q1o2": "ਅਗਲੇ ਦਿਨ ਦੀ ਚਾਮੁੰਡੀ ਐਕਸਪ੍ਰੈੱਸ",
        "everyday|6:1|5|q1o3": "ਦੋ ਵਜੇ ਵਾਲੀ ਗੱਡੀ",
        "everyday|6:1|5|q2": "ਕਵਿਤਾ ਨੂੰ ਪੈਸੇ ਵਾਪਸ ਕਿਵੇਂ ਮਿਲਣਗੇ?",
