        "services|1:1|0|w4": "ਖ਼ੁਰਾਕ",
        "services|1:1|0|w5": "ਮਾੜਾ ਅਸਰ",
        "services|1:1|1|p0": "ਕੀ ਨੇੜੇ ਕੋਈ ਦਵਾਈਆਂ ਦੀ ਦੁਕਾਨ ਹੈ ਜੋ ਸਾਰੀ ਰਾਤ ਖੁੱਲ੍ਹੀ ਰਹਿੰਦੀ ਹੋਵੇ?",
        "services|1:1|1|p1": "ਕੀ ਤੁਸੀਂ ਮੈਨੂੰ ਦਸ ਸਾਲ ਦੇ ਬੱਚੇ ਲਈ ਸਹੀ ਖ਼ੁਰਾਕ ਦੱਸ ਸਕਦੇ ਹੋ?",
        "services|1:1|1|p2": "ਕੈਮਿਸਟ ਨੇ ਕਿਹਾ ਕਿ ਮੈਂ ਹਰ ਖਾਣੇ ਤੋਂ ਬਾਅਦ ਇੱਕ ਗੋਲੀ ਲਵਾਂ।",
        "services|1:1|1|p3": "ਕੀ ਖੰਘ ਦੇ ਇਸ ਸਿਰਪ ਦਾ ਕੋਈ ਮਾੜਾ ਅਸਰ ਹੈ, ਜਿਵੇਂ ਨੀਂਦ ਆਉਣਾ?",
        "services|1:1|1|p4": "ਮਾਫ਼ ਕਰਨਾ, ਅਸੀਂ ਡਾਕਟਰ ਦੀ ਪਰਚੀ ਤੋਂ ਬਿਨਾਂ ਤੁਹਾਨੂੰ ਇਹ ਗੋਲੀਆਂ ਨਹੀਂ ਦੇ ਸਕਦੇ।",
