        "services|1:1|2|w3": "ਦਰਦ ਦੀ ਗੋਲੀ",
        "services|1:1|2|w4": "ਐਂਟੀਬਾਇਓਟਿਕ",
        "services|1:1|2|w5": "ਉਨੀਂਦਾ",
        "services|1:1|3|p0": "ਇਹ ਮੱਲ੍ਹਮ ਦਿਨ ਵਿੱਚ ਦੋ ਵਾਰ ਸੜੀ ਹੋਈ ਥਾਂ ਉੱਤੇ ਹੌਲੀ-ਹੌਲੀ ਲਾਓ।",
        "services|1:1|3|p1": "ਮੈਨੂੰ ਪੈਨਸਿਲਿਨ ਤੋਂ ਐਲਰਜੀ ਹੈ, ਇਸ ਲਈ ਕਿਰਪਾ ਕਰਕੇ ਕੋਈ ਹੋਰ ਦਵਾਈ ਦੱਸੋ।",
        "services|1:1|3|p2": "ਨਵਾਂ ਪੱਤਾ ਖੋਲ੍ਹਣ ਤੋਂ ਪਹਿਲਾਂ ਹਮੇਸ਼ਾ ਮਿਆਦ ਪੁੱਗਣ ਦੀ ਤਾਰੀਖ਼ ਦੇਖੋ।",
        "services|1:1|3|p3": "ਐਂਟੀਬਾਇਓਟਿਕ ਦਾ ਪੂਰਾ ਕੋਰਸ ਖ਼ਤਮ ਕਰੋ, ਭਾਵੇਂ ਤੁਸੀਂ ਠੀਕ ਮਹਿਸੂਸ ਕਰੋ।",
        "services|1:1|3|p4": "ਇਸ ਦਰਦ ਦੀ ਗੋਲੀ ਨਾਲ ਨੀਂਦ ਆ ਸਕਦੀ ਹੈ, ਇਸ ਲਈ ਇਹ ਲੈਣ ਤੋਂ ਬਾਅਦ ਗੱਡੀ ਨਾ ਚਲਾਓ।",
        "services|1:1|4|title": "ਦਵਾਈਆਂ ਦੀ ਦੁਕਾਨ ਉੱਤੇ ਦੇਰ ਰਾਤ",
        "services|1:1|4|text": "ਮੈਸੂਰੂ ਵਿੱਚ ਇੱਕ ਰਾਤ ਦਸ ਵਜੇ ਮੀਰਾ ਦਾ ਛੋਟਾ ਭਰਾ ਰੋਹਨ ਤੇਜ਼ ਬੁਖ਼ਾਰ ਨਾਲ ਜਾਗ ਪਿਆ। ਉਨ੍ਹਾਂ ਦੀ ਪਰਿਵਾਰਕ ਡਾਕਟਰ ਸ਼ਹਿਰੋਂ ਬਾਹਰ ਸੀ, ਇਸ ਲਈ ਮੀਰਾ ਨੇ ਸਲਾਹ ਲਈ ਉਸ ਨੂੰ ਫ਼ੋਨ ਕੀਤਾ। ਡਾਕਟਰ ਨੇ ਕਿਹਾ ਕਿ ਸਵੇਰ ਤੱਕ ਬੁਖ਼ਾਰ ਦਾ ਸਿਰਪ ਕਾਫ਼ੀ ਹੋਵੇਗਾ। ਮੀਰਾ ਨੂੰ ਬੱਸ ਅੱਡੇ ਨੇੜੇ ਦਵਾਈਆਂ ਦੀ ਇੱਕ ਦੁਕਾਨ ਮਿਲੀ ਜੋ ਸਾਰੀ ਰਾਤ ਖੁੱਲ੍ਹੀ ਰਹਿੰਦੀ ਹੈ। ਉਸ ਨੇ ਕੈਮਿਸਟ ਨੂੰ ਦੱਸਿਆ ਕਿ ਰੋਹਨ ਅੱਠ ਸਾਲ ਦਾ ਹੈ ਅਤੇ ਉਸ ਨੂੰ ਇੱਕ ਐਂਟੀਬਾਇਓਟਿਕ ਤੋਂ ਐਲਰਜੀ ਹੈ। ਕੈਮਿਸਟ ਨੇ ਮਿਆਦ ਪੁੱਗਣ ਦੀ ਤਾਰੀਖ਼ ਦੇਖੀ, ਡੱਬੇ ਉੱਤੇ ਖ਼ੁਰਾਕ ਲਿਖ ਦਿੱਤੀ ਅਤੇ ਖ਼ਬਰਦਾਰ ਕੀਤਾ ਕਿ ਸਿਰਪ ਨਾਲ ਰੋਹਨ ਨੂੰ ਨੀਂਦ ਆ ਸਕਦੀ ਹੈ। ਸਵੇਰ ਤੱਕ ਰੋਹਨ ਦਾ ਬੁਖ਼ਾਰ ਉੱਤਰ ਗਿਆ ਸੀ ਅਤੇ ਉਹ ਡੋਸਾ ਮੰਗ ਰਿਹਾ ਸੀ।",
        "services|1:1|4|q0": "ਮੀਰਾ ਰਾਤ ਨੂੰ ਦਵਾਈਆਂ ਦੀ ਦੁਕਾਨ ਉੱਤੇ ਕਿਉਂ ਗਈ?",
