        "services|1:1|4|q2o3": "ਉਸ ਨੂੰ ਨਵੀਂ ਐਲਰਜੀ ਹੋ ਗਈ ਸੀ",
        "services|1:1|5|title": "ਕੈਮਿਸਟ ਤੋਂ ਸਲਾਹ",
        "services|1:1|5|scenario": "ਕਿਰਨ ਨੂੰ ਬਹੁਤ ਜ਼ੁਕਾਮ ਹੈ, ਅਤੇ ਉਹ ਹੁਬਲੀ ਦੀ ਕੈਮਿਸਟ ਲਤਾ ਤੋਂ ਸਲਾਹ ਮੰਗਦਾ ਹੈ।",
        "services|1:1|5|l0": "ਨਮਸਕਾਰ। ਦੱਸੋ, ਮੈਂ ਤੁਹਾਡੀ ਕੀ ਮਦਦ ਕਰਾਂ?",
        "services|1:1|5|l1": "ਨਮਸਕਾਰ। ਕੱਲ੍ਹ ਤੋਂ ਮੇਰਾ ਨੱਕ ਬੰਦ ਹੈ ਅਤੇ ਗਲ਼ਾ ਖ਼ਰਾਬ ਹੈ। ਕੀ ਤੁਸੀਂ ਕੋਈ ਦਵਾਈ ਦੱਸ ਸਕਦੇ ਹੋ?",
        "services|1:1|5|l2": "ਕੀ ਤੁਹਾਨੂੰ ਬੁਖ਼ਾਰ ਹੈ, ਜਾਂ ਕਿਸੇ ਦਵਾਈ ਤੋਂ ਐਲਰਜੀ ਹੈ?",
        "services|1:1|5|l3": "ਬੁਖ਼ਾਰ ਨਹੀਂ ਹੈ, ਅਤੇ ਜਿੱਥੋਂ ਤੱਕ ਮੈਨੂੰ ਪਤਾ ਹੈ, ਕੋਈ ਐਲਰਜੀ ਵੀ ਨਹੀਂ। ਮੈਂ ਬਹੁਤੀ ਤੇਜ਼ ਦਵਾਈ ਨਹੀਂ ਲੈਣਾ ਚਾਹੁੰਦਾ।",
        "services|1:1|5|l4": "ਤਾਂ ਜ਼ੁਕਾਮ ਲਈ ਇਹ ਗੋਲੀਆਂ ਲਓ, ਇੱਕ ਸਵੇਰੇ ਅਤੇ ਇੱਕ ਰਾਤ ਨੂੰ, ਖਾਣੇ ਤੋਂ ਬਾਅਦ।",
        "services|1:1|5|l5": "ਕੀ ਇਨ੍ਹਾਂ ਦਾ ਕੋਈ ਮਾੜਾ ਅਸਰ ਹੈ ਜਿਸ ਬਾਰੇ ਮੈਨੂੰ ਪਤਾ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ?",
        "services|1:1|5|l6": "ਇਨ੍ਹਾਂ ਨਾਲ ਥੋੜ੍ਹੀ ਨੀਂਦ ਆ ਸਕਦੀ ਹੈ, ਇਸ ਲਈ ਕਿਰਪਾ ਕਰਕੇ ਰਾਤ ਵਾਲੀ ਗੋਲੀ ਤੋਂ ਬਾਅਦ ਗੱਡੀ ਨਾ ਚਲਾਇਓ।",
        "services|1:1|5|l7": "ਸਮਝ ਗਿਆ। ਅਤੇ ਕੀ ਗਲ਼ੇ ਲਈ ਵੀ ਕੁਝ ਹੈ?",
        "services|1:1|5|l8": "ਇਹ ਸਿਰਪ ਫ਼ਾਇਦਾ ਕਰੇਗਾ: ਦੋ ਚਮਚ, ਦਿਨ ਵਿੱਚ ਤਿੰਨ ਵਾਰ। ਜੇ ਤਿੰਨ ਦਿਨਾਂ ਵਿੱਚ ਠੀਕ ਨਾ ਹੋਏ, ਤਾਂ ਕਿਰਪਾ ਕਰਕੇ ਡਾਕਟਰ ਨੂੰ ਦਿਖਾਓ।",
        "services|1:1|5|l9": "ਬਹੁਤ ਮਦਦ ਮਿਲੀ, ਸ਼ੁਕਰੀਆ। ਕੀ ਮੈਂ ਯੂਪੀਆਈ ਨਾਲ ਪੈਸੇ ਦੇ ਸਕਦਾ ਹਾਂ?",
        "services|1:1|5|q0": "ਕਿਰਨ ਨੂੰ ਗੋਲੀਆਂ ਕਿੰਨੀ ਵਾਰ ਲੈਣੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ?",
        "services|1:1|5|q0o0": "ਦਿਨ ਵਿੱਚ ਦੋ ਵਾਰ, ਖਾਣੇ ਤੋਂ ਬਾਅਦ",
