        "services|2:1|0|w0": "ਐਮਰਜੈਂਸੀ",
        "services|2:1|0|w1": "ਐਂਬੂਲੈਂਸ",
        "services|2:1|0|w2": "ਹੈਲਪਲਾਈਨ",
        "services|2:1|0|w3": "ਫ਼ਾਇਰ ਬ੍ਰਿਗੇਡ",
        "services|2:1|0|w4": "ਹਾਦਸਾ",
        "services|2:1|0|w5": "ਨਿਸ਼ਾਨੀ",
        "services|2:1|1|p0": "ਮੈਂ ਹੁਬਲੀ ਬੱਸ ਅੱਡੇ ਨੇੜੇ ਹੋਏ ਸੜਕ ਹਾਦਸੇ ਦੀ ਸੂਚਨਾ ਦੇਣਾ ਚਾਹੁੰਦਾ ਹਾਂ।",
        "services|2:1|1|p1": "ਕਿਰਪਾ ਕਰਕੇ ਛੇਤੀ ਐਂਬੂਲੈਂਸ ਭੇਜੋ; ਸੜਕ ਉੱਤੇ ਇੱਕ ਆਦਮੀ ਡਿੱਗਿਆ ਪਿਆ ਹੈ।",
        "services|2:1|1|p2": "ਐਮਰਜੈਂਸੀ ਵਿੱਚ 112 ਹੈਲਪਲਾਈਨ ਉੱਤੇ ਫ਼ੋਨ ਕਰੋ ਅਤੇ ਹੌਲੀ ਤੇ ਸਾਫ਼ ਬੋਲੋ।",
        "services|2:1|1|p3": "ਫ਼ਾਇਰ ਬ੍ਰਿਗੇਡ ਰਸਤੇ ਵਿੱਚ ਹੈ, ਇਸ ਲਈ ਕਿਰਪਾ ਕਰਕੇ ਹੁਣੇ ਇਮਾਰਤ ਵਿੱਚੋਂ ਬਾਹਰ ਨਿਕਲ ਜਾਓ।",
        "services|2:1|1|p4": "ਸਭ ਤੋਂ ਨੇੜੇ ਦੀ ਨਿਸ਼ਾਨੀ ਪੈਟਰੋਲ ਪੰਪ ਦੇ ਸਾਹਮਣੇ ਵਾਲਾ ਵੱਡਾ ਮੰਦਰ ਹੈ।",
        "services|2:1|2|w0": "ਜ਼ਖ਼ਮੀ",
        "services|2:1|2|w1": "ਬੇਹੋਸ਼",
        "services|2:1|2|w2": "ਖ਼ੂਨ ਵਗਣਾ",
        "services|2:1|2|w3": "ਮੁੱਢਲੀ ਸਹਾਇਤਾ",
        "services|2:1|2|w4": "ਚੋਰੀ",
        "services|2:1|2|w5": "ਘਬਰਾਹਟ",
        "services|2:1|3|p0": "ਦੋ ਲੋਕ ਜ਼ਖ਼ਮੀ ਹਨ, ਅਤੇ ਉਨ੍ਹਾਂ ਵਿੱਚੋਂ ਇੱਕ ਬੇਹੋਸ਼ ਹੈ।",
        "services|2:1|3|p1": "ਖ਼ੂਨ ਰੋਕਣ ਲਈ ਜ਼ਖ਼ਮ ਉੱਤੇ ਸਾਫ਼ ਕੱਪੜਾ ਦਬਾ ਕੇ ਰੱਖੋ।",
        "services|2:1|3|p2": "ਕੀ ਤੁਹਾਨੂੰ ਮੁੱਢਲੀ ਸਹਾਇਤਾ ਆਉਂਦੀ ਹੈ, ਜਾਂ ਅਸੀਂ ਐਂਬੂਲੈਂਸ ਦੀ ਉਡੀਕ ਕਰੀਏ?",
        "services|2:1|3|p3": "ਸਟੇਸ਼ਨ ਉੱਤੇ ਮੇਰਾ ਬੈਗ ਚੋਰੀ ਹੋ ਗਿਆ, ਅਤੇ ਮੈਂ ਚੋਰੀ ਦੀ ਰਿਪੋਰਟ ਲਿਖਵਾਉਣੀ ਹੈ।",
        "services|2:1|3|p4": "ਘਬਰਾਓ ਨਾ; ਡੂੰਘਾ ਸਾਹ ਲਓ ਅਤੇ ਮੈਨੂੰ ਆਪਣਾ ਪਤਾ ਦੱਸੋ।",
        "services|2:1|4|title": "ਹਾਈਵੇ ਉੱਤੇ ਮਦਦ",
        "services|2:1|4|text": "ਰਵੀ ਮੰਗਲੁਰੂ ਤੋਂ ਉਡੁਪੀ ਗੱਡੀ ਚਲਾ ਕੇ ਜਾ ਰਿਹਾ ਸੀ ਜਦੋਂ ਉਸ ਨੇ ਹਾਈਵੇ ਦੇ ਕੰਢੇ ਇੱਕ ਮੋਟਰਸਾਈਕਲ ਡਿੱਗਿਆ ਦੇਖਿਆ। ਉਸ ਦੇ ਕੋਲ ਇੱਕ ਨੌਜਵਾਨ ਬੈਠਾ ਸੀ, ਅਤੇ ਉਸ ਦੀ ਬਾਂਹ ਵਿੱਚੋਂ ਬਹੁਤ ਖ਼ੂਨ ਵਗ ਰਿਹਾ ਸੀ। ਰਵੀ ਨੇ ਆਪਣੀ ਕਾਰ ਰੋਕੀ ਅਤੇ ਆਪਣੇ ਆਪ ਨੂੰ ਕਿਹਾ ਕਿ ਘਬਰਾਉਣਾ ਨਹੀਂ। ਉਸ ਨੇ 108 ਉੱਤੇ ਫ਼ੋਨ ਕੀਤਾ ਅਤੇ ਕਿਹਾ, 'ਮੈਂ ਇੱਕ ਹਾਦਸੇ ਦੀ ਸੂਚਨਾ ਦੇਣੀ ਹੈ; ਇੱਕ ਬੰਦਾ ਜ਼ਖ਼ਮੀ ਹੈ।' ਆਪਰੇਟਰ ਨੇ ਸਹੀ ਥਾਂ ਪੁੱਛੀ, ਇਸ ਲਈ ਰਵੀ ਨੇ ਸਭ ਤੋਂ ਨੇੜੇ ਦੀ ਨਿਸ਼ਾਨੀ ਦੱਸੀ, ਸੂਰਤਕਲ ਦਾ ਲਾਈਟਹਾਊਸ। ਉਡੀਕ ਕਰਦਿਆਂ ਰਵੀ ਨੇ ਜ਼ਖ਼ਮ ਉੱਤੇ ਸਾਫ਼ ਤੌਲੀਆ ਦਬਾ ਕੇ ਮੁੱਢਲੀ ਸਹਾਇਤਾ ਦਿੱਤੀ। ਐਂਬੂਲੈਂਸ ਪੰਦਰਾਂ ਮਿੰਟਾਂ ਵਿੱਚ ਪਹੁੰਚ ਗਈ, ਅਤੇ ਬਾਅਦ ਵਿੱਚ ਨੌਜਵਾਨ ਨੇ ਸ਼ਾਂਤ ਰਹਿਣ ਲਈ ਰਵੀ ਦਾ ਸ਼ੁਕਰੀਆ ਕੀਤਾ।",
        "services|2:1|4|q0": "ਰਵੀ ਨੇ ਮੋਟਰਸਾਈਕਲ ਕਿੱਥੇ ਦੇਖਿਆ?",
        "services|2:1|4|q0o0": "ਹਾਈਵੇ ਦੇ ਕੰਢੇ",
        "services|2:1|4|q0o1": "ਇੱਕ ਹਸਪਤਾਲ ਦੇ ਬਾਹਰ",
        "services|2:1|4|q0o2": "ਉਡੁਪੀ ਦੀ ਇੱਕ ਪਾਰਕਿੰਗ ਵਿੱਚ",
        "services|2:1|4|q0o3": "ਮੰਗਲੁਰੂ ਵਿੱਚ ਆਪਣੇ ਘਰ ਨੇੜੇ",
        "services|2:1|4|q1": "ਰਵੀ ਨੇ ਕਿਹੜੀ ਨਿਸ਼ਾਨੀ ਦੱਸੀ?",
        "services|2:1|4|q1o0": "ਸੂਰਤਕਲ ਦਾ ਲਾਈਟਹਾਊਸ",
