        "services|2:1|4|q1o3": "ਇੱਕ ਬੱਸ ਅੱਡਾ",
        "services|2:1|4|q2": "ਐਂਬੂਲੈਂਸ ਨੂੰ ਪਹੁੰਚਣ ਵਿੱਚ ਕਿੰਨਾ ਸਮਾਂ ਲੱਗਾ?",
        "services|2:1|4|q2o0": "ਪੰਦਰਾਂ ਮਿੰਟ",
        "services|2:1|4|q2o1": "ਇੱਕ ਘੰਟਾ",
        "services|2:1|4|q2o2": "ਪੰਜ ਮਿੰਟ",
        "services|2:1|4|q2o3": "ਤੀਹ ਮਿੰਟ",
        "services|2:1|5|title": "112 ਉੱਤੇ ਫ਼ੋਨ",
        "services|2:1|5|scenario": "ਨੰਦਿਨੀ ਪੁਣੇ ਵਿੱਚ ਆਪਣੀ ਗਲੀ ਦੇ ਇੱਕ ਘਰ ਵਿੱਚੋਂ ਧੂੰਆਂ ਨਿਕਲਦਾ ਦੇਖਦੀ ਹੈ ਅਤੇ 112 ਐਮਰਜੈਂਸੀ ਹੈਲਪਲਾਈਨ ਉੱਤੇ ਫ਼ੋਨ ਕਰਦੀ ਹੈ। ਸੁਰੇਸ਼ ਫ਼ੋਨ ਚੁੱਕਦਾ ਹੈ।",
        "services|2:1|5|l0": "112 ਐਮਰਜੈਂਸੀ ਹੈਲਪਲਾਈਨ। ਦੱਸੋ, ਕੀ ਐਮਰਜੈਂਸੀ ਹੈ?",
        "services|2:1|5|l1": "ਮੇਰੀ ਗਲੀ ਦੇ ਇੱਕ ਘਰ ਵਿੱਚ ਅੱਗ ਲੱਗੀ ਹੈ। ਉੱਪਰਲੀ ਖਿੜਕੀ ਵਿੱਚੋਂ ਸੰਘਣਾ ਧੂੰਆਂ ਨਿਕਲਦਾ ਦਿਸ ਰਿਹਾ ਹੈ।",
        "services|2:1|5|l2": "ਕਿਰਪਾ ਕਰਕੇ ਸ਼ਾਂਤ ਰਹੋ, ਮੈਡਮ। ਕੀ ਘਰ ਦੇ ਅੰਦਰ ਹਾਲੇ ਕੋਈ ਹੈ?",
        "services|2:1|5|l3": "ਪੱਕਾ ਨਹੀਂ ਪਤਾ। ਉੱਥੇ ਇੱਕ ਬਜ਼ੁਰਗ ਜੋੜਾ ਰਹਿੰਦਾ ਹੈ, ਅਤੇ ਉਹ ਮੈਨੂੰ ਬਾਹਰ ਨਹੀਂ ਦਿਸ ਰਹੇ।",
        "services|2:1|5|l4": "ਮੈਂ ਹੁਣੇ ਫ਼ਾਇਰ ਬ੍ਰਿਗੇਡ ਅਤੇ ਐਂਬੂਲੈਂਸ ਭੇਜ ਰਿਹਾ ਹਾਂ। ਪੂਰਾ ਪਤਾ ਕੀ ਹੈ?",
        "services|2:1|5|l5": "ਮਕਾਨ ਨੰਬਰ 14, ਸ਼ਾਂਤੀ ਨਗਰ, ਕੋਥਰੂਡ। ਨਿਸ਼ਾਨੀ ਹੈ ਮੋੜ ਉੱਤੇ ਨੀਲੀ ਪਾਣੀ ਦੀ ਟੈਂਕੀ।",
        "services|2:1|5|l6": "ਸ਼ੁਕਰੀਆ। ਕਿਰਪਾ ਕਰਕੇ ਅੰਦਰ ਨਾ ਜਾਣਾ, ਅਤੇ ਬਾਕੀ ਲੋਕਾਂ ਨੂੰ ਧੂੰਏਂ ਤੋਂ ਦੂਰ ਰੱਖੋ।",
        "services|2:1|5|l7": "ਠੀਕ ਹੈ। ਓਹ, ਇੱਕ ਗੁਆਂਢੀ ਕਹਿ ਰਿਹਾ ਹੈ ਕਿ ਜੋੜਾ ਮੰਦਰ ਗਿਆ ਹੋਇਆ ਹੈ, ਇਸ ਲਈ ਘਰ ਖ਼ਾਲੀ ਹੈ।",
        "services|2:1|5|l8": "ਇਹ ਤਾਂ ਚੰਗੀ ਖ਼ਬਰ ਹੈ। ਫ਼ਾਇਰ ਬ੍ਰਿਗੇਡ ਲਗਭਗ ਦਸ ਮਿੰਟਾਂ ਵਿੱਚ ਪਹੁੰਚ ਜਾਣੀ ਚਾਹੀਦੀ ਹੈ। ਕਿਰਪਾ ਕਰਕੇ ਫ਼ੋਨ ਉੱਤੇ ਬਣੇ ਰਹੋ।",
        "services|2:1|5|l9": "ਬਹੁਤ-ਬਹੁਤ ਸ਼ੁਕਰੀਆ। ਮੈਨੂੰ ਸਾਇਰਨ ਸੁਣਾਈ ਦੇਣ ਲੱਗ ਪਿਆ ਹੈ।",
        "services|2:1|5|q0": "ਨੰਦਿਨੀ ਨੇ 112 ਉੱਤੇ ਫ਼ੋਨ ਕਿਉਂ ਕੀਤਾ?",
