        "services|3:1|0|w4": "ਵਾਇਰਿੰਗ",
        "services|3:1|0|w5": "ਫ਼ਿਊਜ਼",
        "services|3:1|1|p0": "ਰਸੋਈ ਦੀ ਟੂਟੀ ਸਾਰੀ ਰਾਤ ਤੋਂ ਚੋ ਰਹੀ ਹੈ; ਕੀ ਤੁਸੀਂ ਅੱਜ ਪਲੰਬਰ ਭੇਜ ਸਕਦੇ ਹੋ?",
        "services|3:1|1|p1": "ਬਾਥਰੂਮ ਦੇ ਸਿੰਕ ਹੇਠਾਂ ਲੀਕ ਹੈ, ਅਤੇ ਫ਼ਰਸ਼ ਹਮੇਸ਼ਾ ਗਿੱਲਾ ਰਹਿੰਦਾ ਹੈ।",
        "services|3:1|1|p2": "ਜਦੋਂ ਵੀ ਮੈਂ ਗੀਜ਼ਰ ਚਲਾਉਂਦਾ ਹਾਂ, ਫ਼ਿਊਜ਼ ਉੱਡ ਜਾਂਦਾ ਹੈ।",
        "services|3:1|1|p3": "ਬਿਜਲੀ ਮਿਸਤਰੀ ਕਹਿੰਦਾ ਹੈ ਕਿ ਇਸ ਫ਼ਲੈਟ ਦੀ ਪੁਰਾਣੀ ਵਾਇਰਿੰਗ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਹੈ।",
        "services|3:1|1|p4": "ਕਿਸੇ ਵੀ ਤਾਰ ਨੂੰ ਹੱਥ ਲਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਕਿਰਪਾ ਕਰਕੇ ਮੇਨ ਸਵਿੱਚ ਬੰਦ ਕਰੋ।",
        "services|3:1|2|w0": "ਘਰੇਲੂ ਉਪਕਰਨ",
        "services|3:1|2|w1": "ਨੁਕਸ",
        "services|3:1|2|w2": "ਟੈਕਨੀਸ਼ੀਅਨ",
        "services|3:1|2|w3": "ਪੁਰਜ਼ਾ",
        "services|3:1|2|w4": "ਅੰਦਾਜ਼ਾ",
        "services|3:1|2|w5": "ਸਰਵਿਸ ਚਾਰਜ",
        "services|3:1|3|p0": "ਸਾਡੀ ਵਾਸ਼ਿੰਗ ਮਸ਼ੀਨ ਵਿੱਚ ਨੁਕਸ ਹੈ; ਇਹ ਹਰ ਵਾਰ ਕੱਪੜੇ ਧੋਂਦਿਆਂ ਵਿਚਾਲੇ ਰੁਕ ਜਾਂਦੀ ਹੈ।",
        "services|3:1|3|p1": "ਕੀ ਟੈਕਨੀਸ਼ੀਅਨ ਕੱਲ੍ਹ ਸਵੇਰੇ ਆ ਸਕਦਾ ਹੈ, ਮੇਰੇ ਕੰਮ ਉੱਤੇ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ?",
        "services|3:1|3|p2": "ਕੰਮ ਸ਼ੁਰੂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ, ਕੀ ਤੁਸੀਂ ਮੈਨੂੰ ਕੁੱਲ ਖ਼ਰਚੇ ਦਾ ਅੰਦਾਜ਼ਾ ਦੇ ਸਕਦੇ ਹੋ?",
        "services|3:1|3|p3": "ਪੁਰਜ਼ੇ ਨੂੰ ਬੈਂਗਲੁਰੂ ਤੋਂ ਆਉਣ ਵਿੱਚ ਤਿੰਨ ਦਿਨ ਲੱਗਣਗੇ।",
        "services|3:1|3|p4": "ਕਿਸੇ ਵੀ ਵੱਡੇ ਘਰੇਲੂ ਉਪਕਰਨ ਦਾ ਸਰਵਿਸ ਚਾਰਜ ਹਰ ਗੇੜੇ ਦਾ ਤਿੰਨ ਸੌ ਰੁਪਏ ਹੈ।",
        "services|3:1|4|title": "ਫ਼ਰਿੱਜ ਜਿਸ ਨੇ ਠੰਢਾ ਕਰਨਾ ਛੱਡ ਦਿੱਤਾ",
        "services|3:1|4|text": "ਮਈ ਵਿੱਚ ਕਲਬੁਰਗੀ ਦੇ ਇੱਕ ਗਰਮ ਹਫ਼ਤੇ ਦੌਰਾਨ ਕੁਲਕਰਨੀ ਪਰਿਵਾਰ ਦਾ ਫ਼ਰਿੱਜ ਅਚਾਨਕ ਠੰਢਾ ਕਰਨੋਂ ਹਟ ਗਿਆ। ਸੁਨੀਤਾ ਨੇ ਕੰਪਨੀ ਦੇ ਸਰਵਿਸ ਸੈਂਟਰ ਨੂੰ ਫ਼ੋਨ ਕੀਤਾ ਅਤੇ ਨੁਕਸ ਸਾਫ਼-ਸਾਫ਼ ਸਮਝਾਇਆ: ਬੱਤੀ ਜਗ ਰਹੀ ਸੀ, ਪਰ ਅੰਦਰੋਂ ਫ਼ਰਿੱਜ ਗਰਮ ਸੀ। ਅਗਲੀ ਦੁਪਹਿਰ ਇੱਕ ਟੈਕਨੀਸ਼ੀਅਨ ਆਇਆ ਅਤੇ ਉਸ ਨੇ ਮਸ਼ੀਨ ਧਿਆਨ ਨਾਲ ਜਾਂਚੀ। ਉਸ ਨੇ ਦੱਸਿਆ ਕਿ ਠੰਢਕ ਵਾਲੇ ਸਿਸਟਮ ਦਾ ਇੱਕ ਪੁਰਜ਼ਾ ਖ਼ਰਾਬ ਹੋ ਗਿਆ ਹੈ ਅਤੇ ਉਸ ਨੂੰ ਬਦਲਣਾ ਪਵੇਗਾ। ਕੰਮ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਸੁਨੀਤਾ ਨੇ ਨਿਮਰਤਾ ਨਾਲ ਖ਼ਰਚੇ ਦਾ ਅੰਦਾਜ਼ਾ ਮੰਗਿਆ, ਅਤੇ ਉਸ ਨੇ ਕਿਹਾ ਕਿ ਸਰਵਿਸ ਚਾਰਜ ਸਮੇਤ ਕੁੱਲ ਲਗਭਗ ਦੋ ਹਜ਼ਾਰ ਰੁਪਏ ਬਣਨਗੇ। ਪੁਰਜ਼ਾ ਦੋ ਦਿਨਾਂ ਬਾਅਦ ਹੁਬਲੀ ਤੋਂ ਆਇਆ, ਅਤੇ ਟੈਕਨੀਸ਼ੀਅਨ ਨੇ ਇੱਕ ਘੰਟੇ ਵਿੱਚ ਫ਼ਰਿੱਜ ਠੀਕ ਕਰ ਦਿੱਤਾ। ਉਸ ਸ਼ਾਮ ਫ਼ਰਿੱਜ ਫਿਰ ਠੰਢਾ ਹੋ ਗਿਆ, ਅਤੇ ਆਖ਼ਰਕਾਰ ਪਰਿਵਾਰ ਦੁੱਧ ਅਤੇ ਦਹੀਂ ਰੱਖ ਸਕਿਆ।",
        "services|3:1|4|q0": "ਫ਼ਰਿੱਜ ਵਿੱਚ ਕੀ ਖ਼ਰਾਬੀ ਸੀ?",
