        "services|3:1|5|title": "ਬਿਜਲੀ ਮਿਸਤਰੀ ਬੁਲਾਉਣਾ",
        "services|3:1|5|scenario": "ਫ਼ਰਹਾਨ ਮੈਸੂਰੂ ਵਿੱਚ ਘਰੇਲੂ ਮੁਰੰਮਤ ਦੀ ਸਰਵਿਸ ਚਲਾਉਣ ਵਾਲੀ ਆਸ਼ਾ ਨੂੰ ਫ਼ੋਨ ਕਰਦਾ ਹੈ, ਕਿਉਂਕਿ ਉਸ ਦੇ ਫ਼ਲੈਟ ਦਾ ਫ਼ਿਊਜ਼ ਵਾਰ-ਵਾਰ ਉੱਡ ਜਾਂਦਾ ਹੈ।",
        "services|3:1|5|l0": "ਨਮਸਕਾਰ, ਕੁਇੱਕਫ਼ਿਕਸ ਹੋਮ ਸਰਵਿਸਿਜ਼। ਮੈਂ ਆਸ਼ਾ ਬੋਲ ਰਹੀ ਹਾਂ। ਦੱਸੋ, ਕੀ ਮਦਦ ਕਰਾਂ?",
        "services|3:1|5|l1": "ਹੈਲੋ, ਮੈਂ ਬਿਜਲੀ ਦੀ ਇੱਕ ਸਮੱਸਿਆ ਬਾਰੇ ਫ਼ੋਨ ਕਰ ਰਿਹਾ ਹਾਂ। ਮੇਰੇ ਫ਼ਲੈਟ ਦਾ ਫ਼ਿਊਜ਼ ਵਾਰ-ਵਾਰ ਉੱਡ ਜਾਂਦਾ ਹੈ, ਜ਼ਿਆਦਾਤਰ ਸ਼ਾਮ ਨੂੰ।",
        "services|3:1|5|l2": "ਅੱਛਾ। ਕੀ ਇਹ ਕੋਈ ਖ਼ਾਸ ਮਸ਼ੀਨ ਚਲਾਉਣ ਉੱਤੇ ਹੁੰਦਾ ਹੈ?",
        "services|3:1|5|l3": "ਮੇਰੇ ਖ਼ਿਆਲ ਵਿੱਚ ਹਾਂ। ਆਮ ਤੌਰ 'ਤੇ ਇਹ ਉਦੋਂ ਹੁੰਦਾ ਹੈ ਜਦੋਂ ਗੀਜ਼ਰ ਅਤੇ ਪ੍ਰੈੱਸ ਇਕੱਠੇ ਚੱਲਦੇ ਹਨ।",
        "services|3:1|5|l4": "ਸ਼ਾਇਦ ਵਾਇਰਿੰਗ ਵਿੱਚ ਨੁਕਸ ਹੈ। ਮੈਂ ਜਾਂਚ ਲਈ ਬਿਜਲੀ ਮਿਸਤਰੀ ਭੇਜ ਸਕਦੀ ਹਾਂ। ਤੁਹਾਨੂੰ ਕਦੋਂ ਠੀਕ ਰਹੇਗਾ?",
        "services|3:1|5|l5": "ਕੀ ਤੁਸੀਂ ਅੱਜ ਹੀ ਕਿਸੇ ਨੂੰ ਭੇਜ ਸਕਦੇ ਹੋ? ਮੈਂ ਛੇ ਵਜੇ ਤੱਕ ਘਰੋਂ ਕੰਮ ਕਰ ਰਿਹਾ ਹਾਂ।",
        "services|3:1|5|l6": "ਸਾਡਾ ਬਿਜਲੀ ਮਿਸਤਰੀ ਮਹੇਸ਼ ਚਾਰ ਵਜੇ ਆ ਸਕਦਾ ਹੈ। ਗੇੜੇ ਦਾ ਸਰਵਿਸ ਚਾਰਜ ਢਾਈ ਸੌ ਰੁਪਏ ਹੈ।",
        "services|3:1|5|l7": "ਠੀਕ ਹੈ। ਕੀ ਉਹ ਮੁਰੰਮਤ ਸ਼ੁਰੂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਮੈਨੂੰ ਖ਼ਰਚੇ ਦਾ ਅੰਦਾਜ਼ਾ ਦੇਵੇਗਾ?",
        "services|3:1|5|l8": "ਹਾਂ, ਉਹ ਹਮੇਸ਼ਾ ਪਹਿਲਾਂ ਖ਼ਰਚਾ ਸਮਝਾਉਂਦਾ ਹੈ। ਕਿਰਪਾ ਕਰਕੇ ਆਪਣਾ ਪਤਾ ਵਟਸਐਪ ਉੱਤੇ ਭੇਜ ਦਿਓ।",
        "services|3:1|5|l9": "ਬਹੁਤ ਵਧੀਆ, ਮੈਂ ਹੁਣੇ ਭੇਜਦਾ ਹਾਂ। ਸ਼ੁਕਰੀਆ।",
        "services|3:1|5|q0": "ਫ਼ਰਹਾਨ ਦੇ ਫ਼ਲੈਟ ਵਿੱਚ ਕੀ ਸਮੱਸਿਆ ਹੈ?",
        "services|3:1|5|q0o0": "ਫ਼ਿਊਜ਼ ਵਾਰ-ਵਾਰ ਉੱਡ ਜਾਂਦਾ ਹੈ",
