        "services|4:1|5|q1": "ਦੀਪਾ ਨੇ ਪੈਸੇ ਵਾਪਸ ਲੈਣਾ ਕਿਉਂ ਚੁਣਿਆ?",
        "services|4:1|5|q1o0": "ਨਵਾਂ ਕੁੜਤਾ ਵਿਆਹ ਤੋਂ ਪਹਿਲਾਂ ਨਹੀਂ ਪਹੁੰਚਣਾ ਸੀ",
