        "services|5:1|1|p0": "ਆਮਦਨ ਸਰਟੀਫ਼ਿਕੇਟ ਲਈ ਅਰਜ਼ੀ ਫ਼ਾਰਮ ਮੈਨੂੰ ਕਿੱਥੋਂ ਮਿਲ ਸਕਦਾ ਹੈ?",
        "services|5:1|1|p1": "ਕਿਰਪਾ ਕਰਕੇ ਅਸਲ ਦਸਤਾਵੇਜ਼ ਅਤੇ ਹਰੇਕ ਦੀ ਇੱਕ ਫ਼ੋਟੋਕਾਪੀ ਨਾਲ ਲਿਆਓ।",
        "services|5:1|1|p2": "ਤੁਸੀਂ ਦੂਜੇ ਸਫ਼ੇ ਉੱਤੇ ਦਸਤਖ਼ਤ ਕਰਨਾ ਭੁੱਲ ਗਏ।",
        "services|5:1|1|p3": "ਕੀ ਪਤੇ ਦੇ ਸਬੂਤ ਵਜੋਂ ਬਿਜਲੀ ਦਾ ਬਿੱਲ ਕਾਫ਼ੀ ਹੈ?",
        "services|5:1|1|p4": "ਮੇਰੇ ਜਨਮ ਸਰਟੀਫ਼ਿਕੇਟ ਵਿੱਚ ਮੇਰੇ ਪਿਤਾ ਜੀ ਦੇ ਨਾਂ ਦੇ ਸ਼ਬਦ-ਜੋੜ ਗ਼ਲਤ ਹਨ।",
