        "services|5:1|3|p0": "ਕਿਰਪਾ ਕਰਕੇ ਟੋਕਨ ਲਓ ਅਤੇ ਆਪਣਾ ਨੰਬਰ ਬੁਲਾਏ ਜਾਣ ਤੱਕ ਉਡੀਕ ਕਰੋ।",
        "services|5:1|3|p1": "ਸੁਣੋ ਜੀ, ਕੀ ਆਧਾਰ ਅੱਪਡੇਟ ਲਈ ਇਹੀ ਕਤਾਰ ਹੈ?",
        "services|5:1|3|p2": "ਅਧਿਕਾਰੀ ਨੇ ਕਿਹਾ ਕਿ ਮੇਰੀਆਂ ਉਂਗਲਾਂ ਦੇ ਨਿਸ਼ਾਨ ਦੁਬਾਰਾ ਸਕੈਨ ਕਰਨੇ ਪੈਣਗੇ।",
        "services|5:1|3|p3": "ਪਾਸਪੋਰਟ ਲਈ ਪੁਲਿਸ ਪੜਤਾਲ ਵਿੱਚ ਆਮ ਤੌਰ 'ਤੇ ਲਗਭਗ ਦੋ ਹਫ਼ਤੇ ਲੱਗਦੇ ਹਨ।",
        "services|5:1|3|p4": "ਇਹ ਪ੍ਰਾਪਤੀ ਰਸੀਦ ਸੰਭਾਲ ਕੇ ਰੱਖੋ; ਆਪਣੀ ਅਰਜ਼ੀ ਦੀ ਸਥਿਤੀ ਦੇਖਣ ਲਈ ਇਸ ਦੀ ਲੋੜ ਪਵੇਗੀ।",
        "services|5:1|4|title": "ਆਧਾਰ ਕੇਂਦਰ ਵਿੱਚ ਇੱਕ ਸਵੇਰ",
        "services|5:1|4|text": "ਲਕਸ਼ਮੀ ਕੰਮ ਲਈ ਸ਼ਿਵਮੋਗਾ ਤੋਂ ਪੁਣੇ ਆ ਗਈ ਸੀ, ਇਸ ਲਈ ਉਸ ਨੂੰ ਆਪਣੇ ਆਧਾਰ ਕਾਰਡ ਉੱਤੇ ਪਤਾ ਬਦਲਵਾਉਣਾ ਸੀ। ਉਹ ਸਵੇਰੇ ਅੱਠ ਵਜੇ ਆਧਾਰ ਕੇਂਦਰ ਪਹੁੰਚੀ, ਪਰ ਕਤਾਰ ਪਹਿਲਾਂ ਹੀ ਲੰਬੀ ਸੀ। ਇੱਕ ਗਾਰਡ ਨੇ ਉਸ ਨੂੰ ਬਿਆਲੀ ਨੰਬਰ ਦਾ ਟੋਕਨ ਅਤੇ ਭਰਨ ਲਈ ਇੱਕ ਅਰਜ਼ੀ ਫ਼ਾਰਮ ਦਿੱਤਾ। ਜਦੋਂ ਉਸ ਦੀ ਵਾਰੀ ਆਈ, ਅਧਿਕਾਰੀ ਨੇ ਉਸ ਦੇ ਦਸਤਾਵੇਜ਼ ਦੇਖੇ ਅਤੇ ਪਤੇ ਦੇ ਸਬੂਤ ਵਜੋਂ ਬਿਜਲੀ ਦੇ ਬਿੱਲ ਦੀ ਫ਼ੋਟੋਕਾਪੀ ਮੰਗੀ। ਚੰਗੀ ਕਿਸਮਤ ਨਾਲ ਲਕਸ਼ਮੀ ਦੋ ਕਾਪੀਆਂ ਲੈ ਕੇ ਆਈ ਸੀ, ਅਤੇ ਉਸ ਨੇ ਹਰ ਸਫ਼ੇ ਉੱਤੇ ਪਹਿਲਾਂ ਹੀ ਦਸਤਖ਼ਤ ਕਰ ਦਿੱਤੇ ਸਨ। ਫਿਰ ਅਧਿਕਾਰੀ ਨੇ ਪੜਤਾਲ ਲਈ ਉਸ ਦੀਆਂ ਉਂਗਲਾਂ ਦੇ ਨਿਸ਼ਾਨ ਸਕੈਨ ਕੀਤੇ ਅਤੇ ਪ੍ਰਾਪਤੀ ਰਸੀਦ ਛਾਪ ਦਿੱਤੀ। ਉਸ ਨੇ ਦੱਸਿਆ ਕਿ ਦਸ ਦਿਨਾਂ ਵਿੱਚ ਨਵਾਂ ਪਤਾ ਅੱਪਡੇਟ ਹੋ ਜਾਵੇਗਾ, ਅਤੇ ਲਕਸ਼ਮੀ ਦੁਪਹਿਰ ਤੋਂ ਪਹਿਲਾਂ ਹੀ ਸੁਖ ਦਾ ਸਾਹ ਲੈਂਦੀ ਹੋਈ ਦਫ਼ਤਰੋਂ ਨਿਕਲ ਆਈ।",
        "services|5:1|4|q0": "ਲਕਸ਼ਮੀ ਆਧਾਰ ਕੇਂਦਰ ਕਿਉਂ ਗਈ?",
        "services|5:1|4|q0o0": "ਆਪਣਾ ਪਤਾ ਬਦਲਵਾਉਣ ਲਈ",
        "services|5:1|4|q0o1": "ਪਾਸਪੋਰਟ ਬਣਵਾਉਣ ਲਈ",
        "services|5:1|4|q0o2": "ਜੁਰਮਾਨਾ ਭਰਨ ਲਈ",
        "services|5:1|4|q0o3": "ਨੌਕਰੀ ਲਈ ਅਰਜ਼ੀ ਦੇਣ ਲਈ",
        "services|5:1|4|q1": "ਅਧਿਕਾਰੀ ਨੇ ਪਤੇ ਦੇ ਸਬੂਤ ਵਜੋਂ ਕੀ ਮੰਗਿਆ?",
        "services|5:1|4|q1o0": "ਬਿਜਲੀ ਦੇ ਬਿੱਲ ਦੀ ਫ਼ੋਟੋਕਾਪੀ",
        "services|5:1|4|q1o1": "ਉਸ ਦਾ ਕਾਲਜ ਸਰਟੀਫ਼ਿਕੇਟ",
        "services|5:1|4|q1o2": "ਉਸ ਦੇ ਮੈਨੇਜਰ ਦੀ ਚਿੱਠੀ",
        "services|5:1|4|q1o3": "ਉਸ ਦੀ ਬੈਂਕ ਪਾਸਬੁੱਕ",
        "services|5:1|4|q2": "ਅੱਪਡੇਟ ਵਿੱਚ ਕਿੰਨਾ ਸਮਾਂ ਲੱਗੇਗਾ?",
        "services|5:1|4|q2o0": "ਦਸ ਦਿਨਾਂ ਤੱਕ",
        "services|5:1|4|q2o1": "ਦੋ ਮਹੀਨੇ",
        "services|5:1|4|q2o2": "ਇੱਕ ਦਿਨ",
        "services|5:1|4|q2o3": "ਛੇ ਹਫ਼ਤੇ",
        "services|5:1|5|title": "ਪਾਸਪੋਰਟ ਦਫ਼ਤਰ ਵਿੱਚ",
        "services|5:1|5|scenario": "ਵਿਕਰਮ ਹੁਬਲੀ ਦੇ ਪਾਸਪੋਰਟ ਸੇਵਾ ਕੇਂਦਰ ਵਿੱਚ ਹੈ, ਜਿੱਥੇ ਕਾਊਂਟਰ ਉੱਤੇ ਬੈਠੀ ਅਧਿਕਾਰੀ ਸ਼ਾਲਿਨੀ ਉਸ ਦੇ ਦਸਤਾਵੇਜ਼ ਜਾਂਚਦੀ ਹੈ।",
        "services|5:1|5|l0": "ਨਮਸਕਾਰ। ਕਿਰਪਾ ਕਰਕੇ ਆਪਣੀ ਟੋਕਨ ਪਰਚੀ ਅਤੇ ਅਪੌਇੰਟਮੈਂਟ ਦਾ ਪ੍ਰਿੰਟ ਦਿਓਗੇ?",
        "services|5:1|5|l1": "ਨਮਸਕਾਰ ਮੈਡਮ। ਇਹ ਲਓ। ਇਹ ਮੇਰੀ ਪਾਸਪੋਰਟ ਦੀ ਪਹਿਲੀ ਅਰਜ਼ੀ ਹੈ।",
        "services|5:1|5|l2": "ਸ਼ੁਕਰੀਆ। ਮੈਨੂੰ ਤੁਹਾਡਾ ਆਧਾਰ ਕਾਰਡ ਅਤੇ ਪਤੇ ਦਾ ਇੱਕ ਹੋਰ ਸਬੂਤ ਚਾਹੀਦਾ ਹੈ। ਤੁਸੀਂ ਕੀ ਲੈ ਕੇ ਆਏ ਹੋ?",
        "services|5:1|5|l3": "ਮੇਰੇ ਕੋਲ ਆਧਾਰ ਕਾਰਡ, ਜਨਮ ਤਾਰੀਖ਼ ਲਈ ਦਸਵੀਂ ਦਾ ਸਰਟੀਫ਼ਿਕੇਟ, ਅਤੇ ਗੈਸ ਦਾ ਨਵਾਂ ਬਿੱਲ ਹੈ।",
        "services|5:1|5|l4": "ਗੈਸ ਦਾ ਬਿੱਲ ਤੁਹਾਡੇ ਪਿਤਾ ਜੀ ਦੇ ਨਾਂ ਉੱਤੇ ਹੈ। ਕੀ ਤੁਹਾਡੇ ਕੋਲ ਆਪਣੇ ਨਾਂ ਉੱਤੇ ਕੁਝ ਹੈ?",
        "services|5:1|5|l5": "ਜੀ ਨਹੀਂ, ਪਰ ਮੈਂ ਆਪਣੀ ਬੈਂਕ ਪਾਸਬੁੱਕ ਦੀ ਫ਼ੋਟੋਕਾਪੀ ਲਿਆਇਆ ਹਾਂ ਜਿਸ ਉੱਤੇ ਮੇਰਾ ਪਤਾ ਹੈ। ਕੀ ਉਹ ਚੱਲੇਗੀ?",
        "services|5:1|5|l6": "ਹਾਂ, ਉਹ ਠੀਕ ਹੈ। ਕਿਰਪਾ ਕਰਕੇ ਇੱਥੇ ਦਸਤਖ਼ਤ ਕਰੋ, ਅਤੇ ਫਿਰ ਫ਼ੋਟੋ ਅਤੇ ਉਂਗਲਾਂ ਦੇ ਨਿਸ਼ਾਨਾਂ ਲਈ ਕਾਊਂਟਰ ਬੀ ਉੱਤੇ ਜਾਓ।",
        "services|5:1|5|l7": "ਜ਼ਰੂਰ। ਇਸ ਤੋਂ ਬਾਅਦ ਪੁਲਿਸ ਪੜਤਾਲ ਵਿੱਚ ਕਿੰਨਾ ਸਮਾਂ ਲੱਗੇਗਾ?",
        "services|5:1|5|l8": "ਆਮ ਤੌਰ 'ਤੇ ਦੋ ਤੋਂ ਤਿੰਨ ਹਫ਼ਤੇ। ਜਦੋਂ ਪੁਲਿਸ ਤੁਹਾਡੇ ਕੋਲ ਆਉਣ ਲਈ ਤਿਆਰ ਹੋਵੇਗੀ, ਤੁਹਾਨੂੰ ਐੱਸਐੱਮਐੱਸ ਆ ਜਾਵੇਗਾ।",
        "services|5:1|5|l9": "ਤੁਹਾਡੀ ਮਦਦ ਲਈ ਬਹੁਤ-ਬਹੁਤ ਸ਼ੁਕਰੀਆ, ਮੈਡਮ।",
        "services|5:1|5|q0": "ਵਿਕਰਮ ਗੈਸ ਦਾ ਬਿੱਲ ਕਿਉਂ ਨਹੀਂ ਵਰਤ ਸਕਿਆ?",
        "services|5:1|5|q0o0": "ਉਹ ਉਸ ਦੇ ਪਿਤਾ ਦੇ ਨਾਂ ਉੱਤੇ ਸੀ",
