        "services|5:1|5|q1o0": "ਫ਼ੋਟੋ ਅਤੇ ਉਂਗਲਾਂ ਦੇ ਨਿਸ਼ਾਨਾਂ ਲਈ ਕਾਊਂਟਰ ਬੀ ਉੱਤੇ",
