        "services|5:1|5|q2o2": "ਉਸ ਨੂੰ ਚਿੱਠੀ ਮਿਲੇਗੀ",
        "services|5:1|5|q2o3": "ਉਸ ਨੂੰ ਹਰ ਰੋਜ਼ ਦਫ਼ਤਰ ਆ ਕੇ ਪੁੱਛਣਾ ਪਵੇਗਾ",
        "services|6:1|0|w0": "ਮਕਾਨ ਮਾਲਕ",
        "services|6:1|0|w1": "ਕਿਰਾਏਦਾਰ",
        "services|6:1|0|w2": "ਕਿਰਾਇਆ",
        "services|6:1|0|w3": "ਸਿਕਿਓਰਿਟੀ ਰਕਮ",
        "services|6:1|0|w4": "ਦਲਾਲ",
        "services|6:1|0|w5": "ਫ਼ਰਨੀਚਰ ਸਮੇਤ",
        "services|6:1|1|p0": "ਬੈਂਗਲੁਰੂ ਦੇ ਮਕਾਨ ਮਾਲਕ ਅਕਸਰ ਸਿਕਿਓਰਿਟੀ ਵਜੋਂ ਦਸ ਮਹੀਨਿਆਂ ਦਾ ਕਿਰਾਇਆ ਮੰਗਦੇ ਹਨ।",
        "services|6:1|1|p1": "ਕੀ ਕਿਰਾਏ ਵਿੱਚ ਕੁਝ ਗੁੰਜਾਇਸ਼ ਹੈ, ਜਾਂ ਇਹੀ ਆਖ਼ਰੀ ਰਕਮ ਹੈ?",
        "services|6:1|1|p2": "ਦਲਾਲ ਆਪਣੀ ਫ਼ੀਸ ਵਜੋਂ ਇੱਕ ਮਹੀਨੇ ਦਾ ਕਿਰਾਇਆ ਲੈਂਦਾ ਹੈ।",
        "services|6:1|1|p3": "ਅਸੀਂ ਮੈਟਰੋ ਸਟੇਸ਼ਨ ਦੇ ਨੇੜੇ ਪੂਰੇ ਫ਼ਰਨੀਚਰ ਵਾਲਾ ਫ਼ਲੈਟ ਲੱਭ ਰਹੇ ਹਾਂ।",
        "services|6:1|1|p4": "ਕਿਰਾਏਦਾਰ ਹੋਣ ਦੇ ਨਾਤੇ, ਤੁਹਾਨੂੰ ਹਰ ਅਦਾਇਗੀ ਦੀ ਰਸੀਦ ਲੈਣ ਦਾ ਹੱਕ ਹੈ।",
        "services|6:1|2|w0": "ਕਿਰਾਇਆਨਾਮਾ",
        "services|6:1|2|w1": "ਰੱਖ-ਰਖਾਅ",
        "services|6:1|2|w2": "ਗੁਆਂਢੀ",
        "services|6:1|2|w3": "ਨੋਟਿਸ ਦੀ ਮਿਆਦ",
        "services|6:1|2|w4": "ਖ਼ਾਲੀ ਕਰਨਾ",
        "services|6:1|2|w5": "ਬਿਜਲੀ ਦਾ ਮੀਟਰ",
        "services|6:1|3|p0": "ਦਸਤਖ਼ਤ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਕਿਰਪਾ ਕਰਕੇ ਕਿਰਾਇਆਨਾਮਾ ਧਿਆਨ ਨਾਲ ਪੜ੍ਹੋ।",
        "services|6:1|3|p1": "ਕੀ ਮਹੀਨੇ ਦਾ ਰੱਖ-ਰਖਾਅ ਖ਼ਰਚਾ ਕਿਰਾਏ ਵਿੱਚ ਸ਼ਾਮਲ ਹੈ, ਜਾਂ ਉਹ ਵੱਖਰਾ ਹੈ?",
        "services|6:1|3|p2": "ਸਾਡੇ ਗੁਆਂਢੀ ਮਿਲਣਸਾਰ ਹਨ, ਪਰ ਉਹ ਦੇਰ ਰਾਤ ਤੱਕ ਉੱਚੀ ਆਵਾਜ਼ ਵਿੱਚ ਗਾਣੇ ਲਾਉਂਦੇ ਹਨ।",
        "services|6:1|3|p3": "ਨੋਟਿਸ ਦੀ ਮਿਆਦ ਦੋ ਮਹੀਨੇ ਹੈ, ਇਸ ਲਈ ਸਾਨੂੰ ਜੁਲਾਈ ਤੱਕ ਮਕਾਨ ਮਾਲਕ ਨੂੰ ਦੱਸਣਾ ਪਵੇਗਾ।",
        "services|6:1|3|p4": "ਜਦੋਂ ਅਸੀਂ ਫ਼ਲੈਟ ਖ਼ਾਲੀ ਕਰਾਂਗੇ, ਤਾਂ ਬਿਜਲੀ ਦੇ ਮੀਟਰ ਦੀ ਰੀਡਿੰਗ ਲਿਖ ਲਵਾਂਗੇ।",
        "services|6:1|4|title": "ਮੈਸੂਰੂ ਵਿੱਚ ਨਵਾਂ ਫ਼ਲੈਟ",
        "services|6:1|4|text": "ਮੈਸੂਰੂ ਵਿੱਚ ਨੌਕਰੀ ਮਿਲਣ ਤੋਂ ਬਾਅਦ ਅਨੀਤਾ ਕੁਵੇਂਪੂਨਗਰ ਨੇੜੇ ਇੱਕ ਛੋਟਾ ਫ਼ਲੈਟ ਲੱਭਣ ਲੱਗੀ। ਇੱਕ ਦਲਾਲ ਨੇ ਉਸ ਨੂੰ ਚਾਰ ਥਾਵਾਂ ਦਿਖਾਈਆਂ, ਅਤੇ ਉਸ ਨੂੰ ਦੂਜੀ ਮੰਜ਼ਿਲ ਉੱਤੇ ਫ਼ਰਨੀਚਰ ਵਾਲਾ ਇੱਕ ਕਮਰੇ ਦਾ ਫ਼ਲੈਟ ਪਸੰਦ ਆਇਆ। ਮਕਾਨ ਮਾਲਕ ਮਿਸਟਰ ਗੌੜਾ ਨੇ ਬਾਰ੍ਹਾਂ ਹਜ਼ਾਰ ਰੁਪਏ ਮਹੀਨਾ ਕਿਰਾਇਆ ਅਤੇ ਸੱਠ ਹਜ਼ਾਰ ਸਿਕਿਓਰਿਟੀ ਮੰਗੀ। ਅਨੀਤਾ ਨੇ ਨਿਮਰਤਾ ਨਾਲ ਪੁੱਛਿਆ ਕਿ ਕੀ ਸਿਕਿਓਰਿਟੀ ਥੋੜ੍ਹੀ ਘੱਟ ਹੋ ਸਕਦੀ ਹੈ, ਅਤੇ ਆਖ਼ਰ ਪੰਜਾਹ ਹਜ਼ਾਰ ਉੱਤੇ ਗੱਲ ਬਣ ਗਈ। ਕਿਰਾਇਆਨਾਮੇ ਉੱਤੇ ਦਸਤਖ਼ਤ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਉਸ ਨੇ ਨੋਟਿਸ ਦੀ ਮਿਆਦ ਦੇਖੀ ਅਤੇ ਪੁੱਛਿਆ ਕਿ ਮਹੀਨੇ ਦਾ ਰੱਖ-ਰਖਾਅ ਖ਼ਰਚਾ ਕੌਣ ਦੇਵੇਗਾ। ਉਸ ਨੇ ਬਿਜਲੀ ਦੇ ਮੀਟਰ ਦੀ ਫ਼ੋਟੋ ਵੀ ਖਿੱਚ ਲਈ, ਤਾਂ ਜੋ ਬਾਅਦ ਵਿੱਚ ਬਿੱਲਾਂ ਬਾਰੇ ਕੋਈ ਉਲਝਣ ਨਾ ਹੋਵੇ। ਪਹਿਲੀ ਸ਼ਾਮ ਇੱਕ ਮਿਲਣਸਾਰ ਗੁਆਂਢਣ ਉਸ ਲਈ ਗਰਮ-ਗਰਮ ਬਿਸੀ ਬੇਲੇ ਭਾਤ ਦੀ ਪਲੇਟ ਲੈ ਕੇ ਆਈ।",
        "services|6:1|4|q0": "ਆਖ਼ਰ ਅਨੀਤਾ ਕਿੰਨੀ ਸਿਕਿਓਰਿਟੀ ਦੇਣ ਲਈ ਮੰਨੀ?",
        "services|6:1|4|q0o0": "ਪੰਜਾਹ ਹਜ਼ਾਰ ਰੁਪਏ",
        "services|6:1|4|q0o1": "ਸੱਠ ਹਜ਼ਾਰ ਰੁਪਏ",
        "services|6:1|4|q0o2": "ਬਾਰ੍ਹਾਂ ਹਜ਼ਾਰ ਰੁਪਏ",
