        "services|6:1|4|q1": "ਉਸ ਨੇ ਬਿਜਲੀ ਦੇ ਮੀਟਰ ਦੀ ਫ਼ੋਟੋ ਕਿਉਂ ਖਿੱਚੀ?",
        "services|6:1|4|q1o0": "ਤਾਂ ਜੋ ਬਾਅਦ ਵਿੱਚ ਬਿੱਲਾਂ ਬਾਰੇ ਉਲਝਣ ਨਾ ਹੋਵੇ",
        "services|6:1|4|q1o1": "ਦਲਾਲ ਨੂੰ ਭੇਜਣ ਲਈ",
        "services|6:1|4|q1o2": "ਕਿਉਂਕਿ ਮੀਟਰ ਖ਼ਰਾਬ ਸੀ",
        "services|6:1|4|q1o3": "ਆਪਣੇ ਮਾਪਿਆਂ ਨੂੰ ਫ਼ਲੈਟ ਦਿਖਾਉਣ ਲਈ",
        "services|6:1|4|q2": "ਗੁਆਂਢਣ ਉਸ ਲਈ ਕੀ ਲੈ ਕੇ ਆਈ?",
        "services|6:1|4|q2o0": "ਬਿਸੀ ਬੇਲੇ ਭਾਤ ਦੀ ਪਲੇਟ",
