        "services|6:1|4|q2o3": "ਕੌਫ਼ੀ ਦਾ ਕੱਪ",
        "services|6:1|5|title": "ਮਕਾਨ ਮਾਲਕਣ ਨੂੰ ਫ਼ੋਨ",
        "services|6:1|5|scenario": "ਪੁਣੇ ਵਿੱਚ ਕਿਰਾਏਦਾਰ ਰਾਹੁਲ ਫ਼ਲੈਟ ਦੀ ਇੱਕ ਸਮੱਸਿਆ ਅਤੇ ਫ਼ਲੈਟ ਛੱਡਣ ਬਾਰੇ ਆਪਣੀ ਮਕਾਨ ਮਾਲਕਣ ਮਿਸਿਜ਼ ਜੋਸ਼ੀ ਨੂੰ ਫ਼ੋਨ ਕਰਦਾ ਹੈ।",
        "services|6:1|5|l0": "ਨਮਸਕਾਰ ਮਿਸਿਜ਼ ਜੋਸ਼ੀ। ਮੈਂ ਫ਼ਲੈਟ 3ਬੀ ਤੋਂ ਰਾਹੁਲ ਬੋਲ ਰਿਹਾ ਹਾਂ। ਕੀ ਤੁਹਾਡੇ ਕੋਲ ਇੱਕ ਮਿੰਟ ਹੈ?",
        "services|6:1|5|l1": "ਹਾਂ ਰਾਹੁਲ, ਦੱਸੋ। ਸਭ ਠੀਕ ਤਾਂ ਹੈ?",
        "services|6:1|5|l2": "ਪੂਰੀ ਤਰ੍ਹਾਂ ਨਹੀਂ। ਸੋਮਵਾਰ ਤੋਂ ਬਾਥਰੂਮ ਦੀ ਛੱਤ ਵਿੱਚੋਂ ਪਾਣੀ ਚੋ ਰਿਹਾ ਹੈ, ਅਤੇ ਕੰਧ ਸਿੱਲ੍ਹੀ ਹੁੰਦੀ ਜਾ ਰਹੀ ਹੈ।",
        "services|6:1|5|l3": "ਹਾਏ। ਇਹ ਛੱਤ ਉੱਤੇ ਪਈ ਟੈਂਕੀ ਦਾ ਕੰਮ ਹੋਵੇਗਾ। ਮੈਂ ਕੱਲ੍ਹ ਸਵੇਰੇ ਸਾਡੇ ਪਲੰਬਰ ਸੁਨੀਲ ਨੂੰ ਭੇਜਾਂਗੀ।",
        "services|6:1|5|l4": "ਸ਼ੁਕਰੀਆ। ਕੀ ਮੁਰੰਮਤ ਦਾ ਖ਼ਰਚਾ ਰੱਖ-ਰਖਾਅ ਵਿੱਚੋਂ ਹੋਵੇਗਾ, ਜਾਂ ਮੈਨੂੰ ਦੇਣਾ ਪਵੇਗਾ?",
        "services|6:1|5|l5": "ਫ਼ਿਕਰ ਨਾ ਕਰੋ, ਮਕਾਨ ਮਾਲਕਣ ਹੋਣ ਦੇ ਨਾਤੇ ਇਹ ਮੇਰੀ ਜ਼ਿੰਮੇਵਾਰੀ ਹੈ। ਤੁਸੀਂ ਸਿਰਫ਼ ਬੱਲਬ ਵਰਗੀਆਂ ਛੋਟੀਆਂ ਚੀਜ਼ਾਂ ਦੇ ਪੈਸੇ ਦਿੰਦੇ ਹੋ।",
        "services|6:1|5|l6": "ਤੁਹਾਡੀ ਮਿਹਰਬਾਨੀ। ਇੱਕ ਗੱਲ ਹੋਰ: ਮੇਰੀ ਕੰਪਨੀ ਮਾਰਚ ਵਿੱਚ ਮੇਰੀ ਬਦਲੀ ਨਾਸਿਕ ਕਰ ਰਹੀ ਹੈ।",
        "services|6:1|5|l7": "ਅੱਛਾ। ਸਮਝੌਤੇ ਮੁਤਾਬਕ ਨੋਟਿਸ ਦੀ ਮਿਆਦ ਦੋ ਮਹੀਨੇ ਹੈ, ਇਸ ਲਈ ਕਿਰਪਾ ਕਰਕੇ ਜਨਵਰੀ ਤੱਕ ਮੈਨੂੰ ਲਿਖਤੀ ਨੋਟਿਸ ਦੇ ਦਿਓ।",
        "services|6:1|5|l8": "ਮੈਂ ਇਸ ਹਫ਼ਤੇ ਤੁਹਾਨੂੰ ਈਮੇਲ ਰਾਹੀਂ ਨੋਟਿਸ ਭੇਜ ਦਿਆਂਗਾ। ਅਤੇ ਫ਼ਲੈਟ ਖ਼ਾਲੀ ਕਰਨ ਉੱਤੇ ਸਿਕਿਓਰਿਟੀ ਵਾਪਸ ਮਿਲ ਜਾਵੇਗੀ, ਹੈ ਨਾ?",
        "services|6:1|5|l9": "ਹਾਂ। ਫ਼ਲੈਟ ਅਤੇ ਬਿਜਲੀ ਦਾ ਆਖ਼ਰੀ ਬਿੱਲ ਦੇਖਣ ਤੋਂ ਬਾਅਦ ਮੈਂ ਇੱਕ ਹਫ਼ਤੇ ਵਿੱਚ ਪੈਸੇ ਭੇਜ ਦਿਆਂਗੀ।",
        "services|6:1|5|q0": "ਰਾਹੁਲ ਕਿਹੜੀ ਸਮੱਸਿਆ ਦੱਸਦਾ ਹੈ?",
