        "workplace|1:1|1|p1": "ਤੁਸੀਂ ਕਿਹੜੇ ਵਿਭਾਗ ਵਿੱਚ ਕੰਮ ਕਰਦੇ ਹੋ, ਅਤੇ ਕਿਸ ਨੂੰ ਰਿਪੋਰਟ ਕਰਦੇ ਹੋ?",
        "workplace|1:1|1|p2": "ਕਾਗ਼ਜ਼ਾਂ ਵਿੱਚ ਮੇਰਾ ਅਹੁਦਾ ਸੀਨੀਅਰ ਐਨਾਲਿਸਟ ਹੈ, ਪਰ ਮੇਰੇ ਕੰਮ ਹਰ ਹਫ਼ਤੇ ਬਦਲ ਜਾਂਦੇ ਹਨ।",
        "workplace|1:1|1|p3": "ਮੈਂ ਛੇ ਜਣਿਆਂ ਦੀ ਟੀਮ ਦੀ ਨਿਗਰਾਨੀ ਕਰਦਾ ਹਾਂ ਅਤੇ ਕਲਾਇੰਟਾਂ ਦੀਆਂ ਜ਼ਿਆਦਾਤਰ ਕਾਲਾਂ ਸੰਭਾਲਦਾ ਹਾਂ।",
        "workplace|1:1|1|p4": "ਆਮ ਦਿਨ ਵਿੱਚ ਮੈਂ ਦੁਪਹਿਰ ਦੇ ਖਾਣੇ ਤੋਂ ਪਹਿਲਾਂ ਜ਼ਰੂਰੀ ਕੰਮ ਨਿਬੇੜਦਾ ਹਾਂ ਅਤੇ ਬਾਕੀ ਦੀ ਯੋਜਨਾ ਬਣਾਉਂਦਾ ਹਾਂ।",
        "workplace|1:1|2|w0": "ਮੁੱਖ ਦਫ਼ਤਰ",
