        "workplace|1:1|3|p0": "ਸਾਡਾ ਮੁੱਖ ਦਫ਼ਤਰ ਬੈਂਗਲੁਰੂ ਵਿੱਚ ਹੈ, ਪਰ ਸਾਡੇ ਜ਼ਿਆਦਾਤਰ ਮੁਲਾਜ਼ਮ ਹੁਬਲੀ ਵਿੱਚ ਹਨ।",
        "workplace|1:1|3|p1": "ਅਸੀਂ ਇੱਕ ਛੋਟਾ ਸਟਾਰਟਅੱਪ ਹਾਂ ਜੋ ਕਲੀਨਿਕਾਂ ਲਈ ਬਿਲਿੰਗ ਸਾਫ਼ਟਵੇਅਰ ਬਣਾਉਂਦਾ ਹੈ।",
        "workplace|1:1|3|p2": "ਮੈਸੂਰੂ ਨੇੜੇ ਸਾਡਾ ਕਾਰਖ਼ਾਨਾ ਭਾਰਤ ਦੇ ਜ਼ਿਆਦਾਤਰ ਦੋਪਹੀਆ ਬ੍ਰਾਂਡਾਂ ਲਈ ਬ੍ਰੇਕ ਦੇ ਪੁਰਜ਼ੇ ਬਣਾਉਂਦਾ ਹੈ।",
        "workplace|1:1|3|p3": "ਸਾਨੂੰ ਵੱਖਰਾ ਬਣਾਉਂਦੀ ਹੈ ਪੇਂਡੂ ਸਿਹਤ ਸੇਵਾ ਵਿੱਚ ਸਾਡੀ ਮੁਹਾਰਤ।",
        "workplace|1:1|3|p4": "ਅਸੀਂ ਛੋਟੇ ਕਸਬਿਆਂ ਦੀਆਂ ਦੁਕਾਨਾਂ ਨੂੰ ਆਨਲਾਈਨ ਵਿਕਰੀ ਸ਼ੁਰੂ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਨ ਦੇ ਮਾਹਰ ਹਾਂ।",
        "workplace|1:1|4|title": "ਤੂੰ ਅਸਲ ਵਿੱਚ ਕਰਦਾ ਕੀ ਹੈਂ?",
        "workplace|1:1|4|text": "ਧਾਰਵਾੜ ਵਿੱਚ ਪਰਿਵਾਰ ਦੇ ਇੱਕ ਵਿਆਹ ਵਿੱਚ ਨਿਖਿਲ ਦੇ ਚਾਚੇ ਨੇ ਉਸ ਨੂੰ ਪੁੱਛਿਆ ਕਿ ਉਹ ਅਸਲ ਵਿੱਚ ਕੰਮ ਉੱਤੇ ਕਰਦਾ ਕੀ ਹੈ। ਨਿਖਿਲ ਨੇ ਸਮਝਾਇਆ ਕਿ ਉਹ ਇੱਕ ਸਟਾਰਟਅੱਪ ਵਿੱਚ ਕੰਮ ਕਰਦਾ ਹੈ ਜੋ ਕਿਸਾਨਾਂ ਲਈ ਮਿੱਟੀ ਦੇ ਸੈਂਸਰ ਬਣਾਉਂਦਾ ਹੈ। ਕੰਪਨੀ ਦਾ ਮੁੱਖ ਦਫ਼ਤਰ ਬੈਂਗਲੁਰੂ ਵਿੱਚ ਹੈ, ਪਰ ਸੈਂਸਰ ਹੁਬਲੀ ਨੇੜੇ ਇੱਕ ਛੋਟੇ ਕਾਰਖ਼ਾਨੇ ਵਿੱਚ ਬਣਦੇ ਹਨ। ਉਸ ਦਾ ਅਹੁਦਾ ਪ੍ਰੋਡਕਟ ਇੰਜੀਨੀਅਰ ਹੈ, ਅਤੇ ਉਹ ਟੈਸਟਿੰਗ ਵਿਭਾਗ ਵਿੱਚ ਹੈ। ਉਸ ਦਾ ਮੁੱਖ ਕੰਮ ਹਰ ਨਵੇਂ ਸੈਂਸਰ ਨੂੰ ਕਿਸਾਨਾਂ ਕੋਲ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਜਾਂਚਣਾ ਹੈ। ਉਹ ਦੋ ਜੂਨੀਅਰ ਇੰਜੀਨੀਅਰਾਂ ਦੀ ਨਿਗਰਾਨੀ ਵੀ ਕਰਦਾ ਹੈ ਅਤੇ ਕਾਰਖ਼ਾਨੇ ਦੀ ਟੀਮ ਦੇ ਸਵਾਲ ਸੰਭਾਲਦਾ ਹੈ। ਚਾਚਾ ਜੀ ਮੁਸਕਰਾਏ ਅਤੇ ਬੋਲੇ ਕਿ ਕੰਪਨੀ ਵਿੱਚ ਤਾਂ ਬਹੁਤ ਸਾਰੇ ਮੁਲਾਜ਼ਮ ਹੋਣਗੇ। ਨਿਖਿਲ ਹੱਸ ਪਿਆ ਅਤੇ ਬੋਲਿਆ ਕਿ ਸਿਰਫ਼ ਚਾਲੀ ਲੋਕ ਹਨ, ਪਰ ਹਰ ਇੱਕ ਕੋਲ ਅਸਲੀ ਮੁਹਾਰਤ ਹੈ।",
        "workplace|1:1|4|q0": "ਨਿਖਿਲ ਦੀ ਕੰਪਨੀ ਕੀ ਬਣਾਉਂਦੀ ਹੈ?",
