        "workplace|1:1|5|scenario": "ਬੈਂਗਲੁਰੂ ਵਿੱਚ ਇੱਕ ਕਾਰੋਬਾਰੀ ਸਮਾਗਮ ਵਿੱਚ ਅਨੰਨਿਆ ਅਤੇ ਫ਼ਰਹਾਨ ਪਹਿਲੀ ਵਾਰ ਮਿਲਦੇ ਹਨ ਅਤੇ ਆਪਣੀਆਂ ਨੌਕਰੀਆਂ ਬਾਰੇ ਗੱਲ ਕਰਦੇ ਹਨ।",
        "workplace|1:1|5|l0": "ਹੈਲੋ, ਮੈਂ ਸਹਿਆਦਰੀ ਲੌਜਿਸਟਿਕਸ ਤੋਂ ਫ਼ਰਹਾਨ ਹਾਂ। ਤੁਸੀਂ ਇਸ ਸਮਾਗਮ ਵਿੱਚ ਕਿਵੇਂ ਆਏ?",
        "workplace|1:1|5|l1": "ਤੁਹਾਨੂੰ ਮਿਲ ਕੇ ਖ਼ੁਸ਼ੀ ਹੋਈ। ਮੈਂ ਅਨੰਨਿਆ ਹਾਂ। ਮੈਂ ਇੱਕ ਫ਼ਿਨਟੈੱਕ ਸਟਾਰਟਅੱਪ ਵਿੱਚ ਕਸਟਮਰ ਸਪੋਰਟ ਟੀਮ ਦੀ ਮੁਖੀ ਹਾਂ।",
        "workplace|1:1|5|l2": "ਦਿਲਚਸਪ। ਤੁਹਾਡੀ ਕੰਪਨੀ ਅਸਲ ਵਿੱਚ ਕੀ ਕਰਦੀ ਹੈ?",
        "workplace|1:1|5|l3": "ਅਸੀਂ ਇੱਕ ਐਪ ਬਣਾਈ ਹੈ ਜੋ ਛੋਟੇ ਦੁਕਾਨਦਾਰਾਂ ਨੂੰ ਹਿਸਾਬ-ਕਿਤਾਬ ਰੱਖਣ ਅਤੇ ਡਿਜੀਟਲ ਪੇਮੈਂਟ ਲੈਣ ਵਿੱਚ ਮਦਦ ਕਰਦੀ ਹੈ।",
        "workplace|1:1|5|l4": "ਅਤੇ ਤੁਹਾਡਾ ਇੱਕ ਆਮ ਦਿਨ ਕਿਹੋ ਜਿਹਾ ਹੁੰਦਾ ਹੈ?",
        "workplace|1:1|5|l5": "ਮੈਂ ਆਪਣੀ ਟੀਮ ਨਾਲ ਇੱਕ ਛੋਟੀ ਜਿਹੀ ਕਾਲ ਨਾਲ ਸ਼ੁਰੂ ਕਰਦੀ ਹਾਂ, ਅਤੇ ਫਿਰ ਔਖੀਆਂ ਸ਼ਿਕਾਇਤਾਂ ਖ਼ੁਦ ਸੰਭਾਲਦੀ ਹਾਂ।",
        "workplace|1:1|5|l6": "ਇਹ ਤਾਂ ਮਿਹਨਤ ਵਾਲਾ ਕੰਮ ਲੱਗਦਾ ਹੈ। ਤੁਹਾਡੀ ਟੀਮ ਕਿੰਨੀ ਵੱਡੀ ਹੈ?",
        "workplace|1:1|5|l7": "ਦੋ ਸ਼ਿਫ਼ਟਾਂ ਵਿੱਚ ਬਾਰ੍ਹਾਂ ਲੋਕ। ਤੇ ਤੁਸੀਂ? ਤੁਹਾਡੀ ਭੂਮਿਕਾ ਕੀ ਹੈ?",
        "workplace|1:1|5|l8": "ਮੈਂ ਰੂਟ ਪਲੈਨਰ ਹਾਂ। ਮੋਟੇ ਤੌਰ 'ਤੇ, ਮੈਂ ਇਹ ਪੱਕਾ ਕਰਦਾ ਹਾਂ ਕਿ ਸਾਡੇ ਟਰੱਕ ਸਭ ਤੋਂ ਤੇਜ਼ ਅਤੇ ਸਸਤੇ ਰਾਹਾਂ ਤੋਂ ਜਾਣ।",
        "workplace|1:1|5|l9": "ਤਾਂ ਤੁਹਾਡੀ ਬਦੌਲਤ ਮੇਰੇ ਪਾਰਸਲ ਸਮੇਂ ਸਿਰ ਪਹੁੰਚਦੇ ਹਨ! ਸੰਪਰਕ ਵਿੱਚ ਰਹਾਂਗੇ।",
        "workplace|1:1|5|q0": "ਅਨੰਨਿਆ ਦੀ ਕੰਪਨੀ ਨੇ ਕੀ ਬਣਾਇਆ ਹੈ?",
        "workplace|1:1|5|q0o0": "ਛੋਟੇ ਦੁਕਾਨਦਾਰਾਂ ਲਈ ਇੱਕ ਐਪ",
