        "workplace|1:1|5|q2o3": "ਉਹ ਐਪਾਂ ਬਣਾਉਂਦਾ ਹੈ",
        "workplace|2:1|0|w0": "ਮਿਊਟ ਕਰਨਾ",
        "workplace|2:1|0|w1": "ਵੈੱਬਕੈਮ",
        "workplace|2:1|0|w2": "ਹੈੱਡਸੈੱਟ",
        "workplace|2:1|0|w3": "ਵੇਟਿੰਗ ਰੂਮ",
        "workplace|2:1|0|w4": "ਮੇਜ਼ਬਾਨ",
        "workplace|2:1|0|w5": "ਭਾਗੀਦਾਰ",
        "workplace|2:1|1|p0": "ਕਿਰਪਾ ਕਰਕੇ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਬੋਲ ਨਹੀਂ ਰਹੇ, ਸਾਰੇ ਆਪਣੇ ਆਪ ਨੂੰ ਮਿਊਟ ਰੱਖੋ।",
        "workplace|2:1|1|p1": "ਮੈਂ ਹੁਣੇ ਟੀਮ ਚੈਟ ਵਿੱਚ ਮੀਟਿੰਗ ਦਾ ਲਿੰਕ ਭੇਜਿਆ ਹੈ।",
        "workplace|2:1|1|p2": "ਰਵੀ, ਤੁਹਾਡਾ ਵੈੱਬਕੈਮ ਬੰਦ ਹੈ; ਕੀ ਤੁਸੀਂ ਇੱਕ ਮਿੰਟ ਲਈ ਇਸ ਨੂੰ ਚਾਲੂ ਕਰ ਸਕਦੇ ਹੋ?",
        "workplace|2:1|1|p3": "ਸਿਰਫ਼ ਮੇਜ਼ਬਾਨ ਹੀ ਭਾਗੀਦਾਰਾਂ ਨੂੰ ਵੇਟਿੰਗ ਰੂਮ ਵਿੱਚੋਂ ਅੰਦਰ ਆਉਣ ਦੇ ਸਕਦਾ ਹੈ।",
        "workplace|2:1|1|p4": "ਕਿਰਪਾ ਕਰਕੇ ਹੈੱਡਸੈੱਟ ਲਾ ਲਓ ਤਾਂ ਜੋ ਸਾਨੂੰ ਤੁਹਾਡੇ ਪਿੱਛੇ ਦਾ ਟ੍ਰੈਫ਼ਿਕ ਨਾ ਸੁਣੇ।",
        "workplace|2:1|2|w0": "ਅਸਥਿਰ",
        "workplace|2:1|2|w1": "ਲੈਗ",
        "workplace|2:1|2|w2": "ਅਟਕ ਜਾਣਾ",
        "workplace|2:1|2|w3": "ਗੂੰਜ",
        "workplace|2:1|2|w4": "ਰਿਕਾਰਡਿੰਗ",
        "workplace|2:1|2|w5": "ਫ਼ਾਲੋ-ਅੱਪ",
        "workplace|2:1|3|p0": "ਮਾਫ਼ ਕਰਨਾ, ਮੇਰਾ ਕਨੈਕਸ਼ਨ ਅਸਥਿਰ ਹੈ; ਮੈਂ ਆਪਣੀ ਵੀਡੀਓ ਬੰਦ ਕਰ ਦਿੰਦਾ ਹਾਂ।",
        "workplace|2:1|3|p1": "ਕੁਝ ਸਕਿੰਟਾਂ ਦਾ ਲੈਗ ਹੈ, ਇਸ ਲਈ ਆਓ ਇੱਕ-ਦੂਜੇ ਦੀ ਗੱਲ ਵਿੱਚ ਨਾ ਬੋਲੀਏ।",
        "workplace|2:1|3|p2": "ਤੁਹਾਡੀ ਸਕਰੀਨ ਅਟਕ ਗਈ ਹੈ; ਕੀ ਤੁਸੀਂ ਇਸ ਨੂੰ ਦੁਬਾਰਾ ਸ਼ੇਅਰ ਕਰ ਸਕਦੇ ਹੋ?",
        "workplace|2:1|3|p3": "ਮੈਨੂੰ ਗੂੰਜ ਸੁਣਾਈ ਦੇ ਰਹੀ ਹੈ; ਕਿਸੇ ਦੇ ਲੈਪਟਾਪ ਦਾ ਸਪੀਕਰ ਉਸ ਦੇ ਮਾਈਕ ਦੇ ਬਹੁਤ ਨੇੜੇ ਹੈ।",
        "workplace|2:1|3|p4": "ਮੈਂ ਅੱਜ ਸ਼ਾਮ ਤੱਕ ਰਿਕਾਰਡਿੰਗ ਅਤੇ ਇੱਕ ਛੋਟੀ ਫ਼ਾਲੋ-ਅੱਪ ਈਮੇਲ ਭੇਜ ਦਿਆਂਗਾ।",
        "workplace|2:1|4|title": "ਵਾਰ-ਵਾਰ ਅਟਕਣ ਵਾਲੀ ਕਾਲ",
        "workplace|2:1|4|text": "ਹਰ ਸੋਮਵਾਰ ਦੀਪਾ ਮੈਸੂਰੂ ਵਾਲੀ ਆਪਣੀ ਟੀਮ ਅਤੇ ਪੁਣੇ ਦੀ ਸੇਲਜ਼ ਟੀਮ ਵਿਚਕਾਰ ਇੱਕ ਵੀਡੀਓ ਕਾਲ ਦੀ ਮੇਜ਼ਬਾਨੀ ਕਰਦੀ ਹੈ। ਪਿਛਲੇ ਹਫ਼ਤੇ ਕਾਲ ਦੀ ਸ਼ੁਰੂਆਤ ਮਾੜੀ ਹੋਈ। ਬਾਰ੍ਹਾਂ ਭਾਗੀਦਾਰ ਜੁੜੇ, ਪਰ ਉਨ੍ਹਾਂ ਵਿੱਚੋਂ ਤਿੰਨ ਲਿੰਕ ਨਹੀਂ ਖੋਲ੍ਹ ਸਕੇ। ਫਿਰ ਉੱਚੀ ਗੂੰਜ ਆਉਣ ਲੱਗੀ, ਕਿਉਂਕਿ ਸੁਰੇਸ਼ ਇੱਕੋ ਵੇਲੇ ਆਪਣੇ ਲੈਪਟਾਪ ਅਤੇ ਫ਼ੋਨ ਦੋਵਾਂ ਤੋਂ ਜੁੜ ਗਿਆ ਸੀ। ਜਦੋਂ ਦੀਪਾ ਨੇ ਆਪਣੀ ਸਕਰੀਨ ਸ਼ੇਅਰ ਕਰਨੀ ਸ਼ੁਰੂ ਕੀਤੀ, ਉਹ ਅਟਕ ਗਈ, ਅਤੇ ਉਸ ਦੀ ਆਵਾਜ਼ ਪੁਣੇ ਬਹੁਤ ਦੇਰੀ ਨਾਲ ਪਹੁੰਚ ਰਹੀ ਸੀ। ਉਸ ਨੇ ਸ਼ਾਂਤੀ ਨਾਲ ਸਭ ਨੂੰ ਮਿਊਟ ਕਰਨ, ਵੈੱਬਕੈਮ ਬੰਦ ਕਰਨ ਅਤੇ ਹੈੱਡਸੈੱਟ ਵਰਤਣ ਲਈ ਕਿਹਾ। ਕਨੈਕਸ਼ਨ ਸੁਧਰ ਗਿਆ, ਅਤੇ ਮੀਟਿੰਗ ਸਿਰਫ਼ ਦਸ ਮਿੰਟ ਦੇਰ ਨਾਲ ਖ਼ਤਮ ਹੋਈ। ਉਸ ਸ਼ਾਮ ਦੀਪਾ ਨੇ ਰਿਕਾਰਡਿੰਗ ਅਤੇ ਇੱਕ ਸਾਫ਼ ਫ਼ਾਲੋ-ਅੱਪ ਈਮੇਲ ਭੇਜੀ, ਜਿਸ ਵਿੱਚ ਹਰ ਫ਼ੈਸਲਾ ਅਤੇ ਹਰ ਆਖ਼ਰੀ ਤਾਰੀਖ਼ ਲਿਖੀ ਸੀ।",
        "workplace|2:1|4|q0": "ਉੱਚੀ ਗੂੰਜ ਕਿਉਂ ਆ ਰਹੀ ਸੀ?",
        "workplace|2:1|4|q0o0": "ਸੁਰੇਸ਼ ਇੱਕੋ ਵੇਲੇ ਦੋ ਡਿਵਾਈਸਾਂ ਤੋਂ ਜੁੜ ਗਿਆ ਸੀ",
        "workplace|2:1|4|q0o1": "ਦੀਪਾ ਦਾ ਹੈੱਡਸੈੱਟ ਟੁੱਟਿਆ ਹੋਇਆ ਸੀ",
        "workplace|2:1|4|q0o2": "ਪੁਣੇ ਦੇ ਦਫ਼ਤਰ ਵਿੱਚ ਬਹੁਤ ਰੌਲਾ ਸੀ",
        "workplace|2:1|4|q0o3": "ਲਿੰਕ ਗ਼ਲਤ ਸੀ",
        "workplace|2:1|4|q1": "ਦੀਪਾ ਨੇ ਸਭ ਨੂੰ ਕੀ ਕਰਨ ਲਈ ਕਿਹਾ?",
        "workplace|2:1|4|q1o0": "ਮਿਊਟ ਕਰਨ, ਵੈੱਬਕੈਮ ਬੰਦ ਕਰਨ ਅਤੇ ਹੈੱਡਸੈੱਟ ਵਰਤਣ ਲਈ",
        "workplace|2:1|4|q1o1": "ਕਾਲ ਛੱਡ ਕੇ ਕੱਲ੍ਹ ਦੁਬਾਰਾ ਜੁੜਨ ਲਈ",
        "workplace|2:1|4|q1o2": "ਉਸ ਨੂੰ ਫ਼ੋਨ ਉੱਤੇ ਕਾਲ ਕਰਨ ਲਈ",
        "workplace|2:1|4|q1o3": "ਮੈਸੂਰੂ ਦਫ਼ਤਰ ਆਉਣ ਲਈ",
