        "workplace|2:1|4|q2o0": "ਰਿਕਾਰਡਿੰਗ ਅਤੇ ਫ਼ਾਲੋ-ਅੱਪ ਈਮੇਲ",
        "workplace|2:1|4|q2o1": "ਮੀਟਿੰਗ ਦਾ ਨਵਾਂ ਲਿੰਕ",
        "workplace|2:1|4|q2o2": "ਦੇਰ ਨਾਲ ਆਉਣ ਵਾਲਿਆਂ ਦੀ ਸੂਚੀ",
        "workplace|2:1|4|q2o3": "ਸੁਰੇਸ਼ ਲਈ ਨਵਾਂ ਹੈੱਡਸੈੱਟ",
        "workplace|2:1|5|title": "ਕੀ ਤੁਹਾਨੂੰ ਮੇਰੀ ਸਕਰੀਨ ਦਿਸ ਰਹੀ ਹੈ?",
        "workplace|2:1|5|scenario": "ਕਾਰਤਿਕ ਹੁਬਲੀ ਵਿੱਚ ਆਪਣੇ ਘਰੋਂ ਇੱਕ ਆਨਲਾਈਨ ਪ੍ਰੋਜੈਕਟ ਮੀਟਿੰਗ ਵਿੱਚ ਜੁੜਦਾ ਹੈ। ਮੇਜ਼ਬਾਨ ਮੀਰਾ ਉਸ ਦੀ ਆਵਾਜ਼ ਅਤੇ ਸਕਰੀਨ ਵਿੱਚ ਮਦਦ ਕਰਦੀ ਹੈ।",
        "workplace|2:1|5|l0": "ਹੈਲੋ ਕਾਰਤਿਕ, ਤੁਸੀਂ ਸਾਨੂੰ ਦਿਸ ਰਹੇ ਹੋ, ਪਰ ਤੁਸੀਂ ਮਿਊਟ ਉੱਤੇ ਹੋ।",
        "workplace|2:1|5|l1": "ਮਾਫ਼ ਕਰਨਾ। ਕੀ ਹੁਣ ਮੇਰੀ ਆਵਾਜ਼ ਆ ਰਹੀ ਹੈ?",
        "workplace|2:1|5|l2": "ਹਾਂ, ਬਿਲਕੁਲ ਸਾਫ਼। ਕੀ ਤੁਸੀਂ ਆਪਣੀ ਸਕਰੀਨ ਸ਼ੇਅਰ ਕਰਕੇ ਸਾਨੂੰ ਟੈਸਟ ਦੇ ਨਤੀਜੇ ਸਮਝਾ ਸਕਦੇ ਹੋ?",
        "workplace|2:1|5|l3": "ਜ਼ਰੂਰ, ਇੱਕ ਸਕਿੰਟ। ਕੀ ਸਭ ਨੂੰ ਮੇਰੀ ਸਕਰੀਨ ਦਿਸ ਰਹੀ ਹੈ?",
        "workplace|2:1|5|l4": "ਸਾਨੂੰ ਇੱਕ ਸਪ੍ਰੈੱਡਸ਼ੀਟ ਦਿਸ ਰਹੀ ਹੈ, ਪਰ ਲੱਗਦਾ ਹੈ ਉਹ ਅਟਕ ਗਈ ਹੈ।",
        "workplace|2:1|5|l5": "ਮੇਰਾ ਕਨੈਕਸ਼ਨ ਵਾਰ-ਵਾਰ ਟੁੱਟ ਰਿਹਾ ਹੈ। ਮੈਂ ਆਪਣੀ ਵੀਡੀਓ ਬੰਦ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰਦਾ ਹਾਂ।",
        "workplace|2:1|5|l6": "ਹੁਣ ਬਹੁਤ ਵਧੀਆ, ਹੁਣ ਚੱਲ ਰਹੀ ਹੈ। ਕਿਰਪਾ ਕਰਕੇ ਅੱਗੇ ਵਧੋ।",
        "workplace|2:1|5|l7": "ਸ਼ੁਕਰੀਆ। ਜਿਵੇਂ ਤੁਸੀਂ ਦੇਖ ਸਕਦੇ ਹੋ, ਇਸ ਹਫ਼ਤੇ ਦੇ ਨੱਬੇ ਪ੍ਰਤੀਸ਼ਤ ਟੈਸਟ ਪਾਸ ਹੋ ਗਏ ਹਨ।",
        "workplace|2:1|5|l8": "ਸ਼ਾਨਦਾਰ ਕੰਮ। ਮੈਂ ਇਹ ਰਿਕਾਰਡ ਕਰ ਰਹੀ ਹਾਂ, ਤਾਂ ਜੋ ਪੁਣੇ ਦੀ ਟੀਮ ਬਾਅਦ ਵਿੱਚ ਦੇਖ ਸਕੇ।",
        "workplace|2:1|5|l9": "ਬਹੁਤ ਵਧੀਆ। ਕਾਲ ਤੋਂ ਬਾਅਦ ਮੈਂ ਫ਼ੇਲ੍ਹ ਹੋਏ ਟੈਸਟਾਂ ਨਾਲ ਇੱਕ ਛੋਟਾ ਫ਼ਾਲੋ-ਅੱਪ ਵੀ ਭੇਜ ਦਿਆਂਗਾ।",
        "workplace|2:1|5|q0": "ਕਾਰਤਿਕ ਦੀ ਪਹਿਲੀ ਸਮੱਸਿਆ ਕੀ ਸੀ?",
