        "workplace|2:1|5|q0o1": "ਉਸ ਕੋਲ ਲੈਪਟਾਪ ਨਹੀਂ ਸੀ",
        "workplace|2:1|5|q0o2": "ਉਹ ਗ਼ਲਤ ਮੀਟਿੰਗ ਵਿੱਚ ਜੁੜ ਗਿਆ",
        "workplace|2:1|5|q0o3": "ਉਸ ਦਾ ਵੈੱਬਕੈਮ ਟੁੱਟਿਆ ਹੋਇਆ ਸੀ",
        "workplace|2:1|5|q1": "ਕਾਰਤਿਕ ਨੇ ਅਟਕੀ ਹੋਈ ਸਕਰੀਨ ਕਿਵੇਂ ਠੀਕ ਕੀਤੀ?",
        "workplace|2:1|5|q1o0": "ਉਸ ਨੇ ਆਪਣੀ ਵੀਡੀਓ ਬੰਦ ਕਰ ਦਿੱਤੀ",
        "workplace|2:1|5|q1o1": "ਉਸ ਨੇ ਨਵਾਂ ਹੈੱਡਸੈੱਟ ਖ਼ਰੀਦਿਆ",
        "workplace|2:1|5|q1o2": "ਉਸ ਨੇ ਮੀਰਾ ਨੂੰ ਫ਼ੋਨ ਕੀਤਾ",
        "workplace|2:1|5|q1o3": "ਉਹ ਦਫ਼ਤਰ ਚਲਾ ਗਿਆ",
        "workplace|2:1|5|q2": "ਮੀਰਾ ਮੀਟਿੰਗ ਰਿਕਾਰਡ ਕਿਉਂ ਕਰ ਰਹੀ ਹੈ?",
        "workplace|2:1|5|q2o0": "ਤਾਂ ਜੋ ਪੁਣੇ ਦੀ ਟੀਮ ਬਾਅਦ ਵਿੱਚ ਦੇਖ ਸਕੇ",
        "workplace|2:1|5|q2o1": "ਇਹ ਦੇਖਣ ਲਈ ਕਿ ਕੌਣ ਦੇਰ ਨਾਲ ਆਇਆ",
