        "workplace|2:1|5|q2o3": "ਕਿਸੇ ਕਲਾਇੰਟ ਨੂੰ ਭੇਜਣ ਲਈ",
        "workplace|3:1|0|w0": "ਸਲਾਈਡ",
        "workplace|3:1|0|w1": "ਰੂਪ-ਰੇਖਾ",
        "workplace|3:1|0|w2": "ਸੰਖੇਪ ਝਾਤ",
        "workplace|3:1|0|w3": "ਚਾਰਟ",
        "workplace|3:1|0|w4": "ਉਭਾਰਨਾ",
        "workplace|3:1|0|w5": "ਅੰਕੜਾ",
        "workplace|3:1|1|p0": "ਆਓ, ਮੈਂ ਅੱਜ ਦੀਆਂ ਗੱਲਾਂ ਦੀ ਇੱਕ ਸੰਖੇਪ ਝਾਤ ਨਾਲ ਸ਼ੁਰੂ ਕਰਾਂ।",
        "workplace|3:1|1|p1": "ਜਿਵੇਂ ਤੁਸੀਂ ਇਸ ਸਲਾਈਡ ਉੱਤੇ ਦੇਖ ਸਕਦੇ ਹੋ, ਮਾਰਚ ਤੋਂ ਬਾਅਦ ਵਿਕਰੀ ਦੁੱਗਣੀ ਹੋ ਗਈ।",
        "workplace|3:1|1|p2": "ਮੈਂ ਰੂਪ-ਰੇਖਾ ਸਾਦੀ ਰੱਖੀ ਹੈ: ਸਮੱਸਿਆ, ਹੱਲ, ਖ਼ਰਚਾ ਅਤੇ ਸਮਾਂ-ਸੀਮਾ।",
        "workplace|3:1|1|p3": "ਇਹ ਚਾਰਟ ਪਿਛਲੇ ਦੋ ਸਾਲਾਂ ਦੇ ਸਾਡੇ ਮਹੀਨੇਵਾਰ ਅੰਕੜੇ ਦਿਖਾਉਂਦਾ ਹੈ।",
        "workplace|3:1|1|p4": "ਮੈਂ ਖ਼ਾਸ ਤੌਰ 'ਤੇ ਇੱਕ ਅੰਕੜਾ ਉਭਾਰਨਾ ਚਾਹੁੰਦਾ ਹਾਂ: ਸਾਡੇ ਖ਼ਰਚੇ ਬਾਰ੍ਹਾਂ ਪ੍ਰਤੀਸ਼ਤ ਘਟ ਗਏ।",
        "workplace|3:1|2|w0": "ਪ੍ਰੋਜੈਕਟਰ",
        "workplace|3:1|2|w1": "ਅਭਿਆਸ ਕਰਨਾ",
        "workplace|3:1|2|w2": "ਪਰਚਾ",
        "workplace|3:1|2|w3": "ਸਪਸ਼ਟ ਕਰਨਾ",
        "workplace|3:1|2|w4": "ਸਮਾਪਤ ਕਰਨਾ",
        "workplace|3:1|2|w5": "ਸਾਰ ਦੱਸਣਾ",
        "workplace|3:1|3|p0": "ਕੀ ਕੋਈ ਪ੍ਰੋਜੈਕਟਰ ਦੇਖ ਸਕਦਾ ਹੈ? ਸਲਾਈਡਾਂ ਬਹੁਤ ਹਨੇਰੀਆਂ ਲੱਗ ਰਹੀਆਂ ਹਨ।",
        "workplace|3:1|3|p1": "ਮੈਂ ਪੂਰੀ ਪੇਸ਼ਕਾਰੀ ਦਾ ਦੋ ਵਾਰ ਅਭਿਆਸ ਕੀਤਾ, ਇਸ ਲਈ ਮੈਨੂੰ ਪੱਕਾ ਪਤਾ ਹੈ ਕਿ ਇਸ ਵਿੱਚ ਕਿੰਨਾ ਸਮਾਂ ਲੱਗਦਾ ਹੈ।",
        "workplace|3:1|3|p2": "ਸਾਰੇ ਅੰਕੜਿਆਂ ਵਾਲਾ ਇੱਕ ਪਰਚਾ ਹੈ, ਇਸ ਲਈ ਤੁਹਾਨੂੰ ਨੋਟ ਲਿਖਣ ਦੀ ਲੋੜ ਨਹੀਂ।",
        "workplace|3:1|3|p3": "ਇਹ ਚੰਗਾ ਸਵਾਲ ਹੈ; ਮੈਂ ਸਪਸ਼ਟ ਕਰਦਾ ਹਾਂ ਕਿ ਕੁੱਲ ਖ਼ਰਚੇ ਤੋਂ ਮੇਰਾ ਕੀ ਮਤਲਬ ਸੀ।",
        "workplace|3:1|3|p4": "ਸਮਾਪਤ ਕਰਦਿਆਂ, ਮੈਂ ਇੱਕ ਮਿੰਟ ਵਿੱਚ ਤਿੰਨ ਮੁੱਖ ਗੱਲਾਂ ਦਾ ਸਾਰ ਦੱਸਦਾ ਹਾਂ।",
        "workplace|3:1|4|title": "ਰੇਖਾ ਦਾ ਖ਼ਾਸ ਦਿਨ",
        "workplace|3:1|4|text": "ਹੁਬਲੀ ਦੀ ਮਾਰਕੀਟਿੰਗ ਐਗਜ਼ੈਕਟਿਵ ਰੇਖਾ ਨੇ ਕੰਪਨੀ ਦੇ ਡਾਇਰੈਕਟਰਾਂ ਸਾਹਮਣੇ ਸਾਲਾਨਾ ਨਤੀਜੇ ਪੇਸ਼ ਕਰਨੇ ਸਨ। ਉਸ ਨੇ ਇੱਕ ਸਾਦੀ ਰੂਪ-ਰੇਖਾ ਅਤੇ ਸਿਰਫ਼ ਅੱਠ ਸਲਾਈਡਾਂ ਤਿਆਰ ਕੀਤੀਆਂ, ਹਰ ਇੱਕ ਉੱਤੇ ਇੱਕ ਸਾਫ਼ ਚਾਰਟ। ਇੱਕ ਰਾਤ ਪਹਿਲਾਂ ਉਸ ਨੇ ਆਪਣੀ ਭੈਣ ਸਾਹਮਣੇ ਪੂਰੀ ਪੇਸ਼ਕਾਰੀ ਦਾ ਤਿੰਨ ਵਾਰ ਅਭਿਆਸ ਕੀਤਾ। ਉਸ ਦਿਨ ਮੀਟਿੰਗ ਰੂਮ ਦਾ ਪ੍ਰੋਜੈਕਟਰ ਉਸ ਦੇ ਸ਼ੁਰੂ ਕਰਨ ਤੋਂ ਪੰਜ ਮਿੰਟ ਪਹਿਲਾਂ ਬੰਦ ਹੋ ਗਿਆ। ਚੰਗੀ ਕਿਸਮਤ ਨੂੰ ਰੇਖਾ ਨੇ ਸਾਰੇ ਜ਼ਰੂਰੀ ਅੰਕੜਿਆਂ ਵਾਲੇ ਪਰਚੇ ਛਪਵਾ ਲਏ ਸਨ। ਉਸ ਨੇ ਇੱਕ ਛੋਟੀ ਜਿਹੀ ਸੰਖੇਪ ਝਾਤ ਨਾਲ ਸ਼ੁਰੂ ਕੀਤਾ ਅਤੇ ਫਿਰ ਉਭਾਰਿਆ ਕਿ ਡਿਲਿਵਰੀ ਦੇ ਖ਼ਰਚੇ ਕਿੰਨੇ ਘਟੇ ਹਨ। ਜਦੋਂ ਇੱਕ ਡਾਇਰੈਕਟਰ ਨੇ ਬੇਲਗਾਵੀ ਦੀ ਨਵੀਂ ਦੁਕਾਨ ਬਾਰੇ ਪੁੱਛਿਆ, ਤਾਂ ਉਸ ਨੇ ਸ਼ਾਂਤੀ ਨਾਲ ਅੰਕੜੇ ਸਪਸ਼ਟ ਕੀਤੇ। ਉਸ ਨੇ ਆਪਣੀਆਂ ਤਿੰਨ ਮੁੱਖ ਗੱਲਾਂ ਦਾ ਸਾਰ ਦੱਸ ਕੇ ਸਮਾਪਤੀ ਕੀਤੀ, ਅਤੇ ਡਾਇਰੈਕਟਰਾਂ ਨੇ ਇੰਨੀ ਸਪਸ਼ਟਤਾ ਲਈ ਉਸ ਦਾ ਧੰਨਵਾਦ ਕੀਤਾ।",
        "workplace|3:1|4|q0": "ਰੇਖਾ ਨੇ ਕਿੰਨੀਆਂ ਸਲਾਈਡਾਂ ਤਿਆਰ ਕੀਤੀਆਂ?",
