        "workplace|3:1|4|q2o1": "ਉਸ ਨੇ ਆਨਲਾਈਨ ਵੀਡੀਓ ਦੇਖੀਆਂ",
        "workplace|3:1|4|q2o2": "ਉਸ ਨੇ ਡਾਇਰੈਕਟਰਾਂ ਨਾਲ ਅਭਿਆਸ ਕੀਤਾ",
        "workplace|3:1|4|q2o3": "ਉਸ ਨੇ ਬਿਲਕੁਲ ਅਭਿਆਸ ਨਹੀਂ ਕੀਤਾ",
        "workplace|3:1|5|title": "ਇੱਕ ਰਿਹਰਸਲ",
        "workplace|3:1|5|scenario": "ਸੰਜੇ ਪੁਣੇ ਦੇ ਦਫ਼ਤਰ ਵਿੱਚ ਆਪਣੀ ਮੈਨੇਜਰ ਲਕਸ਼ਮੀ ਨਾਲ ਇੱਕ ਕਲਾਇੰਟ ਪੇਸ਼ਕਾਰੀ ਦਾ ਅਭਿਆਸ ਕਰਦਾ ਹੈ।",
        "workplace|3:1|5|l0": "ਚਲੋ ਸੰਜੇ, ਸਮਝ ਲਓ ਕਿ ਮੈਂ ਕਲਾਇੰਟ ਹਾਂ। ਜਦੋਂ ਤਿਆਰ ਹੋਵੋ, ਸ਼ੁਰੂ ਕਰੋ।",
        "workplace|3:1|5|l1": "ਸਭ ਨੂੰ ਨਮਸਕਾਰ, ਅਤੇ ਸਾਨੂੰ ਬੁਲਾਉਣ ਲਈ ਸ਼ੁਕਰੀਆ। ਅੱਜ ਮੈਂ ਤੁਹਾਨੂੰ ਤੁਹਾਡੀ ਨਵੀਂ ਵੈੱਬਸਾਈਟ ਲਈ ਸਾਡੀ ਯੋਜਨਾ ਸਮਝਾਉਣਾ ਚਾਹੁੰਦਾ ਹਾਂ।",
        "workplace|3:1|5|l2": "ਵਧੀਆ ਸ਼ੁਰੂਆਤ। ਤੁਸੀਂ ਆਪਣੀ ਗੱਲ ਨੂੰ ਕਿਵੇਂ ਤਰਤੀਬ ਦਿਓਗੇ?",
        "workplace|3:1|5|l3": "ਮੈਂ ਤਿੰਨ ਗੱਲਾਂ ਕਰਾਂਗਾ: ਸਾਨੂੰ ਕੀ ਲੱਭਿਆ, ਅਸੀਂ ਕੀ ਸੁਝਾਅ ਦਿੰਦੇ ਹਾਂ, ਅਤੇ ਇਸ ਦਾ ਖ਼ਰਚਾ ਕਿੰਨਾ ਹੋਵੇਗਾ।",
        "workplace|3:1|5|l4": "ਬਹੁਤ ਸਾਫ਼। ਜੇ ਕਲਾਇੰਟ ਅੱਧ ਵਿਚਾਲੇ ਕੋਈ ਸਵਾਲ ਪੁੱਛ ਲਵੇ ਤਾਂ?",
        "workplace|3:1|5|l5": "ਮੈਂ ਉਨ੍ਹਾਂ ਦਾ ਸ਼ੁਕਰੀਆ ਕਰਾਂਗਾ, ਸਵਾਲ ਲਿਖ ਲਵਾਂਗਾ ਅਤੇ ਕਹਾਂਗਾ ਕਿ ਮੈਂ ਅਖ਼ੀਰ ਵਿੱਚ ਇਸ ਦਾ ਜਵਾਬ ਦਿਆਂਗਾ।",
        "workplace|3:1|5|l6": "ਵਧੀਆ। ਅਤੇ ਤੁਹਾਡੀ ਆਖ਼ਰੀ ਸਲਾਈਡ ਉੱਤੇ ਕੀ ਹੈ?",
        "workplace|3:1|5|l7": "ਤਿੰਨਾਂ ਗੱਲਾਂ ਦਾ ਸਾਰ ਅਤੇ ਇੱਕ ਸਾਫ਼ ਅਗਲਾ ਕਦਮ: ਅਗਲੇ ਸ਼ੁੱਕਰਵਾਰ ਇੱਕ ਮੀਟਿੰਗ।",
        "workplace|3:1|5|l8": "ਸ਼ਾਨਦਾਰ। ਬੱਸ ਥੋੜ੍ਹਾ ਹੌਲੀ ਬੋਲੋ, ਅਤੇ ਸਕਰੀਨ ਵੱਲ ਨਹੀਂ, ਸੁਣਨ ਵਾਲਿਆਂ ਵੱਲ ਦੇਖੋ।",
        "workplace|3:1|5|l9": "ਸ਼ੁਕਰੀਆ ਲਕਸ਼ਮੀ। ਮੈਂ ਅੱਜ ਰਾਤ ਇੱਕ ਵਾਰ ਹੋਰ ਅਭਿਆਸ ਕਰਾਂਗਾ।",
        "workplace|3:1|5|q0": "ਸੰਜੇ ਕੀ ਪੇਸ਼ ਕਰ ਰਿਹਾ ਹੈ?",
        "workplace|3:1|5|q0o0": "ਕਲਾਇੰਟ ਦੀ ਨਵੀਂ ਵੈੱਬਸਾਈਟ ਦੀ ਯੋਜਨਾ",
        "workplace|3:1|5|q0o1": "ਸਾਲਾਨਾ ਵਿਕਰੀ ਦੇ ਨਤੀਜੇ",
        "workplace|3:1|5|q0o2": "ਇੱਕ ਨਵੀਂ ਦਫ਼ਤਰੀ ਇਮਾਰਤ",
        "workplace|3:1|5|q0o3": "ਇੱਕ ਸਿਖਲਾਈ ਕੋਰਸ",
        "workplace|3:1|5|q1": "ਜੇ ਕਲਾਇੰਟ ਵਿੱਚੋਂ ਟੋਕੇ ਤਾਂ ਸੰਜੇ ਕੀ ਕਰੇਗਾ?",
        "workplace|3:1|5|q1o0": "ਸ਼ੁਕਰੀਆ ਕਰਕੇ ਅਖ਼ੀਰ ਵਿੱਚ ਜਵਾਬ ਦੇਵੇਗਾ",
        "workplace|3:1|5|q1o1": "ਸਵਾਲ ਨੂੰ ਅਣਡਿੱਠਾ ਕਰੇਗਾ",
