        "workplace|3:1|5|q1o3": "ਲਕਸ਼ਮੀ ਨੂੰ ਜਵਾਬ ਦੇਣ ਲਈ ਕਹੇਗਾ",
        "workplace|3:1|5|q2": "ਲਕਸ਼ਮੀ ਕੀ ਸਲਾਹ ਦਿੰਦੀ ਹੈ?",
