        "workplace|4:1|0|w3": "ਕੋਟੇਸ਼ਨ",
        "workplace|4:1|0|w4": "ਸਮਾਂ-ਸੀਮਾ",
        "workplace|4:1|0|w5": "ਡੈਮੋ",
        "workplace|4:1|1|p0": "ਕੋਈ ਸੁਝਾਅ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ, ਕੀ ਤੁਸੀਂ ਸਾਨੂੰ ਆਪਣੀਆਂ ਲੋੜਾਂ ਬਾਰੇ ਹੋਰ ਦੱਸ ਸਕਦੇ ਹੋ?",
        "workplace|4:1|1|p1": "ਅਸੀਂ ਵੀਰਵਾਰ ਤੱਕ ਤੁਹਾਨੂੰ ਪੂਰੇ ਵੇਰਵੇ ਵਾਲਾ ਪ੍ਰਸਤਾਵ ਅਤੇ ਕੋਟੇਸ਼ਨ ਭੇਜ ਦਿਆਂਗੇ।",
        "workplace|4:1|1|p2": "ਸਾਡੀ ਮੋਟੀ ਸਮਾਂ-ਸੀਮਾ ਛੇ ਹਫ਼ਤੇ ਹੈ, ਪਰ ਸਾਈਟ ਦੇਖਣ ਤੋਂ ਬਾਅਦ ਮੈਂ ਪੱਕਾ ਦੱਸਾਂਗਾ।",
        "workplace|4:1|1|p3": "ਕੀ ਇੱਕ ਛੋਟਾ ਡੈਮੋ ਤੁਹਾਨੂੰ ਇਹ ਫ਼ੈਸਲਾ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰੇਗਾ ਕਿ ਕਿਹੜਾ ਪਲੈਨ ਤੁਹਾਡੇ ਲਈ ਠੀਕ ਹੈ?",
        "workplace|4:1|1|p4": "ਇਹ ਕਲਾਇੰਟ ਐਪ ਦੀਆਂ ਸਕਰੀਨਾਂ ਸਮੇਤ ਸਭ ਕੁਝ ਕੰਨੜ ਵਿੱਚ ਚਾਹੁੰਦਾ ਹੈ।",
        "workplace|4:1|2|w0": "ਰਵਾਨਾ ਕਰਨਾ",
        "workplace|4:1|2|w1": "ਇਨਵੌਇਸ",
        "workplace|4:1|2|w2": "ਖਿਝ",
        "workplace|4:1|2|w3": "ਮਾਫ਼ ਕਰਨਾ",
        "workplace|4:1|2|w4": "ਪੱਕਾ ਵਾਅਦਾ",
        "workplace|4:1|2|w5": "ਭਰੋਸਾ ਦਿਵਾਉਣਾ",
        "workplace|4:1|3|p0": "ਤੁਹਾਡਾ ਆਰਡਰ ਸੋਮਵਾਰ ਨੂੰ ਸਾਡੇ ਪੁਣੇ ਵਾਲੇ ਗੋਦਾਮ ਤੋਂ ਰਵਾਨਾ ਕੀਤਾ ਜਾਵੇਗਾ।",
        "workplace|4:1|3|p1": "ਇਨਵੌਇਸ ਵਿੱਚ ਗ਼ਲਤ ਰਕਮ ਲਿਖੀ ਹੈ, ਇਸ ਲਈ ਮੈਂ ਅਕਾਊਂਟਸ ਨੂੰ ਇਸ ਨੂੰ ਠੀਕ ਕਰਨ ਲਈ ਕਹਾਂਗਾ।",
        "workplace|4:1|3|p2": "ਮੈਂ ਤੁਹਾਡੀ ਖਿਝ ਸਮਝਦਾ ਹਾਂ, ਅਤੇ ਅੱਜ ਹੀ ਇਹ ਮਾਮਲਾ ਆਪਣੇ ਮੈਨੇਜਰ ਤੱਕ ਪਹੁੰਚਾਵਾਂਗਾ।",
        "workplace|4:1|3|p3": "ਦੇਰੀ ਦੀ ਭਰਪਾਈ ਲਈ ਅਸੀਂ ਇਸ ਵਾਰ ਡਿਲਿਵਰੀ ਚਾਰਜ ਮਾਫ਼ ਕਰ ਦਿਆਂਗੇ।",
        "workplace|4:1|3|p4": "ਮੈਂ ਤੁਹਾਨੂੰ ਭਰੋਸਾ ਦਿਵਾਉਂਦਾ ਹਾਂ ਕਿ ਬਦਲਵੀਂ ਚੀਜ਼ ਸ਼ੁੱਕਰਵਾਰ ਤੱਕ ਪਹੁੰਚ ਜਾਵੇਗੀ; ਇਹ ਮੇਰਾ ਨਿੱਜੀ ਵਾਅਦਾ ਹੈ।",
        "workplace|4:1|4|title": "ਮੀਨੂ ਕਾਰਡ ਜੋ ਕਦੇ ਪਹੁੰਚੇ ਹੀ ਨਹੀਂ",
        "workplace|4:1|4|text": "ਇਮਰਾਨ ਬੈਂਗਲੁਰੂ ਦੀ ਇੱਕ ਛਪਾਈ ਕੰਪਨੀ ਵਿੱਚ ਕਲਾਇੰਟਾਂ ਦੇ ਖਾਤੇ ਸੰਭਾਲਦਾ ਹੈ। ਇੱਕ ਸੋਮਵਾਰ ਮੈਸੂਰੂ ਵਿੱਚ ਹੋਟਲ ਚਲਾਉਣ ਵਾਲੀ ਮਿਸਿਜ਼ ਸ਼ੈੱਟੀ ਨੇ ਉਸ ਨੂੰ ਬਹੁਤ ਨਾਰਾਜ਼ ਹੋ ਕੇ ਫ਼ੋਨ ਕੀਤਾ। ਉਨ੍ਹਾਂ ਦੇ ਨਵੇਂ ਮੀਨੂ ਕਾਰਡ ਨਹੀਂ ਪਹੁੰਚੇ ਸਨ, ਭਾਵੇਂ ਕੋਟੇਸ਼ਨ ਵਿੱਚ ਇੱਕ ਹਫ਼ਤੇ ਅੰਦਰ ਡਿਲਿਵਰੀ ਦਾ ਵਾਅਦਾ ਸੀ। ਇਮਰਾਨ ਨੇ ਬਿਨਾਂ ਟੋਕੇ ਸੁਣਿਆ ਅਤੇ ਫਿਰ ਉਨ੍ਹਾਂ ਦੀਆਂ ਲੋੜਾਂ ਦੁਹਰਾਈਆਂ ਤਾਂ ਜੋ ਪੱਕਾ ਹੋ ਜਾਵੇ ਕਿ ਉਹ ਸਹੀ ਸਮਝਿਆ ਹੈ। ਉਸ ਨੂੰ ਪਤਾ ਲੱਗਾ ਕਿ ਇਨਵੌਇਸ ਵਿੱਚ ਗ਼ਲਤੀ ਕਾਰਨ ਆਰਡਰ ਕਦੇ ਰਵਾਨਾ ਹੀ ਨਹੀਂ ਹੋਇਆ ਸੀ। ਉਸ ਨੇ ਮਾਮਲਾ ਆਪਣੇ ਮੈਨੇਜਰ ਤੱਕ ਪਹੁੰਚਾਇਆ ਅਤੇ ਉਸੇ ਦੁਪਹਿਰ ਕੋਰੀਅਰ ਦਾ ਪ੍ਰਬੰਧ ਕੀਤਾ। ਦੇਰੀ ਦੀ ਭਰਪਾਈ ਲਈ ਕੰਪਨੀ ਨੇ ਬਿੱਲ ਵਿੱਚੋਂ ਦਸ ਪ੍ਰਤੀਸ਼ਤ ਘਟਾ ਦਿੱਤਾ। ਇਮਰਾਨ ਨੇ ਉਨ੍ਹਾਂ ਨੂੰ ਭਰੋਸਾ ਦਿਵਾਇਆ ਕਿ ਅੱਗੇ ਤੋਂ ਉਹ ਉਨ੍ਹਾਂ ਦੇ ਆਰਡਰ ਖ਼ੁਦ ਜਾਂਚੇਗਾ, ਅਤੇ ਉਹ ਕੰਪਨੀ ਨਾਲ ਜੁੜੇ ਰਹੇ।",
        "workplace|4:1|4|q0": "ਮਿਸਿਜ਼ ਸ਼ੈੱਟੀ ਨਾਰਾਜ਼ ਕਿਉਂ ਸਨ?",
        "workplace|4:1|4|q0o0": "ਉਨ੍ਹਾਂ ਦੇ ਮੀਨੂ ਕਾਰਡ ਨਹੀਂ ਪਹੁੰਚੇ ਸਨ",
        "workplace|4:1|4|q0o1": "ਕਾਰਡਾਂ ਵਿੱਚ ਸ਼ਬਦ-ਜੋੜਾਂ ਦੀਆਂ ਗ਼ਲਤੀਆਂ ਸਨ",
        "workplace|4:1|4|q0o2": "ਕੀਮਤ ਬਹੁਤ ਜ਼ਿਆਦਾ ਸੀ",
        "workplace|4:1|4|q0o3": "ਇਮਰਾਨ ਨੇ ਉਨ੍ਹਾਂ ਦਾ ਫ਼ੋਨ ਨਹੀਂ ਚੁੱਕਿਆ",
        "workplace|4:1|4|q1": "ਆਰਡਰ ਰਵਾਨਾ ਕਿਉਂ ਨਹੀਂ ਹੋਇਆ ਸੀ?",
        "workplace|4:1|4|q1o0": "ਇਨਵੌਇਸ ਵਿੱਚ ਗ਼ਲਤੀ ਸੀ",
