        "workplace|4:1|4|q1o3": "ਮਿਸਿਜ਼ ਸ਼ੈੱਟੀ ਨੇ ਪੈਸੇ ਨਹੀਂ ਦਿੱਤੇ ਸਨ",
        "workplace|4:1|4|q2": "ਕੰਪਨੀ ਨੇ ਦੇਰੀ ਦੀ ਭਰਪਾਈ ਕਿਵੇਂ ਕੀਤੀ?",
        "workplace|4:1|4|q2o0": "ਬਿੱਲ ਵਿੱਚੋਂ ਦਸ ਪ੍ਰਤੀਸ਼ਤ ਘਟਾ ਦਿੱਤਾ",
        "workplace|4:1|4|q2o1": "ਮੁਫ਼ਤ ਵਿਜ਼ਿਟਿੰਗ ਕਾਰਡ ਛਾਪੇ",
