        "workplace|4:1|4|q2o3": "ਉਨ੍ਹਾਂ ਦੇ ਸਾਰੇ ਪੈਸੇ ਵਾਪਸ ਕਰ ਦਿੱਤੇ",
        "workplace|4:1|5|title": "ਨਵਾਂ ਕਲਾਇੰਟ",
        "workplace|4:1|5|scenario": "ਹੁਬਲੀ ਦੀ ਇੱਕ ਫ਼ਰਨੀਚਰ ਕੰਪਨੀ ਦੀ ਸੇਲਜ਼ ਮੈਨੇਜਰ ਨੇਹਾ ਨੂੰ ਵਿਕਰਮ ਕੁਲਕਰਨੀ ਦਾ ਫ਼ੋਨ ਆਉਂਦਾ ਹੈ, ਜਿਸ ਨੂੰ ਨਵੇਂ ਦਫ਼ਤਰ ਲਈ ਫ਼ਰਨੀਚਰ ਚਾਹੀਦਾ ਹੈ।",
        "workplace|4:1|5|l0": "ਨਮਸਕਾਰ ਮਿਸਟਰ ਕੁਲਕਰਨੀ। ਸੰਪਰਕ ਕਰਨ ਲਈ ਸ਼ੁਕਰੀਆ। ਦੱਸੋ, ਅਸੀਂ ਕੀ ਮਦਦ ਕਰ ਸਕਦੇ ਹਾਂ?",
        "workplace|4:1|5|l1": "ਅਸੀਂ ਬੇਲਗਾਵੀ ਵਿੱਚ ਨਵਾਂ ਦਫ਼ਤਰ ਖੋਲ੍ਹ ਰਹੇ ਹਾਂ ਅਤੇ ਸਾਨੂੰ ਚਾਲੀ ਲੋਕਾਂ ਲਈ ਮੇਜ਼ ਅਤੇ ਕੁਰਸੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ।",
        "workplace|4:1|5|l2": "ਬਹੁਤ ਵਧੀਆ। ਕੀ ਤੁਸੀਂ ਆਪਣੀਆਂ ਲੋੜਾਂ ਬਾਰੇ ਥੋੜ੍ਹਾ ਹੋਰ ਦੱਸ ਸਕਦੇ ਹੋ? ਕੀ ਤੁਹਾਡੇ ਮਨ ਵਿੱਚ ਕੋਈ ਬਜਟ ਜਾਂ ਡਿਜ਼ਾਈਨ ਹੈ?",
        "workplace|4:1|5|l3": "ਕੁਝ ਸਾਦਾ ਅਤੇ ਆਰਾਮਦਾਇਕ। ਸਾਡਾ ਬਜਟ ਲਗਭਗ ਅੱਠ ਲੱਖ ਰੁਪਏ ਹੈ।",
        "workplace|4:1|5|l4": "ਇਹ ਕਾਫ਼ੀ ਹੋ ਸਕਦਾ ਹੈ। ਤੁਹਾਨੂੰ ਸਾਰਾ ਸਾਮਾਨ ਕਦੋਂ ਤੱਕ ਚਾਹੀਦਾ ਹੈ?",
        "workplace|4:1|5|l5": "ਅਗਲੇ ਮਹੀਨੇ ਦੀ ਪੰਦਰਾਂ ਤਾਰੀਖ਼ ਤੱਕ। ਇਹ ਤਾਰੀਖ਼ ਸਾਡੇ ਲਈ ਬਹੁਤ ਜ਼ਰੂਰੀ ਹੈ।",
        "workplace|4:1|5|l6": "ਸਮਝ ਗਈ। ਮੈਂ ਸ਼ੁੱਕਰਵਾਰ ਤੱਕ ਦੋ ਵਿਕਲਪਾਂ ਵਾਲਾ ਪ੍ਰਸਤਾਵ ਅਤੇ ਕੋਟੇਸ਼ਨ ਭੇਜ ਦਿਆਂਗੀ।",
        "workplace|4:1|5|l7": "ਕੀ ਤੁਹਾਡੀ ਟੀਮ ਸਾਈਟ ਉੱਤੇ ਫ਼ਿਟਿੰਗ ਵੀ ਕਰ ਸਕਦੀ ਹੈ?",
        "workplace|4:1|5|l8": "ਹਾਂ, ਫ਼ਿਟਿੰਗ ਸ਼ਾਮਲ ਹੈ। ਅਤੇ ਮੈਂ ਤੁਹਾਨੂੰ ਭਰੋਸਾ ਦਿਵਾਉਂਦੀ ਹਾਂ ਕਿ ਅਸੀਂ ਤੁਹਾਡੀ ਆਖ਼ਰੀ ਤਾਰੀਖ਼ ਪੂਰੀ ਕਰਾਂਗੇ।",
        "workplace|4:1|5|l9": "ਵਧੀਆ। ਫਿਰ ਮੈਂ ਤੁਹਾਡੇ ਪ੍ਰਸਤਾਵ ਦੀ ਉਡੀਕ ਕਰਾਂਗਾ।",
