        "workplace|5:1|1|p1": "ਕੀ ਮੈਂ ਸ਼ੁੱਕਰਵਾਰ ਨੂੰ ਆਪਣੇ ਭਰਾ ਦੇ ਕਾਲਜ ਦਾਖ਼ਲੇ ਲਈ ਅੱਧੇ ਦਿਨ ਦੀ ਛੁੱਟੀ ਲੈ ਸਕਦਾ ਹਾਂ?",
