        "workplace|5:1|3|p0": "ਕੀ ਤੁਸੀਂ ਅਗਲੇ ਸ਼ਨੀਵਾਰ ਮੇਰੇ ਨਾਲ ਸ਼ਿਫ਼ਟ ਦੀ ਅਦਲਾ-ਬਦਲੀ ਕਰ ਲਓਗੇ?",
        "workplace|5:1|3|p1": "ਪ੍ਰਿਆ ਮੇਰੀ ਗ਼ੈਰਹਾਜ਼ਰੀ ਵਿੱਚ ਮੇਰੀਆਂ ਕਾਲਾਂ ਸੰਭਾਲਣ ਲਈ ਮੰਨ ਗਈ ਹੈ।",
        "workplace|5:1|3|p2": "ਮੈਂ ਵੀਰਵਾਰ ਨੂੰ ਪੂਰੀ ਤਰ੍ਹਾਂ ਕੰਮ ਸੌਂਪ ਦਿਆਂਗਾ ਤਾਂ ਜੋ ਕੁਝ ਵੀ ਛੁੱਟ ਨਾ ਜਾਵੇ।",
        "workplace|5:1|3|p3": "ਕੀ ਅਸੀਂ ਆਪਣੀ ਸਮੀਖਿਆ ਮੀਟਿੰਗ ਦਾ ਸਮਾਂ ਬਦਲ ਕੇ ਅਗਲੇ ਹਫ਼ਤੇ ਕਰ ਸਕਦੇ ਹਾਂ? ਸੋਮਵਾਰ ਨੂੰ ਮੇਰੀ ਛੁੱਟੀ ਹੈ।",
        "workplace|5:1|3|p4": "ਸਾਡਾ ਮੈਨੇਜਰ ਲਚਕੀਲਾ ਹੈ, ਬੱਸ ਅਸੀਂ ਘੱਟੋ-ਘੱਟ ਇੱਕ ਹਫ਼ਤਾ ਪਹਿਲਾਂ ਤੋਂ ਪੁੱਛ ਲਈਏ।",
        "workplace|5:1|4|title": "ਉਡੁਪੀ ਵਿੱਚ ਵਿਆਹ",
        "workplace|5:1|4|text": "ਸੌਮਿਆ ਬੈਂਗਲੁਰੂ ਵਿੱਚ ਇੱਕ ਬੈਂਕ ਦੇ ਮੁੱਖ ਦਫ਼ਤਰ ਦੀ ਪੇਮੈਂਟਸ ਟੀਮ ਵਿੱਚ ਕੰਮ ਕਰਦੀ ਹੈ। ਉਡੁਪੀ ਵਿੱਚ ਉਸ ਦੀ ਚਚੇਰੀ ਭੈਣ ਦਾ ਵਿਆਹ ਮਾਰਚ ਦੇ ਆਖ਼ਰੀ ਹਫ਼ਤੇ ਸੀ, ਜੋ ਸਾਲ ਦਾ ਸਭ ਤੋਂ ਰੁਝੇਵੇਂ ਵਾਲਾ ਸਮਾਂ ਹੁੰਦਾ ਹੈ। ਉਸ ਨੇ ਆਪਣੀਆਂ ਬਾਕੀ ਛੁੱਟੀਆਂ ਦੇਖੀਆਂ ਤਾਂ ਹਾਲੇ ਨੌਂ ਦਿਨ ਬਚੇ ਸਨ। ਤਿੰਨ ਹਫ਼ਤੇ ਪਹਿਲਾਂ ਤੋਂ ਉਸ ਨੇ ਆਪਣੇ ਮੈਨੇਜਰ ਮਿਸਟਰ ਭੱਟ ਤੋਂ ਚਾਰ ਦਿਨਾਂ ਦੀ ਛੁੱਟੀ ਮੰਗੀ ਅਤੇ ਨਿਮਰਤਾ ਨਾਲ ਕਾਰਨ ਸਮਝਾਇਆ। ਉਸ ਨੇ ਵਿਆਹ ਤੋਂ ਅਗਲੇ ਦਿਨ ਘਰੋਂ ਕੰਮ ਕਰਨ ਦੀ ਪੇਸ਼ਕਸ਼ ਵੀ ਕੀਤੀ। ਮਿਸਟਰ ਭੱਟ ਲਚਕੀਲੇ ਸਨ, ਪਰ ਉਨ੍ਹਾਂ ਨੇ ਪੁੱਛਿਆ ਕਿ ਮਹੀਨੇ ਦੇ ਅਖ਼ੀਰ ਦੀਆਂ ਰਿਪੋਰਟਾਂ ਕੌਣ ਸੰਭਾਲੇਗਾ। ਸੌਮਿਆ ਨੇ ਆਪਣੇ ਸਾਥੀ ਰਾਕੇਸ਼ ਨਾਲ ਦੋ ਸ਼ਿਫ਼ਟਾਂ ਦੀ ਅਦਲਾ-ਬਦਲੀ ਕੀਤੀ ਅਤੇ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਪੂਰਾ ਕੰਮ ਸੌਂਪਣ ਦਾ ਵਾਅਦਾ ਕੀਤਾ। ਉਸ ਦੀ ਯੋਜਨਾ ਤੋਂ ਖ਼ੁਸ਼ ਹੋ ਕੇ ਮਿਸਟਰ ਭੱਟ ਨੇ ਉਸੇ ਦੁਪਹਿਰ ਛੁੱਟੀ ਮਨਜ਼ੂਰ ਕਰ ਦਿੱਤੀ।",
        "workplace|5:1|4|q0": "ਸੌਮਿਆ ਨੂੰ ਛੁੱਟੀ ਕਿਉਂ ਚਾਹੀਦੀ ਸੀ?",
        "workplace|5:1|4|q0o0": "ਉਡੁਪੀ ਵਿੱਚ ਆਪਣੀ ਚਚੇਰੀ ਭੈਣ ਦੇ ਵਿਆਹ ਲਈ",
        "workplace|5:1|4|q0o1": "ਕਿਉਂਕਿ ਉਹ ਬਿਮਾਰ ਸੀ",
        "workplace|5:1|4|q0o2": "ਇੱਕ ਸਿਖਲਾਈ ਕੋਰਸ ਲਈ",
        "workplace|5:1|4|q0o3": "ਨਵੇਂ ਘਰ ਵਿੱਚ ਜਾਣ ਲਈ",
        "workplace|5:1|4|q1": "ਉਸ ਦੀਆਂ ਹਾਲੇ ਕਿੰਨੀਆਂ ਛੁੱਟੀਆਂ ਬਾਕੀ ਸਨ?",
        "workplace|5:1|4|q1o0": "ਨੌਂ",
        "workplace|5:1|4|q1o1": "ਚਾਰ",
        "workplace|5:1|4|q1o2": "ਤਿੰਨ",
        "workplace|5:1|4|q1o3": "ਬਾਰ੍ਹਾਂ",
        "workplace|5:1|4|q2": "ਸੌਮਿਆ ਨਾਲ ਸ਼ਿਫ਼ਟਾਂ ਦੀ ਅਦਲਾ-ਬਦਲੀ ਕਿਸ ਨੇ ਕੀਤੀ?",
        "workplace|5:1|4|q2o0": "ਰਾਕੇਸ਼ ਨੇ",
        "workplace|5:1|4|q2o1": "ਮਿਸਟਰ ਭੱਟ ਨੇ",
        "workplace|5:1|4|q2o2": "ਉਸ ਦੀ ਚਚੇਰੀ ਭੈਣ ਨੇ",
        "workplace|5:1|4|q2o3": "ਕਿਸੇ ਨੇ ਨਹੀਂ",
        "workplace|5:1|5|title": "ਤੜਕੇ ਦਾ ਫ਼ੋਨ",
        "workplace|5:1|5|scenario": "ਅਰੁਣ ਸਵੇਰੇ-ਸਵੇਰੇ ਆਪਣੀ ਟੀਮ ਲੀਡ ਸ਼ਾਲਿਨੀ ਨੂੰ ਫ਼ੋਨ ਕਰਦਾ ਹੈ, ਕਿਉਂਕਿ ਉਸ ਦੀ ਮਾਂ ਦੀ ਸਿਹਤ ਠੀਕ ਨਹੀਂ।",
        "workplace|5:1|5|l0": "ਨਮਸਕਾਰ ਸ਼ਾਲਿਨੀ। ਇੰਨੀ ਸਵੇਰੇ ਫ਼ੋਨ ਕਰਨ ਲਈ ਮਾਫ਼ੀ। ਕੀ ਤੁਹਾਡੇ ਕੋਲ ਇੱਕ ਮਿੰਟ ਹੈ?",
        "workplace|5:1|5|l1": "ਹਾਂ ਅਰੁਣ, ਜ਼ਰੂਰ। ਸਭ ਠੀਕ ਤਾਂ ਹੈ?",
        "workplace|5:1|5|l2": "ਨਹੀਂ। ਕੱਲ੍ਹ ਰਾਤ ਮੇਰੀ ਮਾਂ ਡਿੱਗ ਪਈ, ਅਤੇ ਮੈਨੂੰ ਕੁਝ ਟੈਸਟਾਂ ਲਈ ਉਨ੍ਹਾਂ ਨੂੰ ਹਸਪਤਾਲ ਲੈ ਕੇ ਜਾਣਾ ਹੈ।",
        "workplace|5:1|5|l3": "ਓਹ, ਇਹ ਸੁਣ ਕੇ ਦੁੱਖ ਹੋਇਆ। ਕਿਰਪਾ ਕਰਕੇ ਉਨ੍ਹਾਂ ਦਾ ਖ਼ਿਆਲ ਰੱਖੋ। ਕੀ ਤੁਹਾਨੂੰ ਪੂਰਾ ਦਿਨ ਚਾਹੀਦਾ ਹੋਵੇਗਾ?",
        "workplace|5:1|5|l4": "ਮੇਰੇ ਖ਼ਿਆਲ ਵਿੱਚ ਹਾਂ। ਮੈਂ ਅੱਜ ਛੁੱਟੀ ਲੈਣਾ ਚਾਹੁੰਦਾ ਹਾਂ, ਅਤੇ ਸ਼ਾਇਦ ਕੱਲ੍ਹ ਘਰੋਂ ਕੰਮ ਕਰਾਂ।",
        "workplace|5:1|5|l5": "ਠੀਕ ਹੈ। ਤਿੰਨ ਵਜੇ ਵਾਲੀ ਕਲਾਇੰਟ ਕਾਲ ਦਾ ਕੀ?",
        "workplace|5:1|5|l6": "ਦੀਪਕ ਪ੍ਰੋਜੈਕਟ ਨੂੰ ਚੰਗੀ ਤਰ੍ਹਾਂ ਜਾਣਦਾ ਹੈ। ਮੈਂ ਉਸ ਨੂੰ ਪਹਿਲਾਂ ਹੀ ਪੁੱਛ ਲਿਆ ਹੈ, ਅਤੇ ਉਹ ਖ਼ੁਸ਼ੀ ਨਾਲ ਕਾਲ ਸੰਭਾਲ ਲਵੇਗਾ।",
        "workplace|5:1|5|l7": "ਵਧੀਆ। ਕਿਰਪਾ ਕਰਕੇ ਉਸ ਨੂੰ ਆਪਣੇ ਨੋਟ ਭੇਜ ਦਿਓ, ਅਤੇ ਜਦੋਂ ਸਮਾਂ ਮਿਲੇ ਪੋਰਟਲ ਉੱਤੇ ਛੁੱਟੀ ਲਈ ਅਰਜ਼ੀ ਪਾ ਦਿਓ।",
        "workplace|5:1|5|l8": "ਮੈਂ ਇੱਕ ਘੰਟੇ ਵਿੱਚ ਕਰ ਦਿਆਂਗਾ। ਸਮਝਣ ਲਈ ਸ਼ੁਕਰੀਆ, ਸ਼ਾਲਿਨੀ।",
        "workplace|5:1|5|l9": "ਕੋਈ ਗੱਲ ਨਹੀਂ। ਰੱਬ ਕਰੇ ਤੁਹਾਡੀ ਮਾਂ ਛੇਤੀ ਠੀਕ ਹੋ ਜਾਣ।",
        "workplace|5:1|5|q0": "ਅਰੁਣ ਨੂੰ ਛੁੱਟੀ ਕਿਉਂ ਚਾਹੀਦੀ ਹੈ?",
        "workplace|5:1|5|q0o0": "ਉਸ ਦੀ ਮਾਂ ਡਿੱਗ ਪਈ ਸੀ",
        "workplace|5:1|5|q0o1": "ਉਸ ਨੂੰ ਬੁਖ਼ਾਰ ਹੈ",
        "workplace|5:1|5|q0o2": "ਉਸ ਨੇ ਇੱਕ ਵਿਆਹ ਵਿੱਚ ਜਾਣਾ ਹੈ",
        "workplace|5:1|5|q0o3": "ਉਸ ਦੀ ਰੇਲਗੱਡੀ ਰੱਦ ਹੋ ਗਈ",
        "workplace|5:1|5|q1": "ਕਲਾਇੰਟ ਕਾਲ ਕੌਣ ਸੰਭਾਲੇਗਾ?",
        "workplace|5:1|5|q1o0": "ਦੀਪਕ",
        "workplace|5:1|5|q1o1": "ਸ਼ਾਲਿਨੀ",
        "workplace|5:1|5|q1o2": "ਅਰੁਣ",
        "workplace|5:1|5|q1o3": "ਕੋਈ ਨਹੀਂ, ਕਾਲ ਰੱਦ ਹੈ",
        "workplace|5:1|5|q2": "ਸ਼ਾਲਿਨੀ ਅਰੁਣ ਨੂੰ ਕੀ ਕਰਨ ਲਈ ਕਹਿੰਦੀ ਹੈ?",
        "workplace|5:1|5|q2o0": "ਦੀਪਕ ਨੂੰ ਆਪਣੇ ਨੋਟ ਭੇਜੇ ਅਤੇ ਪੋਰਟਲ ਉੱਤੇ ਅਰਜ਼ੀ ਪਾਵੇ",
        "workplace|5:1|5|q2o1": "ਦੁਪਹਿਰ ਦੇ ਖਾਣੇ ਤੋਂ ਬਾਅਦ ਦਫ਼ਤਰ ਆਵੇ",
