        "opinions|2:1|1|p0": "ਕ੍ਰਿਕਟ ਬਾਰੇ ਮੈਂ ਅਤੇ ਮੇਰੇ ਪਿਤਾ ਜੀ ਘੱਟ ਹੀ ਇੱਕ-ਮੱਤ ਹੁੰਦੇ ਹਾਂ।",
        "opinions|2:1|1|p1": "ਇਹ ਜਾਇਜ਼ ਗੱਲ ਹੈ; ਮੈਂ ਖ਼ਰਚੇ ਬਾਰੇ ਨਹੀਂ ਸੋਚਿਆ ਸੀ।",
        "opinions|2:1|1|p2": "ਮੈਂ ਪੂਰੀ ਤਰ੍ਹਾਂ ਸਹਿਮਤ ਹਾਂ; ਲਾਇਬ੍ਰੇਰੀ ਐਤਵਾਰ ਨੂੰ ਵੀ ਖੁੱਲ੍ਹੀ ਰਹਿਣੀ ਚਾਹੀਦੀ ਹੈ।",
        "opinions|2:1|1|p3": "ਮੈਂ ਮੰਨਦਾ ਹਾਂ ਕਿ ਤੁਸੀਂ ਸਹੀ ਸੀ; ਸਕਲੇਸ਼ਪੁਰ ਵਾਲਾ ਰਾਹ ਕਿਤੇ ਛੇਤੀ ਪਹੁੰਚਾਉਂਦਾ ਸੀ।",
        "opinions|2:1|1|p4": "ਕੁਝ ਹੱਦ ਤੱਕ ਤੁਸੀਂ ਸਹੀ ਹੋ, ਪਰ ਆਓ ਕੋਈ ਸਾਂਝੀ ਗੱਲ ਲੱਭੀਏ।",
        "opinions|2:1|2|w0": "ਪੂਰੇ ਸਤਿਕਾਰ ਨਾਲ",
