        "opinions|2:1|2|w3": "ਮਨ ਬਦਲਣਾ",
        "opinions|2:1|2|w4": "ਖੁੱਲ੍ਹੇ ਵਿਚਾਰਾਂ ਵਾਲਾ",
        "opinions|2:1|2|w5": "ਆਪੋ-ਆਪਣੀ ਰਾਇ ਰੱਖਣਾ",
        "opinions|2:1|3|p0": "ਪੂਰੇ ਸਤਿਕਾਰ ਨਾਲ, ਸਰ, ਮੇਰੇ ਖ਼ਿਆਲ ਵਿੱਚ ਅੰਕੜੇ ਕੁਝ ਹੋਰ ਹੀ ਕਹਿੰਦੇ ਹਨ।",
        "opinions|2:1|3|p1": "ਮੇਰੀ ਰਾਇ ਵੱਖਰੀ ਹੈ; ਪੁਰਾਣੇ ਬਾਜ਼ਾਰ ਵਿੱਚ ਮਾਲ ਨਾਲੋਂ ਕਿਤੇ ਵੱਧ ਰੌਣਕ ਹੈ।",
        "opinions|2:1|3|p2": "ਦੋਵਾਂ ਪੱਖਾਂ ਦੀ ਗੱਲ ਸੁਣ ਕੇ, ਪ੍ਰਿੰਸੀਪਲ ਆਪਣੇ ਫ਼ੈਸਲੇ ਉੱਤੇ ਦੁਬਾਰਾ ਸੋਚਣ ਲਈ ਮੰਨ ਗਏ।",
        "opinions|2:1|3|p3": "ਪਹਿਲਾਂ ਉਹ ਟ੍ਰਿਪ ਦੇ ਖ਼ਿਲਾਫ਼ ਸੀ, ਪਰ ਫਿਰ ਉਸ ਦਾ ਮਨ ਬਦਲ ਗਿਆ।",
        "opinions|2:1|3|p4": "ਅਸੀਂ ਦੋਵੇਂ ਖੁੱਲ੍ਹੇ ਵਿਚਾਰਾਂ ਵਾਲੇ ਹਾਂ, ਇਸ ਲਈ ਅਸੀਂ ਆਪੋ-ਆਪਣੀ ਰਾਇ ਰੱਖ ਕੇ ਗੱਲ ਮੁਕਾ ਸਕਦੇ ਹਾਂ।",
        "opinions|2:1|4|title": "ਸਕੂਲ ਦਾ ਆਖ਼ਰੀ ਟੂਰ",
        "opinions|2:1|4|text": "ਹਾਸਨ ਵਿੱਚ ਬਾਰ੍ਹਵੀਂ ਜਮਾਤ ਨੇ ਆਪਣੇ ਆਖ਼ਰੀ ਸਕੂਲ ਟੂਰ ਲਈ ਕੋਈ ਥਾਂ ਚੁਣਨੀ ਸੀ। ਨਿਖਿਲ ਸਮੁੰਦਰ ਕੰਢੇ ਲਈ ਗੋਕਰਣ ਜਾਣਾ ਚਾਹੁੰਦਾ ਸੀ, ਪਰ ਦਿਵਿਆ ਇਤਿਹਾਸ ਲਈ ਹੰਪੀ ਜਾਣਾ ਚਾਹੁੰਦੀ ਸੀ। ਸ਼ੁਰੂ ਵਿੱਚ ਦੋਵੇਂ ਇੱਕ-ਮੱਤ ਨਹੀਂ ਸਨ, ਅਤੇ ਗੱਲਬਾਤ ਉੱਚੀ ਹੋ ਗਈ। ਫਿਰ ਦਿਵਿਆ ਨੇ ਕਿਹਾ, 'ਪੂਰੇ ਸਤਿਕਾਰ ਨਾਲ, ਸਮੁੰਦਰ ਕੰਢਾ ਮਜ਼ੇਦਾਰ ਹੈ, ਪਰ ਹੰਪੀ ਅਜਿਹੀ ਚੀਜ਼ ਹੈ ਜੋ ਸਾਨੂੰ ਸਾਰੀ ਉਮਰ ਯਾਦ ਰਹੇਗੀ।' ਨਿਖਿਲ ਨੇ ਮੰਨਿਆ ਕਿ ਉਸ ਦੀ ਗੱਲ ਜਾਇਜ਼ ਹੈ, ਪਰ ਉਸ ਨੂੰ ਗਰਮੀ ਦੀ ਚਿੰਤਾ ਸੀ। ਉਨ੍ਹਾਂ ਦੇ ਅਧਿਆਪਕ ਨੇ ਸਾਂਝੀ ਗੱਲ ਲੱਭਣ ਵਿੱਚ ਮਦਦ ਕੀਤੀ: ਉਹ ਠੰਢੀ ਸਵੇਰ ਵਿੱਚ ਹੰਪੀ ਘੁੰਮਣਗੇ ਅਤੇ ਦੁਪਹਿਰ ਨੂੰ ਤੁੰਗਭੱਦਰਾ ਨਦੀ ਕੰਢੇ ਆਰਾਮ ਕਰਨਗੇ। ਅਖ਼ੀਰ ਨਿਖਿਲ ਦਾ ਮਨ ਬਦਲ ਗਿਆ ਅਤੇ ਉਸ ਨੇ ਖ਼ੁਦ ਹੰਪੀ ਲਈ ਵੋਟ ਪਾਈ। ਇੱਕ ਮਹੀਨੇ ਬਾਅਦ ਸਾਰੇ ਸਹਿਮਤ ਸਨ ਕਿ ਇਹ ਉਨ੍ਹਾਂ ਦਾ ਹੁਣ ਤੱਕ ਦਾ ਸਭ ਤੋਂ ਵਧੀਆ ਟੂਰ ਸੀ।",
        "opinions|2:1|4|q0": "ਨਿਖਿਲ ਗੋਕਰਣ ਕਿਉਂ ਜਾਣਾ ਚਾਹੁੰਦਾ ਸੀ?",
        "opinions|2:1|4|q0o0": "ਸਮੁੰਦਰ ਕੰਢੇ ਲਈ",
        "opinions|2:1|4|q0o1": "ਮੰਦਰਾਂ ਲਈ",
        "opinions|2:1|4|q0o2": "ਖਾਣੇ ਲਈ",
        "opinions|2:1|4|q0o3": "ਟ੍ਰੈਕਿੰਗ ਲਈ",
        "opinions|2:1|4|q1": "ਨਿਖਿਲ ਨੂੰ ਕਿਸ ਗੱਲ ਦੀ ਚਿੰਤਾ ਸੀ?",
        "opinions|2:1|4|q1o0": "ਗਰਮੀ ਦੀ",
        "opinions|2:1|4|q1o1": "ਖ਼ਰਚੇ ਦੀ",
        "opinions|2:1|4|q1o2": "ਬੱਸ ਦੇ ਲੰਬੇ ਸਫ਼ਰ ਦੀ",
        "opinions|2:1|4|q1o3": "ਮੀਂਹ ਦੀ",
        "opinions|2:1|4|q2": "ਅਧਿਆਪਕ ਨੇ ਕਿਹੜੀ ਯੋਜਨਾ ਉੱਤੇ ਸਹਿਮਤੀ ਬਣਾਉਣ ਵਿੱਚ ਮਦਦ ਕੀਤੀ?",
        "opinions|2:1|4|q2o0": "ਸਵੇਰੇ ਹੰਪੀ, ਦੁਪਹਿਰ ਨੂੰ ਨਦੀ ਕੰਢੇ ਆਰਾਮ",
        "opinions|2:1|4|q2o1": "ਇੱਕ ਦਿਨ ਗੋਕਰਣ ਅਤੇ ਇੱਕ ਦਿਨ ਹੰਪੀ",
        "opinions|2:1|4|q2o2": "ਹਾਸਨ ਵਿੱਚ ਰਹਿ ਕੇ ਅਜਾਇਬ-ਘਰ ਦੇਖਣਾ",
        "opinions|2:1|4|q2o3": "ਹੰਪੀ ਸਿਰਫ਼ ਰਾਤ ਨੂੰ ਦੇਖਣਾ",
        "opinions|2:1|5|title": "ਕਾਲਜ ਫ਼ੈਸਟ ਦੀ ਯੋਜਨਾ",
        "opinions|2:1|5|scenario": "ਮੰਗਲੁਰੂ ਦੇ ਇੱਕ ਕਾਲਜ ਦੀ ਫ਼ੈਸਟ ਕਮੇਟੀ ਦੇ ਦੋ ਵਿਦਿਆਰਥੀ, ਪੂਜਾ ਅਤੇ ਸਮੀਰ, ਪੈਸੇ ਖ਼ਰਚਣ ਦੇ ਤਰੀਕੇ ਬਾਰੇ ਅਸਹਿਮਤ ਹਨ।",
        "opinions|2:1|5|l0": "ਸਮੀਰ, ਮੈਂ ਸੁਣਿਆ ਹੈ ਕਿ ਤੂੰ ਕਾਲਜ ਫ਼ੈਸਟ ਵਿੱਚ ਕਿਸੇ ਫ਼ਿਲਮ ਸਟਾਰ ਨੂੰ ਬੁਲਾਉਣਾ ਚਾਹੁੰਦਾ ਹੈਂ। ਕੀ ਇਹ ਸੱਚ ਹੈ?",
        "opinions|2:1|5|l1": "ਹਾਂ! ਵੱਡਾ ਨਾਂ ਬਹੁਤ ਭੀੜ ਖਿੱਚੇਗਾ। ਕੀ ਤੈਨੂੰ ਨਹੀਂ ਲੱਗਦਾ?",
        "opinions|2:1|5|l2": "ਕੁਝ ਹੱਦ ਤੱਕ, ਹਾਂ। ਪਰ ਪੂਰੇ ਸਤਿਕਾਰ ਨਾਲ, ਸਟਾਰ ਦੀ ਫ਼ੀਸ ਸਾਡੇ ਅੱਧੇ ਪੈਸੇ ਖਾ ਜਾਵੇਗੀ।",
        "opinions|2:1|5|l3": "ਇਹ ਜਾਇਜ਼ ਗੱਲ ਹੈ। ਫਿਰ ਵੀ, ਸਟਾਰ ਤੋਂ ਬਿਨਾਂ ਫ਼ੈਸਟ ਥੋੜ੍ਹਾ ਫਿੱਕਾ ਲੱਗਦਾ ਹੈ।",
        "opinions|2:1|5|l4": "ਮੇਰੀ ਰਾਇ ਵੱਖਰੀ ਹੈ। ਪਿਛਲੇ ਸਾਲ ਉਡੁਪੀ ਦੀ ਯਕਸ਼ਗਾਨ ਮੰਡਲੀ ਫ਼ੈਸਟ ਦਾ ਸਭ ਤੋਂ ਵਧੀਆ ਹਿੱਸਾ ਸੀ।",
        "opinions|2:1|5|l5": "ਹੰਮ, ਉਸ ਸ਼ੋਅ ਬਾਰੇ ਮੈਂ ਪੂਰੀ ਤਰ੍ਹਾਂ ਸਹਿਮਤ ਹਾਂ। ਅਖ਼ੀਰ ਵਿੱਚ ਸਾਰੇ ਨੱਚ ਰਹੇ ਸਨ।",
        "opinions|2:1|5|l6": "ਤਾਂ ਕਿਉਂ ਨਾ ਉਨ੍ਹਾਂ ਨੂੰ ਫਿਰ ਬੁਲਾਈਏ ਅਤੇ ਬਾਕੀ ਪੈਸੇ ਵਧੀਆ ਖਾਣੇ ਅਤੇ ਲਾਈਟਾਂ ਉੱਤੇ ਖ਼ਰਚੀਏ?",
        "opinions|2:1|5|l7": "ਚੱਲ ਠੀਕ ਹੈ, ਤੂੰ ਮੇਰਾ ਮਨ ਬਦਲ ਦਿੱਤਾ। ਮੈਂ ਦੁਬਾਰਾ ਸੋਚਾਂਗਾ ਅਤੇ ਕੱਲ੍ਹ ਕਮੇਟੀ ਨਾਲ ਗੱਲ ਕਰਾਂਗਾ।",
        "opinions|2:1|5|l8": "ਇੰਨੇ ਖੁੱਲ੍ਹੇ ਵਿਚਾਰਾਂ ਵਾਲਾ ਹੋਣ ਲਈ ਸ਼ੁਕਰੀਆ। ਮੈਨੂੰ ਪਤਾ ਹੈ ਇਹ ਤੇਰਾ ਮਨਪਸੰਦ ਵਿਚਾਰ ਸੀ।",
        "opinions|2:1|5|l9": "ਖ਼ੈਰ, ਕਿਹੜਾ ਫ਼ਿਲਮ ਸਟਾਰ ਸਭ ਤੋਂ ਵਧੀਆ ਹੈ, ਇਸ ਬਾਰੇ ਆਪਾਂ ਆਪੋ-ਆਪਣੀ ਰਾਇ ਰੱਖ ਸਕਦੇ ਹਾਂ!",
        "opinions|2:1|5|q0": "ਸਮੀਰ ਫ਼ੈਸਟ ਲਈ ਕੀ ਚਾਹੁੰਦਾ ਸੀ?",
        "opinions|2:1|5|q0o0": "ਕਿਸੇ ਫ਼ਿਲਮ ਸਟਾਰ ਨੂੰ ਬੁਲਾਉਣਾ",
