        "opinions|4:1|1|p0": "ਕਾਸ਼ ਮੈਂ ਆਪਣੇ ਦਾਦਾ ਜੀ ਨਾਲ ਹੋਰ ਸਮਾਂ ਬਿਤਾਇਆ ਹੁੰਦਾ।",
        "opinions|4:1|1|p1": "ਮੇਰਾ ਇੱਕੋ-ਇੱਕ ਪਛਤਾਵਾ ਇਹ ਹੈ ਕਿ ਮੈਂ ਕਦੇ ਤੈਰਨਾ ਨਹੀਂ ਸਿੱਖਿਆ।",
        "opinions|4:1|1|p2": "ਕਾਸ਼ ਮੈਂ ਆਪਣੀ ਮਾਂ ਦੀ ਗੱਲ ਸੁਣੀ ਹੁੰਦੀ, ਤਾਂ ਹੁਣ ਮੀਂਹ ਵਿੱਚ ਨਾ ਫਸਿਆ ਹੁੰਦਾ।",
        "opinions|4:1|1|p3": "ਹੁਣ ਪਿੱਛੇ ਮੁੜ ਕੇ ਦੇਖਾਂ ਤਾਂ ਮੈਨੂੰ ਕਾਮਰਸ ਦੀ ਥਾਂ ਸਾਇੰਸ ਚੁਣਨੀ ਚਾਹੀਦੀ ਸੀ।",
