        "opinions|4:1|3|p0": "ਮੈਂ ਇਸ ਦੀਵਾਲੀ ਉੱਤੇ ਵਾਰਾਣਸੀ ਵਿੱਚ ਆਪਣੇ ਚਚੇਰੇ ਭੈਣ-ਭਰਾਵਾਂ ਨੂੰ ਮਿਲਣ ਦੀ ਬੇਸਬਰੀ ਨਾਲ ਉਡੀਕ ਕਰ ਰਿਹਾ ਹਾਂ।",
        "opinions|4:1|3|p1": "ਦੁਬਈ ਵਿੱਚ ਦੋ ਸਾਲ ਰਹਿਣ ਤੋਂ ਬਾਅਦ ਉਸ ਨੂੰ ਆਪਣੇ ਪਿੰਡ ਦੀ ਡੂੰਘੀ ਤਾਂਘ ਮਹਿਸੂਸ ਹੋਈ।",
        "opinions|4:1|3|p2": "ਨਤੀਜੇ ਕੱਲ੍ਹ ਆਉਣਗੇ, ਪਰ ਮੈਂ ਕਾਫ਼ੀ ਆਸ਼ਾਵਾਦੀ ਹਾਂ, ਰੱਬ ਖ਼ੈਰ ਕਰੇ!",
        "opinions|4:1|3|p3": "ਛੁੱਟੀਆਂ ਦੇ ਦਿਨੇ ਸੁਪਨੇ ਦੇਖਣੇ ਬੰਦ ਕਰੋ ਅਤੇ ਪਹਿਲਾਂ ਆਪਣਾ ਪ੍ਰੋਜੈਕਟ ਪੂਰਾ ਕਰੋ।",
        "opinions|4:1|3|p4": "ਮੈਚ ਹਾਰਨਾ ਦੁਖਦਾਈ ਸੀ, ਪਰ ਆਸ ਦੀ ਕਿਰਨ ਇਹ ਹੈ ਕਿ ਅਸੀਂ ਬਹੁਤ ਕੁਝ ਸਿੱਖਿਆ।",
        "opinions|4:1|4|title": "ਪੈਂਹਠ ਸਾਲ ਦੀ ਉਮਰ ਵਿੱਚ ਦੂਜਾ ਮੌਕਾ",
        "opinions|4:1|4|text": "ਵੈਂਕਟੇਸ਼ ਪੈਂਹਠ ਸਾਲਾਂ ਦਾ ਹੈ ਅਤੇ ਮੈਸੂਰੂ ਵਿੱਚ ਮਹਿਲ ਦੇ ਨੇੜੇ ਇਕੱਲਾ ਰਹਿੰਦਾ ਹੈ। ਜਵਾਨੀ ਵਿੱਚ ਉਸ ਕੋਲ ਚੇਨਈ ਵਿੱਚ ਸੰਗੀਤ ਪੜ੍ਹਨ ਦਾ ਮੌਕਾ ਸੀ, ਪਰ ਉਸ ਨੇ ਉਸ ਦੀ ਥਾਂ ਬੈਂਕ ਦੀ ਪੱਕੀ ਨੌਕਰੀ ਚੁਣ ਲਈ। ਸਾਲਾਂ ਤੱਕ ਉਹ ਆਪਣੇ ਆਪ ਨੂੰ ਕਹਿੰਦਾ ਰਿਹਾ ਕਿ ਕੋਈ ਗੱਲ ਨਹੀਂ, ਪਰ ਦਿਲ ਵਿੱਚ ਹਮੇਸ਼ਾ ਇੱਕ ਚੁੱਪ ਪਛਤਾਵਾ ਰਿਹਾ। ਉਹ ਆਪਣੀ ਧੀ ਲਕਸ਼ਮੀ ਨੂੰ ਕਹਿੰਦਾ ਹੁੰਦਾ ਸੀ, 'ਕਾਸ਼ ਮੈਂ ਥੋੜ੍ਹਾ ਹੋਰ ਹੌਸਲਾ ਕੀਤਾ ਹੁੰਦਾ।' ਪਿਛਲੇ ਸਾਲ ਲਕਸ਼ਮੀ ਨੇ ਵੱਡਿਆਂ ਲਈ ਸ਼ਾਮ ਦੀ ਇੱਕ ਸੰਗੀਤ ਕਲਾਸ ਲੱਭੀ ਅਤੇ ਜਨਮਦਿਨ ਦੇ ਤੋਹਫ਼ੇ ਵਜੋਂ ਉਸ ਦਾ ਨਾਂ ਲਿਖਵਾ ਦਿੱਤਾ। ਪਹਿਲਾਂ ਉਹ ਹੱਸਿਆ ਅਤੇ ਇਸ ਨੂੰ ਖ਼ਿਆਲੀ ਪੁਲਾਅ ਕਿਹਾ, ਪਰ ਲਕਸ਼ਮੀ ਨੇ ਉਸ ਨੂੰ ਹਾਰ ਨਹੀਂ ਮੰਨਣ ਦਿੱਤੀ। ਹੁਣ ਉਹ ਹਰ ਸਵੇਰ ਵੀਣਾ ਦਾ ਰਿਆਜ਼ ਕਰਦਾ ਹੈ ਅਤੇ ਮਾਰਚ ਵਿੱਚ ਆਪਣੇ ਪਹਿਲੇ ਛੋਟੇ ਜਿਹੇ ਕੰਸਰਟ ਦੀ ਬੇਸਬਰੀ ਨਾਲ ਉਡੀਕ ਕਰ ਰਿਹਾ ਹੈ। ਉਹ ਕਹਿੰਦਾ ਹੈ, 'ਮੈਂ ਬੀਤਿਆ ਸਮਾਂ ਨਹੀਂ ਬਦਲ ਸਕਦਾ, ਪਰ ਮੈਂ ਖ਼ੁਸ਼ ਹਾਂ ਕਿ ਆਖ਼ਰ ਮੈਨੂੰ ਦੂਜਾ ਮੌਕਾ ਮਿਲ ਗਿਆ।'",
        "opinions|4:1|4|q0": "ਜਵਾਨੀ ਵਿੱਚ ਵੈਂਕਟੇਸ਼ ਨੇ ਕਿਹੜਾ ਮੌਕਾ ਗੁਆਇਆ?",
        "opinions|4:1|4|q0o0": "ਚੇਨਈ ਵਿੱਚ ਸੰਗੀਤ ਪੜ੍ਹਨ ਦਾ",
        "opinions|4:1|4|q0o1": "ਮੁੰਬਈ ਦੇ ਇੱਕ ਬੈਂਕ ਵਿੱਚ ਕੰਮ ਕਰਨ ਦਾ",
        "opinions|4:1|4|q0o2": "ਕਰਨਾਟਕ ਲਈ ਕ੍ਰਿਕਟ ਖੇਡਣ ਦਾ",
        "opinions|4:1|4|q0o3": "ਵਿਦੇਸ਼ ਵਿੱਚ ਡਾਕਟਰੀ ਪੜ੍ਹਨ ਦਾ",
        "opinions|4:1|4|q1": "ਲਕਸ਼ਮੀ ਨੇ ਉਸ ਨੂੰ ਕਿਵੇਂ ਹੈਰਾਨ ਕੀਤਾ?",
        "opinions|4:1|4|q1o0": "ਸੰਗੀਤ ਕਲਾਸ ਵਿੱਚ ਉਸ ਦਾ ਨਾਂ ਲਿਖਵਾ ਦਿੱਤਾ",
        "opinions|4:1|4|q1o1": "ਉਸ ਲਈ ਨਵਾਂ ਘਰ ਖ਼ਰੀਦਿਆ",
        "opinions|4:1|4|q1o2": "ਉਸ ਨੂੰ ਚੇਨਈ ਲੈ ਗਈ",
        "opinions|4:1|4|q1o3": "ਇੱਕ ਵੱਡੀ ਪਾਰਟੀ ਰੱਖੀ",
        "opinions|4:1|4|q2": "ਵੈਂਕਟੇਸ਼ ਕਿਸ ਚੀਜ਼ ਦੀ ਬੇਸਬਰੀ ਨਾਲ ਉਡੀਕ ਕਰ ਰਿਹਾ ਹੈ?",
        "opinions|4:1|4|q2o0": "ਮਾਰਚ ਵਿੱਚ ਆਪਣੇ ਪਹਿਲੇ ਛੋਟੇ ਕੰਸਰਟ ਦੀ",
        "opinions|4:1|4|q2o1": "ਚੇਨਈ ਦੀ ਯਾਤਰਾ ਦੀ",
        "opinions|4:1|4|q2o2": "ਨਵੀਂ ਵੀਣਾ ਖ਼ਰੀਦਣ ਦੀ",
        "opinions|4:1|4|q2o3": "ਲਕਸ਼ਮੀ ਦੇ ਵਿਆਹ ਦੀ",
        "opinions|4:1|5|title": "ਨਤੀਜਿਆਂ ਤੋਂ ਬਾਅਦ",
        "opinions|4:1|5|scenario": "ਇਮਰਾਨ ਨੇ ਹੁਣੇ ਆਪਣੇ ਦਾਖ਼ਲਾ ਇਮਤਿਹਾਨ ਦਾ ਨਤੀਜਾ ਦੇਖਿਆ ਹੈ। ਉਸ ਦੀ ਸਹੇਲੀ ਕਵਿਤਾ ਉਸ ਨੂੰ ਕਲਬੁਰਗੀ ਵਿੱਚ ਲਾਇਬ੍ਰੇਰੀ ਦੇ ਬਾਹਰ ਮਿਲਦੀ ਹੈ।",
        "opinions|4:1|5|l0": "ਇਮਰਾਨ, ਤੂੰ ਪਰੇਸ਼ਾਨ ਲੱਗਦਾ ਹੈਂ। ਕੀ ਦਾਖ਼ਲਾ ਇਮਤਿਹਾਨ ਦਾ ਨਤੀਜਾ ਆ ਗਿਆ?",
        "opinions|4:1|5|l1": "ਹਾਂ। ਮੈਂ ਕੱਟ-ਆਫ਼ ਤੋਂ ਸਿਰਫ਼ ਚਾਰ ਨੰਬਰਾਂ ਨਾਲ ਰਹਿ ਗਿਆ। ਕਾਸ਼ ਮੈਂ ਤਿਆਰੀ ਪਹਿਲਾਂ ਸ਼ੁਰੂ ਕੀਤੀ ਹੁੰਦੀ।",
        "opinions|4:1|5|l2": "ਮੈਨੂੰ ਬਹੁਤ ਅਫ਼ਸੋਸ ਹੈ। ਪਰ ਚਾਰ ਨੰਬਰ ਤਾਂ ਬਹੁਤ ਨੇੜੇ ਹਨ। ਸਾਫ਼ ਹੈ ਕਿ ਤੈਨੂੰ ਆਪਣੇ ਵਿਸ਼ੇ ਆਉਂਦੇ ਹਨ।",
        "opinions|4:1|5|l3": "ਕਾਸ਼ ਮੈਂ ਉਹ ਦੋ ਮਹੀਨੇ ਵੀਡੀਓ ਗੇਮਾਂ ਉੱਤੇ ਬਰਬਾਦ ਨਾ ਕੀਤੇ ਹੁੰਦੇ!",
        "opinions|4:1|5|l4": "ਪਿੱਛੋਂ ਦੇਖਿਆਂ ਸਭ ਕੁਝ ਸਾਫ਼ ਲੱਗਦਾ ਹੈ। ਹੁਣ ਤੂੰ ਇਸ ਨੂੰ ਬਦਲ ਨਹੀਂ ਸਕਦਾ, ਇਸ ਲਈ ਇਸ ਨੂੰ ਭੁਲਾਉਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰ।",
        "opinions|4:1|5|l5": "ਮੈਨੂੰ ਪਤਾ ਹੈ, ਪਰ ਮੇਰੇ ਮਾਪਿਆਂ ਨੂੰ ਬਹੁਤ ਉਮੀਦਾਂ ਸਨ। ਮੈਨੂੰ ਲੱਗਦਾ ਹੈ ਮੈਂ ਉਨ੍ਹਾਂ ਨੂੰ ਨਿਰਾਸ਼ ਕੀਤਾ ਹੈ।",
        "opinions|4:1|5|l6": "ਉਨ੍ਹਾਂ ਨਾਲ ਖੁੱਲ੍ਹ ਕੇ ਗੱਲ ਕਰ। ਤੂੰ ਅਗਲੇ ਸਾਲ ਦੁਬਾਰਾ ਇਮਤਿਹਾਨ ਦੇ ਸਕਦਾ ਹੈਂ; ਇਹ ਦੂਜਾ ਮੌਕਾ ਹੈ।",
        "opinions|4:1|5|l7": "ਇਹ ਸੱਚ ਹੈ। ਅਤੇ ਇਸ ਵਾਰ ਮੈਂ ਪਹਿਲੇ ਦਿਨ ਤੋਂ ਹੀ ਪੱਕੀ ਸਮਾਂ-ਸਾਰਣੀ ਬਣਾਵਾਂਗਾ।",
        "opinions|4:1|5|l8": "ਦੇਖਿਆ? ਆਸ ਦੀ ਕਿਰਨ ਹੁਣੇ ਤੋਂ ਦਿਸ ਰਹੀ ਹੈ। ਮੈਨੂੰ ਤੇਰੇ ਬਾਰੇ ਪੂਰੀ ਉਮੀਦ ਹੈ।",
        "opinions|4:1|5|l9": "ਸ਼ੁਕਰੀਆ ਕਵਿਤਾ। ਸੱਚ ਪੁੱਛੇਂ ਤਾਂ ਮੈਂ ਅਗਲੇ ਸਾਲ ਆਪਣੇ ਆਪ ਨੂੰ ਸਾਬਤ ਕਰਨ ਦੀ ਬੇਸਬਰੀ ਨਾਲ ਉਡੀਕ ਕਰ ਰਿਹਾ ਹਾਂ।",
        "opinions|4:1|5|q0": "ਇਮਰਾਨ ਕੱਟ-ਆਫ਼ ਤੋਂ ਕਿੰਨੇ ਨੰਬਰਾਂ ਨਾਲ ਰਹਿ ਗਿਆ?",
