        "opinions|4:1|5|q2": "ਅਗਲੀ ਵਾਰ ਇਮਰਾਨ ਕੀ ਵੱਖਰਾ ਕਰੇਗਾ?",
        "opinions|4:1|5|q2o0": "ਪਹਿਲੇ ਦਿਨ ਤੋਂ ਪੱਕੀ ਸਮਾਂ-ਸਾਰਣੀ ਬਣਾਏਗਾ",
        "opinions|4:1|5|q2o1": "ਮਹਿੰਗੀ ਕੋਚਿੰਗ ਕਲਾਸ ਲਵੇਗਾ",
