        "opinions|6:1|0|w0": "ਸੁਝਾਅ",
        "opinions|6:1|0|w1": "ਇੱਕ ਸਲਾਹ",
        "opinions|6:1|0|w2": "ਜੇ ਮੈਂ ਤੁਹਾਡੀ ਥਾਂ ਹੁੰਦਾ",
        "opinions|6:1|0|w3": "ਤੁਹਾਡੇ ਲਈ ਚੰਗਾ ਹੈ ਕਿ",
        "opinions|6:1|0|w4": "ਤੁਸੀਂ ਕਿਉਂ ਨਹੀਂ",
        "opinions|6:1|0|w5": "ਮੋਟਾ ਨਿਯਮ",
        "opinions|6:1|1|p0": "ਸੁਝਾਅ ਲਈ ਸ਼ੁਕਰੀਆ; ਮੈਂ ਇਸ ਹਫ਼ਤੇ ਇਸ ਨੂੰ ਅਜ਼ਮਾਵਾਂਗਾ।",
        "opinions|6:1|1|p1": "ਇੱਕ ਸਲਾਹ: ਜਿਹੜਾ ਦਸਤਾਵੇਜ਼ ਤੁਸੀਂ ਪੜ੍ਹਿਆ ਨਾ ਹੋਵੇ, ਉਸ ਉੱਤੇ ਕਦੇ ਦਸਤਖ਼ਤ ਨਾ ਕਰੋ।",
        "opinions|6:1|1|p2": "ਜੇ ਮੈਂ ਤੁਹਾਡੀ ਥਾਂ ਹੁੰਦਾ, ਤਾਂ ਗੱਲ ਵਧਣ ਤੋਂ ਪਹਿਲਾਂ ਉਸ ਤੋਂ ਮਾਫ਼ੀ ਮੰਗ ਲੈਂਦਾ।",
        "opinions|6:1|1|p3": "ਤੁਹਾਡੇ ਲਈ ਚੰਗਾ ਹੈ ਕਿ ਹੁਣੇ ਨਿਕਲ ਜਾਓ, ਨਹੀਂ ਤਾਂ ਹਾਸਨ ਦੀ ਆਖ਼ਰੀ ਬੱਸ ਨਿਕਲ ਜਾਵੇਗੀ।",
        "opinions|6:1|1|p4": "ਤੁਸੀਂ ਮੇਰੇ ਨਾਲ ਕੱਬਨ ਪਾਰਕ ਦੇ ਸਵੇਰ ਦੀ ਸੈਰ ਵਾਲੇ ਗਰੁੱਪ ਵਿੱਚ ਕਿਉਂ ਨਹੀਂ ਸ਼ਾਮਲ ਹੋ ਜਾਂਦੇ?",
        "opinions|6:1|2|w0": "ਦੁਬਿਧਾ",
        "opinions|6:1|2|w1": "ਦੋ ਚੀਜ਼ਾਂ ਵਿਚਕਾਰ ਫਸਿਆ ਹੋਣਾ",
        "opinions|6:1|2|w2": "ਸਲਾਹਕਾਰ",
        "opinions|6:1|2|w3": "ਧਿਆਨ ਦੇਣਾ",
        "opinions|6:1|2|w4": "ਸੋਚ-ਵਿਚਾਰ ਕਰਨਾ",
        "opinions|6:1|2|w5": "ਪੂਰਾ ਯਕੀਨ ਕੀਤੇ ਬਿਨਾਂ",
        "opinions|6:1|3|p0": "ਮੈਂ ਸੱਚਮੁੱਚ ਦੁਬਿਧਾ ਵਿੱਚ ਹਾਂ: ਪੁਣੇ ਵਾਲੀ ਨੌਕਰੀ ਲਵਾਂ ਜਾਂ ਘਰ ਹੀ ਰਹਾਂ?",
        "opinions|6:1|3|p1": "ਉਹ ਕਲਾ ਦੀ ਪੜ੍ਹਾਈ ਅਤੇ ਪਰਿਵਾਰਕ ਕਾਰੋਬਾਰ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਣ ਵਿਚਕਾਰ ਫਸੀ ਹੋਈ ਹੈ।",
        "opinions|6:1|3|p2": "ਜਦੋਂ ਵੀ ਮੈਂ ਕੋਈ ਵੱਡਾ ਫ਼ੈਸਲਾ ਕਰਨਾ ਹੋਵੇ, ਮੇਰੇ ਚਾਚਾ ਜੀ ਬਹੁਤ ਵਧੀਆ ਸਲਾਹਕਾਰ ਹਨ।",
        "opinions|6:1|3|p3": "ਉਸ ਨੇ ਡਾਕਟਰ ਦੀ ਚਿਤਾਵਨੀ ਉੱਤੇ ਧਿਆਨ ਨਹੀਂ ਦਿੱਤਾ ਅਤੇ ਫਿਰ ਬਿਮਾਰ ਹੋ ਗਿਆ।",
        "opinions|6:1|3|p4": "ਧਿਆਨ ਨਾਲ ਸੋਚ-ਵਿਚਾਰ ਕਰੋ, ਅਤੇ ਆਨਲਾਈਨ ਰਿਵਿਊਆਂ ਉੱਤੇ ਪੂਰਾ ਯਕੀਨ ਨਾ ਕਰੋ।",
        "opinions|6:1|4|title": "ਦਾਦੀ ਦੀ ਸਲਾਹ",
        "opinions|6:1|4|text": "ਉਡੁਪੀ ਦੀ ਸਨੇਹਾ ਦੁਬਿਧਾ ਵਿੱਚ ਸੀ: ਉਸ ਨੂੰ ਅਹਿਮਦਾਬਾਦ ਦੇ ਇੱਕ ਡਿਜ਼ਾਈਨ ਕਾਲਜ ਵਿੱਚ ਦਾਖ਼ਲਾ ਮਿਲ ਗਿਆ ਸੀ, ਪਰ ਉਸ ਦੇ ਮਾਪੇ ਚਾਹੁੰਦੇ ਸਨ ਕਿ ਉਹ ਘਰ ਦੇ ਨੇੜੇ ਪੜ੍ਹੇ। ਉਹ ਆਪਣੇ ਸੁਪਨੇ ਅਤੇ ਪਰਿਵਾਰ ਵਿਚਕਾਰ ਫਸੀ ਹੋਈ ਸੀ, ਇਸ ਲਈ ਉਹ ਆਪਣੀ ਦਾਦੀ ਕੋਲ ਗਈ, ਜੋ ਹਮੇਸ਼ਾ ਉਸ ਦੀ ਸਲਾਹਕਾਰ ਰਹੀ ਸੀ। ਦਾਦੀ ਨੇ ਚੁੱਪਚਾਪ ਸੁਣਿਆ ਅਤੇ ਫਿਰ ਕਿਹਾ, 'ਜੇ ਮੈਂ ਤੇਰੀ ਥਾਂ ਹੁੰਦੀ, ਤਾਂ ਕਾਹਲੀ ਵਿੱਚ ਫ਼ੈਸਲਾ ਨਾ ਕਰਦੀ; ਕੁਝ ਦਿਨ ਸੋਚ-ਵਿਚਾਰ ਕਰ।' ਉਨ੍ਹਾਂ ਨੇ ਰਿਸ਼ਤੇਦਾਰਾਂ ਦੀਆਂ ਗੱਲਾਂ ਬਾਰੇ ਵੀ ਸਨੇਹਾ ਨੂੰ ਇੱਕ ਸਲਾਹ ਦਿੱਤੀ: ਉਨ੍ਹਾਂ ਉੱਤੇ ਪੂਰਾ ਯਕੀਨ ਨਾ ਕਰੀਂ। ਦਾਦੀ ਨੇ ਅੱਗੇ ਕਿਹਾ, 'ਮੇਰਾ ਮੋਟਾ ਨਿਯਮ ਸਿੱਧਾ ਹੈ: ਉਹ ਰਾਹ ਚੁਣ ਜਿਸ ਦਾ ਤੈਨੂੰ ਸੱਠ ਸਾਲ ਦੀ ਉਮਰ ਵਿੱਚ ਪਛਤਾਵਾ ਨਾ ਹੋਵੇ।' ਫਿਰ ਉਨ੍ਹਾਂ ਨੇ ਇੱਕ ਸੁਝਾਅ ਦਿੱਤਾ: 'ਤੂੰ ਆਪਣੇ ਮਾਪਿਆਂ ਨੂੰ ਕਾਲਜ ਦੀ ਵੈੱਬਸਾਈਟ ਅਤੇ ਆਪਣਾ ਪੋਰਟਫ਼ੋਲੀਓ ਕਿਉਂ ਨਹੀਂ ਦਿਖਾਉਂਦੀ?' ਸਨੇਹਾ ਨੇ ਉਨ੍ਹਾਂ ਦੀ ਸਲਾਹ ਉੱਤੇ ਧਿਆਨ ਦਿੱਤਾ, ਅਤੇ ਉਸ ਦਾ ਕੰਮ ਦੇਖ ਕੇ ਉਸ ਦੇ ਮਾਪੇ ਮੰਨ ਗਏ। ਅੱਜ ਉਹ ਹਰ ਐਤਵਾਰ ਦਾਦੀ ਨੂੰ ਫ਼ੋਨ ਕਰਦੀ ਹੈ ਅਤੇ ਆਪਣੀਆਂ ਕਲਾਸਾਂ ਬਾਰੇ ਸਭ ਕੁਝ ਦੱਸਦੀ ਹੈ।",
        "opinions|6:1|4|q0": "ਸਨੇਹਾ ਦੀ ਦੁਬਿਧਾ ਕੀ ਸੀ?",
        "opinions|6:1|4|q0o0": "ਅਹਿਮਦਾਬਾਦ ਵਿੱਚ ਡਿਜ਼ਾਈਨ ਪੜ੍ਹੇ ਜਾਂ ਘਰ ਦੇ ਨੇੜੇ ਰਹੇ",
