        "opinions|6:1|4|q1o0": "ਉਨ੍ਹਾਂ ਉੱਤੇ ਪੂਰਾ ਯਕੀਨ ਨਾ ਕਰ",
        "opinions|6:1|4|q1o1": "ਉਨ੍ਹਾਂ ਨੂੰ ਧਿਆਨ ਨਾਲ ਮੰਨ",
        "opinions|6:1|4|q1o2": "ਉਨ੍ਹਾਂ ਨੂੰ ਲਿਖ ਲੈ",
