        "opinions|6:1|4|q2o2": "ਦਾਦੀ ਦੀ ਗੁੱਸੇ ਭਰੀ ਚਿੱਠੀ ਨਾਲ",
        "opinions|6:1|4|q2o3": "ਵਜ਼ੀਫ਼ੇ ਦੀ ਪੇਸ਼ਕਸ਼ ਨਾਲ",
        "opinions|6:1|5|title": "ਰੌਲਾ ਪਾਉਣ ਵਾਲਾ ਰੂਮਮੇਟ",
        "opinions|6:1|5|scenario": "ਧਾਰਵਾੜ ਵਿੱਚ ਪਹਿਲੇ ਸਾਲ ਦਾ ਵਿਦਿਆਰਥੀ ਦੀਪਕ ਆਪਣੇ ਹੋਸਟਲ ਦੇ ਰੂਮਮੇਟ ਬਾਰੇ ਸਲਾਹ ਲੈਣ ਲਈ ਆਪਣੀ ਵੱਡੀ ਚਚੇਰੀ ਭੈਣ ਸ਼ਾਲਿਨੀ ਨੂੰ ਫ਼ੋਨ ਕਰਦਾ ਹੈ।",
        "opinions|6:1|5|l0": "ਸ਼ਾਲਿਨੀ ਦੀਦੀ, ਕੀ ਮੈਂ ਕਿਸੇ ਗੱਲ ਬਾਰੇ ਤੁਹਾਡੀ ਸਲਾਹ ਲੈ ਸਕਦਾ ਹਾਂ? ਮੈਨੂੰ ਨਹੀਂ ਪਤਾ ਹੋਰ ਕਿਸ ਨਾਲ ਗੱਲ ਕਰਾਂ।",
        "opinions|6:1|5|l1": "ਬਿਲਕੁਲ, ਦੀਪਕ। ਦੱਸ, ਕੀ ਗੱਲ ਹੈ?",
        "opinions|6:1|5|l2": "ਮੇਰਾ ਹੋਸਟਲ ਰੂਮਮੇਟ ਰਾਤ ਦੇ ਦੋ ਵਜੇ ਤੱਕ ਉੱਚੀ ਆਵਾਜ਼ ਵਿੱਚ ਗਾਣੇ ਲਾਉਂਦਾ ਹੈ, ਅਤੇ ਮੈਨੂੰ ਨੀਂਦ ਨਹੀਂ ਆਉਂਦੀ।",
        "opinions|6:1|5|l3": "ਇਹ ਤਾਂ ਥਕਾ ਦੇਣ ਵਾਲਾ ਹੈ। ਕੀ ਤੂੰ ਉਸ ਨੂੰ ਦੱਸਿਆ ਹੈ ਕਿ ਤੈਨੂੰ ਇਸ ਨਾਲ ਕੀ ਤਕਲੀਫ਼ ਹੁੰਦੀ ਹੈ?",
        "opinions|6:1|5|l4": "ਨਹੀਂ। ਮੈਨੂੰ ਡਰ ਹੈ ਕਿ ਸਾਡਾ ਝਗੜਾ ਹੋ ਜਾਵੇਗਾ, ਅਤੇ ਸਾਨੂੰ ਸਾਰਾ ਸਾਲ ਇਕੱਠੇ ਰਹਿਣਾ ਹੈ।",
        "opinions|6:1|5|l5": "ਜੇ ਮੈਂ ਤੇਰੀ ਥਾਂ ਹੁੰਦੀ, ਤਾਂ ਉਸ ਨਾਲ ਸ਼ਾਂਤੀ ਨਾਲ ਗੱਲ ਕਰਦੀ, ਉਸ ਵੇਲੇ ਜਦੋਂ ਤੁਸੀਂ ਦੋਵੇਂ ਆਰਾਮ ਵਿੱਚ ਹੋਵੋ।",
        "opinions|6:1|5|l6": "ਇਹ ਚੰਗਾ ਸੁਝਾਅ ਹੈ। ਪਰ ਮੈਂ ਅਸਲ ਵਿੱਚ ਕਹਾਂ ਕੀ?",
        "opinions|6:1|5|l7": "ਇੱਕ ਚੰਗਾ ਮੋਟਾ ਨਿਯਮ ਇਹ ਹੈ ਕਿ ਆਪਣੀ ਤਕਲੀਫ਼ ਦੀ ਗੱਲ ਕਰ, ਉਸ ਦੀਆਂ ਕਮੀਆਂ ਦੀ ਨਹੀਂ। ਤੂੰ ਗਿਆਰਾਂ ਵਜੇ ਤੋਂ ਬਾਅਦ ਹੈੱਡਫ਼ੋਨ ਵਰਤਣ ਦਾ ਸੁਝਾਅ ਕਿਉਂ ਨਹੀਂ ਦਿੰਦਾ?",
        "opinions|6:1|5|l8": "ਇਹ ਠੀਕ ਲੱਗਦਾ ਹੈ। ਮੈਂ ਸੋਚ-ਵਿਚਾਰ ਕਰਕੇ ਇਸ ਵੀਕਐਂਡ ਉਸ ਨਾਲ ਗੱਲ ਕਰਾਂਗਾ।",
        "opinions|6:1|5|l9": "ਵਧੀਆ। ਅਤੇ ਤੇਰੇ ਲਈ ਚੰਗਾ ਹੈ ਕਿ ਬਹੁਤੀ ਦੇਰ ਨਾ ਕਰੀਂ, ਨਹੀਂ ਤਾਂ ਤੂੰ ਇਮਤਿਹਾਨਾਂ ਵਿੱਚ ਸੌਂ ਜਾਵੇਂਗਾ!",
        "opinions|6:1|5|q0": "ਦੀਪਕ ਦੀ ਸਮੱਸਿਆ ਕੀ ਹੈ?",
        "opinions|6:1|5|q0o0": "ਉਸ ਦਾ ਰੂਮਮੇਟ ਦੇਰ ਰਾਤ ਤੱਕ ਉੱਚੀ ਆਵਾਜ਼ ਵਿੱਚ ਗਾਣੇ ਲਾਉਂਦਾ ਹੈ",
        "opinions|6:1|5|q0o1": "ਉਸ ਦਾ ਰੂਮਮੇਟ ਕਦੇ ਕਮਰਾ ਸਾਫ਼ ਨਹੀਂ ਕਰਦਾ",
