        "society|1:1|1|p4": "ਅੱਜ ਦੀ ਸੰਪਾਦਕੀ ਵਿੱਚ ਦਲੀਲ ਦਿੱਤੀ ਗਈ ਹੈ ਕਿ ਸਾਡੇ ਸ਼ਹਿਰਾਂ ਨੂੰ ਵਧੀਆ ਜਨਤਕ ਆਵਾਜਾਈ ਦੀ ਲੋੜ ਹੈ।",
