        "society|1:1|3|p1": "ਪੁਲਿਸ ਹਾਲੇ ਵੀ ਰੇਲਵੇ ਸਟੇਸ਼ਨ ਨੇੜੇ ਹੋਈ ਘਟਨਾ ਦੀ ਜਾਂਚ ਕਰ ਰਹੀ ਹੈ।",
        "society|1:1|3|p2": "ਪ੍ਰੈੱਸ ਕਾਨਫ਼ਰੰਸ ਵਿੱਚ ਮੰਤਰੀ ਦੀ ਕਹੀ ਗੱਲ ਨੇ ਵੱਡਾ ਵਿਵਾਦ ਛੇੜ ਦਿੱਤਾ।",
